#!/usr/bin/env bash
set -Eeo pipefail
IFS=$'\n\t'
if ((BASH_VERSINFO[0] < 5)); then
	printf '%s\n' "Need bash 5+ (now: $BASH_VERSION)" >&2
	exit 1
fi
shopt -s inherit_errexit lastpipe globstar nullglob
set -o errtrace
unset HISTFILE 2>/dev/null || true

readonly VERSION="1.3"
readonly SAR_VERSION="1"
readonly REPORT_VERSION="4"
readonly TOOL_NAME="CyclePatrol"

readonly C_RED=$'\033[0;31m'
readonly C_GREEN=$'\033[0;32m'
readonly C_YELLOW=$'\033[0;33m'
readonly C_CYAN=$'\033[0;36m'
readonly C_GREY=$'\033[0;90m'
readonly C_BOLD=$'\033[1m'
readonly C_RESET=$'\033[0m'

readonly DEF_IFACE="wlan2"
readonly DEF_SCAN_TIMEOUT=25
readonly DEF_LOG_DIR="/sdcard/Download/wifi"
